/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20071105-5","meetingId":"h19-cm11","date":"2007年11月5日","dateIso":"2007-11-05","committee":"総務委員会","time":"午後１時０３分～午後２時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の基本構想等の策定状況","agenda":"の基本構想等の策定状況","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"もう一つは、１ページに背景のようなものを語っていますけれども、前回のものを見ると、最初につくられた基本理念は人間尊重だとか、そのようなものを受け継いでいくと打ち出されていますけれども、前に２回出された基本構想を受け継いでいって、それを発展しているということなのかどうか、その辺もお聞かせ願いたいと思います。","respondent":"福島長期計画担当課長","answer":"１ページの背景ですけれども、前回の基本構想を受け継いでいるものかですが、こちらでは明記していませんけれども、当然ながら品川区政はずっと続けてきているものですし、前回の基本構想を否定するものではありませんので、それをさらに発展させていくというものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"大綱として示したということですけれども、前回のものを見るとそれぞれに細分化されて、高齢者に対してどういう施策を打っていけばいいのかとかわかりやすいですけれども、今回はパブリックコメントにかけたときに文章上でしか見えてこないというか、自分の勝手な解釈でせざるを得ない部分が強くなってしまうのではないかと思うんです。","respondent":"福島長期計画担当課長","answer":"ただ、２ページの上から５行目ですが、「もとより品川区は、区政の基本的な重点施策である福祉や防災、健康づくりや教育などの水準をさらに向上させるために全力を挙げてまいります」という表現をさせていただきました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"本来、基本構想なわけですから、これは体系の中でこのような言葉が出てくるのはおかしくないと思うんですけれども、基本的な考え方を示す上で、このようなものを普遍の価値と位置づけて守っていく。それから、５ページの第３章で、品川区には１００を超える商店街などの地域の力と産業の振興は、品川区の発展に欠かすことができないものだと言っています。","respondent":"福田企画部長","answer":"基本構想というのは、長期基本計画ですとか総合実施計画のような、一定の期限を想定した行政計画とは異なっていまして、まちづくりの基本的に目指すべきものを、２０年、３０年という想定があるかもしれませんけれども、究極的に今の品川区が置かれた位置を踏まえるならば。","voiceIndex":9,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問・要望","question":"そのとおりだと思うんです。だからこそ、基本構想でしっかりした考えを打ち出すことが必要だと思うんです。今、企画部長が答えてくださった中身からなかなか進まないと思うんですけれども、そのような思いがありますので、改めてそのような視点で、もうこれを出していくわけですから、もう一度変えてくれというわけにいかないかもしれませんけれども、そこをもう一度考えていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"５ページの第３章の都市像の実現に向けてのところでは「自主的・自発的」と順番が変わっています。細かいところですけれども、もう一つ気がついた点は、１０ページの第４章の区政運営の基本姿勢の２番の５行目、「今後機能の拡充が期待される様々な情報媒体や機会を駆使して」というのは、私自身、意味がはっきり読み取れなかったんです。この辺は、このような形にされたということをお伺いしたいと思います。","respondent":"福島長期計画担当課長","answer":"媒体だけではなくて、あらゆる手段を通して行っていきたいということの思いで書いているものです。ただ、わかりにくいというご意見ですが、この辺についても検討していきたいと考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"土井委員","kind":"意見","question":"今、内容についてご説明をいただいたんですけれども、全体的なことで言えば、第５章の最後のところに書いてあることが基本だなと思いました。だから、ある意味ではわかりやすいと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-006"},{"speaker":"武内副委員長","kind":"質問","question":"例えば、２番目の『「都市像の実現に向けて」の中に環境教育を盛り込んだほうがいい』というものは、８ページの「都市像の実現に向けて」の一番下の※に「環境問題への啓発を推進します」と入れてあるのでしょうか、それとも手を加えずに意見としてここに出しているのか、まず教えてください。","respondent":"福島長期計画担当課長","answer":"変更しました大きな点としましては、例えば６ページの「未来を創る子育て・教育都市」となっていますが、品川区基本構想等策定委員会に出した骨子案は「未来を創る教育都市」となっておりましたが。","voiceIndex":15,"id":"exchange-007"},{"speaker":"武内副委員長","kind":"質問","question":"空白になっているところは、例えば審議内容の2)のキャッチフレーズの主な意見を添えて選んでもらうのか、それとも全く新たに区民から出してもらうのか。それを入れ込んだ全文を出すのか、それとも括弧の抜けたまま出すのか、その辺の流れはどのようになっているのでしょうか。","respondent":"福島長期計画担当課長","answer":"ただ、審議内容で出ました主な意見ですけれども、これについても策定委員会ではこういった意見が出ていましたという形でいたします。ただ、それにとらわれることなく、その中で選んでくださいというものではなくて、区民の考えたものを出してくださいという形で募集するものです。","voiceIndex":17,"id":"exchange-008"},{"speaker":"武内副委員長","kind":"質問","question":"パブリックコメントのかけ方で、地域センターとか図書館の区施設で配布するという形ですけれども、当然、ホームページとかＣＡＴＶでもやるということ理解でよろしいでしょうか。","respondent":"福島長期計画担当課長","answer":"こちらに書いてございませんけれども、全文はホームページでも載せていく予定ですし、印刷したものをお配りするものです。ＣＡＴＶでは、パブリックコメントを行っていますというお知らせになります。全文はご容赦いただければと思います。","voiceIndex":19,"id":"exchange-009"}]},{"id":"topic-02","title":"の特別区人事委員会勧告の概要","agenda":"の特別区人事委員会勧告の概要","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"人事委員会勧告ですので、組合との話がどのようになっているのかお聞かせ願いたいと思います。それから、地域手当を１.５％引き上げて、給料月額を同率程度引き下げと書かれていますけれども、そもそも地域手当というのはどのような位置づけで、どのような性格を持ったものなのかお聞かせ願いたいと思います。","respondent":"榎本人事課長","answer":"１点目の組合等の関係ですけれども、人事委員会勧告というのは各区議会議長および各区長あてに勧告されておりますので、それぞれの任命権者の中で、この勧告に対してどのように対応するかという方針が示される中で、一定の職員団体、組合との折衝がされるものと認識しております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"地域手当ですけれども、昔は大都市調整手当で、物価は当然違いますけれども、そうすると１８％に近づけるということで、基本給は引き上げの度合いに関連して引き下げられていくということですか。そうすると、給与水準そのものは下がっていく。例えば、退職金は基本給を軸にして算出されていきますけれども、実質的には生涯給与としては下がらざるを得ない状況がつくり出されるということですか。","respondent":"榎本人事課長","answer":"退職手当につきましては、本給に掛けるという形になっておりますので、現時点での計算でいくと下がる形になりますが、実は退職手当につきましては、去年の第４回定例会で条例を改正いたしましたけれども、職責に基づくポイント制が考慮されておりまして。","voiceIndex":28,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう一つだけ教えていただきたいと思います。２ページにあります初任給のところですけれども、高校卒程度が１４万３,０００円、大学卒程度が１８万１,２００円とあります。とりわけ高卒の１４万３,０００円から社会保険料が引かれると、生活できないのではないかと思うんですけれども、そこを教えていただけますか。","respondent":"榎本人事課長","answer":"これが給料月額になりますので、先ほどの地域手当を入れますと、大卒の場合は２０万４,７００円、高卒ですと１６万１,５９０円、それ以外に住居手当等が入ります。","voiceIndex":30,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"民間に準拠していくという考え方のもとに、このような決められていくのでしょうけれども、今のお話を聞いていると、これから団塊の世代の皆さんが退職されていく中で、新しい方が求められるときに、結果としてそれだけの人材が集まらないことも考えられると思うんですけれども、最後にそこだけ。","respondent":"榎本人事課長","answer":"特に、民間経験をした人の中では、やはり利益がまず第一になってしまうという意見をよく聞きますけれども、そのような考え方を踏まえた上で、新たな職場で働くということも、かなり人材としてはいろいろな視点から検討ができるということで。","voiceIndex":32,"id":"exchange-013"},{"speaker":"土井委員","kind":"質問・要望","question":"私も勉強不足だったんですけれども、給料月額というものと、それが退職金にはね返るのがどの部分なのか、残業手当の計算に何％という場合にはどの部分、要するに民間企業で言う基準内賃金と称するものは退職金にも残業手当にもみんなかかわってくるんですよ、効いてくるんですよという部分と、そういうものには反映しない部分、地域手当というのは両方ともに反映されないんですね。","respondent":"榎本人事課長","answer":"人事委員会の勧告につきましては、実施するかしないかという大前提がありまして、労働基本権の制約のかわりに人事委員会制度を置いてありますので、勧告については実施されるべきものという形で進んでいるものと思います。","voiceIndex":34,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回の調査は企業規模が５０人以上云々という形があって、これがどこまで正確なデータなのかわからないところがあるという気がしますので、その辺の感触がわかれば教えていただきたいと思います。例えば、残業というのでしょうか、超過勤務については上司が命令をするような形で行われて、休日出勤もそういうことに基づいて行われているという認識でよろしいでしょうか。","respondent":"榎本人事課長","answer":"１点目の手当関係ですけれども、確かに扶養手当、住居手当というのは、どちらかというと年功序列的な賃金体系の考え方のもとで出てきた考え方で、昨今の成績主義、実績主義という考え方では、扶養している、していない、住居に入っている。","voiceIndex":36,"id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"今のと関連しますが、基本的なところとしては、職能給的な考え方なのか、それをお聞きしたいと思います。","respondent":"榎本人事課長","answer":"公務員の給与体系というのは、要は実績主義的要素を取り入れてきつつも、ある程度年功的な部分というのは、基本の給料表そのものからは、そういう形で出ているものですし、先ほども給与カーブのフラット化ということで。","voiceIndex":38,"id":"exchange-016"},{"speaker":"原委員","kind":"意見","question":"特別区の採用関係で、民間で言う中途採用を千二、三百人ぐらいが応募されて、そのうち１回目に半分ぐらいしか実際に試験に来られていないという感じのところがあるんですけれども、中途採用を実際に申し込みに来られて、最終的には多分１５倍から２０倍ぐらいの倍率だと思うんですけれども、その辺をお聞かせいただければと思います。","respondent":"榎本人事課長","answer":"まさに今月、ちょうど経験者採用の面接が特別区人事委員会で行われているんですけれども、実際上、２級職と呼ばれる２８歳から３２歳の職群と、主任主事で採用という３２歳から４５歳までの職群の二つで応募を行ったところ。","voiceIndex":40,"id":"exchange-017"},{"speaker":"土井委員","kind":"質問","question":"清掃工場の関係ですとか、その他ここにはいないと言ったらおかしいけれども、品川区だけではない、さまざまな組織形態のものがあるわけですけれども、そういうところはどのような形になっているのでしょうか。","respondent":"榎本人事課長","answer":"給料の関係につきましては、特別区人事委員会の勧告は、それぞれの一部事務組合の管理者に対しても出ておりますので、各区と同じような扱いで勧告が出て、勧告を尊重して、するのかどうかという判断は、それぞれの団体ごとにされるという形です。","voiceIndex":42,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"確認","question":"一つは平等でやったとしていく。と同時に、それにまた上乗せをする形でプラスマイナスをつけていくという、民間とはまた違った意味で必要だと思われますので、一つだけ確認したいのが、ベースはそこにあるのだけれども、こういう考え方を品川区として推進していきますかという確認と、それからこれを具体的にどのような形で展開していくのかお聞かせください。","respondent":"榎本人事課長","answer":"その部分につきましては、今まで懲戒処分、分限処分等の指針が明確にされていない部分がありましたけれども、今、懲戒処分は既につくりまして、分限処分指針につきましても、今検討中ですので、そういうものを整理して、職員に明示していきながら。","voiceIndex":44,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問・要望","question":"民間の視点からすれば、当然のことなんです。頑張った従業員には給料を上げていくというのは、当然の話であって、公務員であるからという前提のもとで、やりにくいことはわかっているけれども、わかっていただきたいのは、頑張った職員に対してプラスアルファをぜひしていただきたいということをずっと言い続けておりますので、そのことをお願いしておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-020"}]},{"id":"topic-03","title":"の戸越体育館改修工事請負契約","agenda":"の戸越体育館改修工事請負契約","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"一つだけ教えていただきたいと思います。アスベストの除去工事というのは、吹き付け材かと思うんですけれども、体育館は室内装飾などに使っている成形板と言われる固いものにアスベスト含有のものが、東京都のマニュアルなどを見てもあるんですけれども、そういうものの調査をやった上でのアスベスト含有材除去工事になっているのか、その辺を教えてください。","respondent":"宍戸施設担当課長","answer":"具体的には、吹き付け材に数％混入しておりまして、平成１７年度に緊急対策ということで対策を打ち出しましたが、大規模改修とあわせて実施したほうが、休館の関係で合理的だろうと思われるものにつきましては、大規模改修にあわせて除去しておりまして。","voiceIndex":53,"id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"ということは、成形板の中に基準を上回るようなアスベストを持ったものはないと理解していいですか。","respondent":"宍戸施設担当課長","answer":"今回の内装材の中には、そういったアスベストを含有した成形板等を含まれていないです。","voiceIndex":55,"id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"概略でいいですけれども、改修部分の全体の面積を、特に防水関係がわかれば教えていただきたいと思います。","respondent":"宍戸施設担当課長","answer":"平部が１,０００m2余、勾配部が６００m2強です。","voiceIndex":57,"id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"なぜ面積をお伺いしたかというと、専門家の方のお話を聞いているとかなり雨漏りがひどい施設だと。特に、改修工事の場合は、雨漏りというのは直し切れない部分があります。工事概要を見ると、シート防水とフッ素ガルバリウム鋼板による改修工事になっています。外壁にクラックが出ているということは、特に台風時期などは横風と雨の関係があるものですから、その辺のところを教えていただければと思います。","respondent":"宍戸施設担当課長","answer":"平部ですが、完全に今までのものを除去して、シート防水をやり変えるですし、勾配部につきましてはステンレス系の鋼板だったものを、フッ素化ガルバリウム鋼板にやり変えるもので、２０年経ってありますので、防水関係は基本的には耐用年数いっぱいまでいっているということで。","voiceIndex":59,"id":"exchange-024"},{"speaker":"原委員","kind":"質問","question":"足場を組んで全部見るということは、目地部分があればそこも補修するということなのか、もう一つはシート防水に関して、通常のシート防水なのか、歩行用のシート防水なのか、この２点を教えていただければと思います。","respondent":"宍戸施設担当課長","answer":"目地部分につきましても、すべてやり変えます。それから、歩行用ではないと思います。","voiceIndex":61,"id":"exchange-025"},{"speaker":"林委員長","kind":"確認","question":"ほかにないようですから、私から確認いたします。改修工事をするにあたって、築５０年になりますね。工事を始める前の話として、建て替えとの比較はされたのですか。というのは、向かいに国文学研究資料館があります。","respondent":"中島経理課長","answer":"戸越体育館ですけれども、先ほどご説明しましたけれども、昭和３４年に開設されまして、昭和６２年に改築しています。そこだけ見ますと約２０年経過しているということで、躯体そのものについては十分いけるです。これは戸越体育館に関しての話です。","voiceIndex":64,"id":"exchange-026"}]},{"id":"topic-04","title":"の商店街電線類地中化工事（北品川地区）その２請負契約","agenda":"の商店街電線類地中化工事（北品川地区）その２請負契約","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１回目の価格と変わらずに２回目の予定価格になっているわけですね。積算し直したということではありませんね。その場合には、辞退された２社は当初から予定価格をわかっていて応募されたのか、例えば入札して、結果として受け入れられなかったというのはわかるけれども、辞退が前提になって応募するという、その辺の仕組みを教えていただけますか。","respondent":"中島経理課長","answer":"ただ、そのときには企業も図面等がない状態で額を見るということで、実際にこの仕事を受けてみようということで、図面等をもらって詳細の内訳書等も含めて作業した結果、予定価格ではなかなか難しいということで辞退してくるというのが通常の辞退の理由です。","voiceIndex":74,"id":"exchange-027"},{"speaker":"菊地委員","kind":"質問","question":"予定価格に近い数字が１社でも出れば成立するという考え方ですよね。一般競争入札の考え方として、複数の会社が札を入れて、初めてそこから決まっていくという前提が崩れた形で、最終的に(株)ＮＩＰＰＯコーポレーションが決まっているという受けとめ方でいいですか。","respondent":"中島経理課長","answer":"額だけの考え方でいきますと、残りの２社はこれより高い金額の考え方を持っているということでは、価格の面でも考え方の整理をされているのかなと考えてございまして、１社でも価格内の提示がされれば入札は成立するものと考えています。","voiceIndex":76,"id":"exchange-028"},{"speaker":"浅野委員","kind":"質問","question":"両方とも大きいところですから、そういうことはないと思うんですけれども、撤退するような通信会社がいるということをある程度想定されているのかお伺いしたいと思います。それから、地中化してトラフの使用料ですとか、そういうようなものが入ると思うんですけれども、今までの収入に比べてどのぐらい変わってくるのか、概算でも結構ですから教えていただければと思います。","respondent":"中島経理課長","answer":"１点目の撤退した場合はどうなるのかということですけれども、大変、申し訳ないですけれども、私ともはそこまで所管と確認を取ってございませんので、後でその線を抜くのかどうかというのは承知しかねます。","voiceIndex":85,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1764#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":30820,"voices":96}},{"id":"h19-20071106-14","meetingId":"h19-cm11","date":"2007年11月6日","dateIso":"2007-11-06","committee":"行財政改革特別委員会","time":"午後１時０３分～午後４時１４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"契約のあり方に関すること","agenda":"契約のあり方に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"この後の視察にも関連するんですけれども、こちら、システムが東京都全体で同じシステムを使っているということで、かつ品川区で既に始まっているということでしたら、きょうの視察というのは、なぜ葛飾区に行くのか。なぜ葛飾区まで行って見るのかということと、その葛飾区で実際にされていることというのは、何か品川区あるいは他の区と違いがあるのかということをちょっと教えてください。","respondent":"中島経理課長","answer":"平成１９年度から一部、今のところまだ１０件程度ですけれども、委託とか物品に拡大を始めたですけれども、片や葛飾区につきましては、一般競争入札あるいは指名競争入札、それとあと、いわゆる見積もり合わせと言いまして、入札まで行かないんですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"阿部委員","kind":"確認","question":"そうすると、確認なんですけれども、葛飾区がそれだけ幅広くされているのも、これはこの東京都のシステムの上でなさっていることで、このノウハウさえ学べば、今後、品川区でも広げていける、あるいはいきたいということでよろしいのでしょうか。","respondent":"中島経理課長","answer":"品川区の事務的な体制とかいろいろありますけれども、基本的には私どもとしても拡大していきたいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"裏面の区のところの３つ目に、「発注図書の配布」というのがありますけれども、この辺が申請が受理された後、すべてインターネット上で全部見られるということなのかどうか、それが１点と、あと、右の紙入札の場合は、業者に出向いてもらう、それが全くなくなるわけですが、やりとりがすべてインターネット上で完結をしているのかどうか、その点を教えてください。","respondent":"中島経理課長","answer":"これは私どもで指定する印刷会社がありますので、そちらのほうで購入していただいておるです。これは紙入札の場合も電子入札の場合も品川区の場合はずっとそういう形でやらせていただいておるということで、これは今後の検討課題であるのかなというふうに思ってあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"発注図書のところで、かなり工事や何かだと膨大ですよね。今まで、紙入札の場合も図書を買う、購入するというのは、どこに行って手に入れるんですか。","respondent":"中島経理課長","answer":"基本的には青焼きですので、価格的にはそう高くなくて、例えば耐震工事の場合で、大体二、三十枚のものが平均ですけれども、１部が２０円から３０円ですので、３０枚として大体９００円ぐらいという価格です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"林委員","kind":"確認","question":"この資格をとるときに、インターネットでのやりとりでしょう。セキュリティーの問題で、１件１件の会社のパソコンにおけるセキュリティーの確認というのはどういうふうにされているんですか。","respondent":"中島経理課長","answer":"先ほど１ページ目のお話で若干説明がわかりづらかったと思うんですけれども、３番のほうで、電子入札の利用に必要なものということで、（１）に電子証明書がございまして、これは登録する前の段階に１つの会社に１つのフロッピィディスクを交付してございまして、それによって。","voiceIndex":13,"id":"exchange-005"},{"speaker":"林委員","kind":"意見","question":"そのフロッピィは危なくないか。だから、セキュリティーはどういうふうに、フロッピィを渡しているから、そのフロッピィはコピーもできなければ、特定のパソコンでしか使えないとか、フロッピィはどこに入れても一般的には使えてしまうという問題で、だから、どこでセキュリティー保証を区はされているのか。","respondent":"中島経理課長","answer":"その詳しいことは、ちょっとどういう形で具体的にどうしているのかというようなことは、ちょっと詳しく存じておりませんけれども、これは情報システム課のほうで基本的にトータルで管理をしてございまして、私どもはそれを使わせていただいているということで。","voiceIndex":15,"id":"exchange-006"},{"speaker":"林委員","kind":"意見","question":"次回で構いませんから、経理課長が信頼しているから大丈夫だという部分と、我々が聞いて、今例えばフロッピィを渡してあって、そのフロッピィで入れなければ入札、応札できないよというのではちょっと不安だから、次回でいいです、こういうセキュリティーをきちんとかけてあるから大丈夫だというのを情報システム課からもらっておいて、次でいいです、お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"電子入札をやったときに、先般説明があった簡易型総合評価制度との兼ね合いはどのようになってくるのか。この作業でどこか変わってくるのか、それと、葛飾区もその辺も入って、向こうは総合評価制度をとっていないのかどうか、それを教えてください。","respondent":"中島経理課長","answer":"総合評価制度との関係ですけれども、総合評価制度につきましては、基本的に金額を入札していただくのと同時に面接等もありますので、今の段階では、この電子入札と合わせてやるというのはちょっと難しい部分もあるのかなというふうに考えてあります。","voiceIndex":19,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5828#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":6797,"voices":23}},{"id":"h19-20071107-16","meetingId":"h19-cm11","date":"2007年11月7日","dateIso":"2007-11-07","committee":"街づくり特別委員会","time":"午後１時０３分～午後３時３１分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"日程に入ります。特定事件調査の「地区計画に関すること」のうち、「八潮地区について」","agenda":"日程に入ります。特定事件調査の「地区計画に関すること」のうち、「八潮地区について」","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"明晴学園の学校規模、何歳から何歳の子どもたちが、１クラス何人体制でとか、そういうものの規模についてちょっと教えていただきたいのと、あと３階のところの家庭科室だけが明晴だという先ほどの説明だったんですけれども、この部屋の活用そのものは、家庭科室ということで使うのかなと理解していたんですけれども、ちょっとその辺の確認と、あとマイスクール八潮が来るということなんですが。","respondent":"古里学務課長、日下部企画財政課長","answer":"３点目につきましては、後ほど企画財政課長のほうからお答えします。最後の現在、マイスクールの現地、今、活動していますけれども、これにつきましては、当面教育施設としてその後の活用を検討しています。６月とたしか８月の当委員会におきまして、確かに八潮北小学校の跡施設の活用についてということで、区としての基本的な考え方の中で。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"わかりました。しかしながら、福祉センターの手狭という状況は見ていても実感するところなので、何らかの方法を考えていくのはやぶさかじゃないと思っていますけれども、要するに今使っているマイスクールのところは半分あくわけですから、今使っているマイスクールのところは全部あくのか。そうすると、そこは教育施設だから教育施設にしかできないというのがありますものね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"意見","question":"今、こちらの図面の中で色のついていない部分、プールの部分とあと校庭の部分については、どのような活用の方向性か、あるいはほかの学校施設のように、休日等に地域開放などの検討はどうなっているのか、状況をお知らせください。","respondent":"古里学務課長","answer":"体育館ならびに校庭の休日開放の問題ですが、こちらにつきましては、明晴学園に貸与するということから、いわゆる公立学校とは違うんですけれども、明晴学園のほうにお願いをして、従来同様。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"幾つか倉庫があって、平成２０年度の移転に伴う一時的な用途で倉庫を幾つかという部分があるんですけれども、その後の活用はどうするのかという話にかかわって、先ほどももとあったマイスクールのところの旧しいのき幼稚園の部分なんですけれども、教育施設として活用を検討していくということなんですが、教育施設としてどういった方々に入ってもらうとか。","respondent":"古里学務課長","answer":"いずれにしてもこれは平成２０年度中に、企画財政課を中心にした庁内検討会等で、地域の声を聞きながら、跡地活用については決めていくものと考えています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"広く皆さんの要望を取り入れるような仕組みをつくっていただきたいと思うんですけれども、その点に関してはいかがですか。","respondent":"市川庶務課長","answer":"先ほど学務課長がこれから検討すると言った趣旨は、今後の八潮のまちづくりのこともありますので、教育施設の活用ということでも、あまり固定的な、要するに塩づけするような活用策ということは、当面検討することはございません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"それは八潮の地区計画というよりも、いろいろ変更などの予定もありますけれども、そういった教育施設以外のことにも幅広くこれから考えていくということなんでしょうか。","respondent":"市川庶務課長","answer":"繰り返しの説明になりますが、当面は教育施設として活用せざるを得ないので、暫定的な教育施設としての活用策を考えていくということで、その後は八潮のまちづくりの中でどう活用したら一番いいのか、それは別のステージで検討すべきことだということだと思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"それで動線をちょっと確認させていただきたいんですけれども、このマイスクール八潮のブルーが１階、２階、階段の部分が塗ってあって、３階にそういう用途があるわけですから、同じ建物の中でも用途ごとに独立性というんですかね、その辺ができているのかなと、この階段のところを見るとわかるんですけれども。","respondent":"古里学務課長","answer":"私のほうから説明申し上げます。１階部分、右上の図を見ていただきたいんですが、この右下のほうに青い区分があります。これが階段でございまして、Ａ階段、Ｂ階段と称しておりますが、こちらのほうの階段をマイスクール八潮の子どもたちが専用階段として使います。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"それはどうされるのかなと。今、中央部分というのは非常に管理されてありますけれども、この芝生のほうを拡大してほしいという意見も受けてはいるんですけれども、それは別の問題としても、管理はどうなっているのか。今はかなりボランティアの方たちがいろいろ助けていただいているんですが、今後明晴学園が入ったときに、そういう関係はどうなっていくのか教えていただきたいと思います。","respondent":"古里学務課長","answer":"はマイスクール八潮の給食につきましては、今後どのように提供していくのかというのは検討中です。したがって、学校の用途としては、現在、給食室は使用しないという方向で考えております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"今まで幾つか項目、明晴学園といろいろな協定を結ばなければいけないということが出てきていると思いますので、それも諸課がまたがってくるという、その点は整理した形で、担当がどこになるとか、どういう協定になっているとかというのは、私たちもすぐ把握できるような形のまとめをしていただきたいなと考えています。これは意見で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田委員","kind":"確認","question":"ちょっとお聞きしたいのは、先ほどプールを防火水槽にするというお話だったけれども、これは例えば八潮のまちづくりの皆様と俎上に上げて、今度例えば、先ほどボランティアという話もあったけども、夏は我々がしっかり管理をするから地域開放してほしいという話があったときには、そういう話を俎上に乗せるのか、それはもう乗せないで、防火水槽だけでいこうと思われているのか。","respondent":"古里学務課長、片田建築課長","answer":"したがって、その１００万円のコストをどういうふうに考えるのかという問題になってまいりますので、現在のところ、明晴学園はプールとしての授業は行わないということ、マイスクール八潮につきましては。学校施設あるいは共同住宅等でも同じですけれども、３階建て以上の建築物等については、避難の安全ということで、階段の区画の問題、それと二方向避難の問題。","voiceIndex":23,"id":"exchange-010"},{"speaker":"石田委員","kind":"質問・要望","question":"そうなったときに、あとはぜひやっていただきたいのは、明晴学園自体がそういう障害をお持ちの子どもというか、幼稚園の子もいるわけですから、そこら辺の、ここを避難訓練で使って、また交流するのがいいか悪いかという考え方はあるんだけれども、時期を見て小まめに避難訓練みたいなのはやられておかないと、いざというときは多分大変なんじゃないかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのは、民間施設という明晴学園に貸し出すということで、全体が民間施設ということになるのか、マイスクール八潮分は、契約上、明晴学園から借りるような形になるのか、それが１点お聞きしたいのと、先ほどの避難路についてはお話がありましたが、ぜひこれは子どもたちですから、小さなお子さんたちがやっぱり安易に避難できるような避難路というのがないと、どこを回ってどうのこうのという話と。","respondent":"古里学務課長","answer":"今は一応学務課の方針としてはプールの継続使用というのは当面しないという形で考えているというところですので、今後まちの人と話をする中でそういう活用策が出てくれば、その中でまた検討を進めてまいりたいと思います。","voiceIndex":27,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと補足で、足りないところがあったんですが、今のプールですが、教育的な見地から考えて、僕は小中一貫校ができるまでは、ある程度予算がかかっても、私は使わせてやるべきではないのかなと思うのが１点と、あと今、一般住宅でも大体二方向避難ということで、きちっと明確に、いざというときに逃げられるような道を確保しなさいという指導を、建築課のほうでもいろいろな場面でやっているわけですから。","respondent":"片田建築課長、古里学務課長","answer":"わかりやすく、どちらの方向に避難するかということをきちっと計画の中で示すようなことはしていかないといけないと思いますので、そういうことも含めて、対応していきたいと考えております。プールの活用の件につきましては、これは民間が管理する施設になるということで、従来の学校開放とは同一に考えられない部分がありますので、その辺も勘案しながら検討してみたいと思います。","voiceIndex":29,"id":"exchange-013"},{"speaker":"山元委員","kind":"質問・要望","question":"それからもう１つは、芝生をおやじの会、ボランティアの方々がやってくださるということで、実は、この工具というか、使っている機械がほかの階にあるものですから、これは要望なんですけれども、できれば校庭の片隅というか、倉庫というか、そちらのほうに置いていただくととてもやりやすいというご意見を聞いたものですから、その辺ご検討していただけるかどうかを聞かせていただきたいと思います。","respondent":"市川庶務課長","answer":"それと芝生の管理に関するご質問ですけれども、いわゆる道具類については、先ほど学務課長が申し上げた今後の関係者との協議の中で、その件も含めて対応してまいりたいと考えております。","voiceIndex":32,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"時間がないところ悪いんですけれども、あまりテーマがないところなので聞きたかったんですけれども、ここの契約上の問題がどうなっているかわからないんですけれども、施設を賃貸するのか、その辺の関係、あと使用料という項目で取るのかどうか、その辺のことも含めて教えていただきたいのと、最後にこの体育館が投票所になっているんですね。","respondent":"古里学務課長","answer":"したがって、品川区の財産を貸し出しするにあたっての基準によって賃借料を決めております。それから投票所としての機能ですが、先ほど防災のことしか聞かれなかったので言いませんでしたが、同じように投票所についても従来の機能を継続するようにということを言ってあります。","voiceIndex":34,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6354#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":17290,"voices":44}},{"id":"h19-20071126-6","meetingId":"h19-cm11","date":"2007年11月26日","dateIso":"2007-11-26","committee":"区民委員会","time":"午前１０時０３分～午後３時０３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"番、議案審査","agenda":"番、議案審査","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"議員提出第１６号議案、品川区文化芸術・スポーツのまちづくり条例について説明をします。品川自民党区議団は、文化芸術とスポーツのもたらす恵沢がまちづくりに活かされ、品川区が心豊かなにぎわい都市として、さらに大きく発展をすることを目的に、条例作成に向けて約２０回にわたり検討会を重ね、今回の議案提出に至りました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"２０回の検討会を経て作成ですけれども、この条例作成に当たって、その検討会の中で、例えば区民の皆さんからこんな要望があったとか、それを受けてどういう意図で今回作成され、どういう意味で提案されたのかということを最初にお伺いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"我々議員の立場として、区民の皆様と普段から接触しており、ですから、今回特別にアンケートをとったということでなく、普段からのヒアリングですとか、通常の日常の政治活動、当然その中でこういう案件が地域の皆さんから聞いている。ですから、改めて何かをやったということではなく、普段からの成果をまとめた、この条例になっております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"区のほうにお伺いしたいんですけれども、区民の皆さんの文化活動やスポーツ活動への関心は高いというものがありますし、施設の利用料がもう少し安くならないかとか、施設の数が少ないというふうな、活動環境の改善もよく聞くんですけれども、今回、この条例で行政運営上どう変わるというふうに認識をしているのか、ちょっとお伺いしたいんですが。","respondent":"鷹倉区民課長","answer":"私ども文化・スポーツに関する施策を多面的に実行してきたところです。施設も整備し、その中でやってきたと。従来から着々と行ってきた、文化・スポーツに関して行ってきたものをさらに後押し、目標というものが今回できるのかなと考えております。","voiceIndex":7,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"具体的にお伺いしたいんですが、条例の趣旨が反映されて、どういうふうに施策の変化があるのかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"提案","question":"提案者側の説明だと思います。それから、この目的がなぜかという質問なのかな。この中で、区として、市町村としての責務というものをうたっておりますので、このことに、さらに品川区としてもラインを合わせていくべきということが大もとです。それを品川としては進めるべきだということは大前提ですので、それは普段から我々の聞いている声の中に入っていたため、こういう検討案の条例化ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"何人もその求めるところに従ってスポーツを行う可能性を持たなければならない」というところで、非常に自由な活動というふうにすべてのスポーツ活動を定めていると思うんです。そういった自主性を尊重するということというのは、この条例の中の「自主性は尊重されなければならない」という文言にありますので、これはしっかりとこういうことで保障されているというふうに考えてよろしいんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"我々も自主性ということは非常に大切しています。ですから、区民等の責務という言葉ではなく、役割としています。わざとここは責務にしないで、役割ということで、負担のないように、強制的に条例化で区民の方にやりなさいということではないということは、自主性として目的の中に最後に強調している部分です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"やはりこういった国際交流をする、スポーツを通して国際交流をするということでも、その節度を持ってといいますか、配慮するということはすごく今、大事だと思うんですが、この具体的な国際交流の推進という点では、何といいますか、どういう活動というのをイメージされているのか、ちょっとお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この条例と海外調査というのは別系統でして、我々としては全く考えていません。当然この国際交流、既に実施しております。例えば、既にやっていますが、２年ほど前ですか、ニュージーランドからも来て、きゅりあんでの交流、現地のダンサーの方などが来た記憶もありますし、それから当然、国際友好協会のほうで、スポーツ交流でポートランドからも来て、こちらからもポートランドに行ったりしている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"意見","question":"１つ大きなところで、国では文化芸術振興基本法というものができて、そのとき共産党は、国民が文化芸術、スポーツももちろんそうなんですが、自由に享受できる、国や行政はそれを支援していく。いろいろな文化芸術、芸能、たくさんあると思うんですけれども、そこら辺が差別をされてはいけないと思いますが、その辺についてのお考えをお聞かせください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"一点目の不当な干渉という部分は、第１条の目的のところで自主的な文化芸術活動およびスポーツ活動の促進ということで規定し、干渉ではなく、自主的にやっているものに対し、さらに促進していこうということが目的でありますので、干渉ということではないと考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"提案","question":"今のところの続きで、いろいろなものが含まれているというところと、差別化されてはいけないと思うので、その辺の根拠というのはどこでとらえていらっしゃるのかなというのが１つ。この今回の提案の条例は、文化芸術・スポーツのまちづくり条例ということで、このまちづくりというところにこだわられた、ここのねらいをちょっとお聞かせいただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"差別化という面で、やはりあまりこだわってしまうと差別化になると思いますので、そのために、逆に大きな範囲で、その他芸術ということで入れております。ですから、建物を建てるとか、改築するという意味のまちづくりではなくて、文化的なもの、スポーツ的なものを品川の中のいろいろなコミュニティという感じのまちづくりに結びつけていきたいということが目的です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"総合的に進めていくというお話ですが、具体的にこんなことをしてほしいみたいな、見えるようなイメージで要求を受けとめられているところがあるのかどうかが１つと、あと、こういった文化芸術とか、スポーツを、やはり本当に区民の皆さんが自由に享受をしていく、そういった行政をつくっていくことはすごく大事なことだし、歓迎されることなんですけれども、この条例ができたことで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"既にやっている部分もありますし、例えば国際交流ですとか、スポーツ交流ですとか、既にやっている部分はありますね。そういうのをもっと積極的にやっていく部分が１つだと考えています。条例に基づいての表彰ではない。ですから、顕著な成績をスポーツで上げたお子さん、生徒児童に対して、やはりそういう顕彰をしてあげるということも大事な問題の１つだということが、我々の中にあります。","respondent":"鷹倉区民課長","answer":"したがって、具体的なイメージというのはその中で表現されていくというふうに考えております。","voiceIndex":20,"id":"exchange-016"},{"speaker":"山路委員","kind":"質問・要望","question":"私も大賛成です。賛成者の１人になっているんですけれども、我が党も長年にわたって文化芸術条例は要望してきたんです。大賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"同時に文化、スポーツ活動は自由に営まれるべきでありまして、行政が支援を行う際は、そんなに介入しないこととか、差別しないことが大事だと考えています。条例では、こういった環境を整える行政の責務が広く定められておりますし、また、審議の中でもそういった自主性を十分重んじていくということでしたので、賛成したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-018"},{"speaker":"稲川委員","kind":"意見","question":"私の会派としても、すばらしい条例だと考えています。今後、例えば２０１６年東京オリンピック誘致運動もスタートしている中で、やはりこういった条例を制定することによって、区民の意識も上がっていくのではないかと考えていますので、賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"今回、保険業法が改正をされたわけなんですが、その改正の趣旨とは何だったんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"自主的共済というのはいろいろあると思うんですけれども、区が認識されている範囲で構わないんですが、区内で例えば、こういう自主的共済というのはどのようなものがあって、どのような影響が出ているか、つかんでいる場合はぜひお伺いしたいんですが。","respondent":"鷹倉区民課長","answer":"したがって、我々としてはわからないというふうに答えします。","voiceIndex":38,"id":"exchange-021"},{"speaker":"渡部委員","kind":"質問","question":"確かにホームページを見ても情報が少ないんですね。１つ教えてほしいのは、そもそもこの共済金をずっと掛け続けていた方がいらっしゃって、例えば今回、このような法整備をされたことによって、確かにどこかの団体による共済が仮に破綻したとした場合、今まで掛けていた人たちというのは、保険業法にのっとっていないわけですよね。これは保護されるんですか。それが１つ知りたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"理事者が答えられる範囲ではない。本来なら紹介議員の方に質問をして、私も聞きたいことが何点かある。条文を見てみても３００条以上あって附則も多くて、とても理解できなかった。個人の名前ですから、会派としてではないという部分はありますけど、この辺の話ができていないということは、質疑しようがないのかなという気がちょっとしてきています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"意見","question":"この方たちはしっかりと、不特定じゃなくてちゃんと特定をされた会員の中で会則をつくって、その中の相互助け合いということで、不特定では全くなくて、自分たちが納得のいく話し合いのもとに行われている共済、これが今回の保険業法の改正によって、自分たちが助け合ってやっているこの共済までが今後立ち行かないという状況になっては困るので、ぜひそこのところを運用の見直しというのと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"例えば、新規加入、特定の加入団体として加入している１つのあれですけれども、逆に現在の加入者だけが入れるのか、これから新規に入る人というのはどうなのか、その辺も理解できていない。ですから、現在特定という範囲で限られているのは、新規加入がなければ、当然こういう共済にしても、相互扶助の会ではなくなってきますよね。その２点をちょっと、もしわかれば。これから入る。そこら辺はどう思うのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-025"},{"speaker":"飯沼副委員長","kind":"質問","question":"６団体ですよね。だから、そのところより、この人たちの請願は自分たち以外、新しく加える人がどうというんじゃなくて、自分たちが、この６団体は今まで健全に運営をしてきた。だから、こういった健全なところまで今回の保険業法で縛られるのは問題。新規加入であったとしても、そういう健全なところを除外をしろと言っているわけですから、除外をされれば同じようにあたると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"いろいろいただいたんで、ちょっと最初の質問、１点目から結構私の言っているのと違うかなと思うのが、共済制度そのものを分かっていないから、自分がね。特定の人という範囲でいったときに、現在の既存の共済の組合員は守られるけれども、例えばそこに私が入りたいといったとき、新規の加入というものの制限はどうなっているのかということが理解できない。その辺はおわかりになるでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"意見","question":"会員が主人公で、心が通い合う、みんなで自分たちの仲間に目配り、気配り、心配りをして、みんなで支えていこうじゃないかという、だから、持っている共済のお金自体で全部運営をしているということと、仲間の数が力になってクリアしていくことが大事ですよというのが５つの魅力としてうたわれているので、ここを守っている限りにおいては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、その辺が先ほどご説明があった小規模短期保険業者になるとすると、副委員長の立場としては答えられないでしょうけれども、そこの弊害部分が理解できていないということはあるので、その辺は理解していらっしゃる紹介議員側の会派として、わかっていればご説明いただきたい部分があったんだけど、現状、そこは無理というお話なので、ちょっとほかの、制度の問題じゃなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問","question":"私も、きょう若干いただいた資料とインターネットをあれこれ出して勉強した範囲でわからないところがあるので、私はよい機会なので課長にもお伺いしたいなと。ほかに聞くところがないんです。わかりませんか。","respondent":"鷹倉区民課長","answer":"請願の項目の２番目のところを見ますと、自主的にということを強調されているわけです。したがって、少額短期保険の中でいけば、保険業法の規制がかかると。当然国とすれば、いろいろな各種団体があるわけですから、規制したいという形で成立した。","voiceIndex":48,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の、副委員長の質問は、逆に言うと紹介者に、請願者の請願の意味の理解ということで、同じ会派の中で何でそこを理解していないのというふうに私には聞こえて、行政のほうで答える話じゃないと思ったんですが、それは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-031"},{"speaker":"山路委員","kind":"質問","question":"質問ではないんですけれども、意見ではまだ早いですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-032"},{"speaker":"山路委員","kind":"意見","question":"この言葉に、請願、項目の意味はよく理解できるんです。言葉だけ、なるほどと思うんです。しかし、法改正の目的からずっと展開していきますと、やっぱり待てよというのが出てくるんです。いろいろな規制の必要性があるからこそ法改正をするわけでありますから、その中でやっていく。まだその時期じゃないんじゃないかという気がしますので、そういうところで判断になるんでしょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"態度としては、６団体の中の状況は実際、健全性というのは我々の中では見えてはいない。それから特定、不特定の線引きの問題。この辺、ちょっとこの請願の中で理解し切れない部分がありますので、今回の請願に対しては不採択という形での態度を表明したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-034"},{"speaker":"安藤委員","kind":"意見","question":"結論を出すことも含めて、採択でお願いしたいんですが、やっぱり当初の消費者利益を守るという法改正の趣旨から、今回はちょっと法改正の途中でそういった趣旨とは若干逸脱してしまった部分があって、非常に今回はパンフレットとかにはお話もあったんですけれども、まじめな組合員の相互扶助のために特定の人と限定していますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-035"},{"speaker":"稲川委員","kind":"意見","question":"今ずっと話を聞いているんですけれども、まとまりがないというか、まだ意見書を提出するまでに至ってはいないんではないかなという思いがあります。態度表明としては、本当にわかりづらくて、僕はわからない。それは勉強不足と言われてしまうかもしれないですが、あまりにも大き過ぎて、不採択……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-036"},{"speaker":"渡部委員","kind":"意見","question":"いろいろ、インターネットとかで調べながら、こういう制度があるのはこういうことがあるんだというのを見ました。例えば、じゃあ、品川の中でどれぐらいの人たちが、どれぐらいを掛けていて、どういうふうなことをやっていたんだろうというのがなかなか見えてこない。もう１回ちょっと勉強したり、いろいろな人の話を聞いてから答えを出したいと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-037"},{"speaker":"飯沼副委員長","kind":"質問","question":"結論を出す過程でかなり判断に迷っていたのと、わからないというところが強かったので、もし一通りお伺いする中で検討ができたら、深められれば、わからないままに結論を出してしまうよりも、もうちょっと深めたほうがいいかなと、うちの会派は結論ということだったんですけれども、もし……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-038"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"何回か、司会も中学生がやってしっかりと進めている。最初のときから気になっているのは、中学校側の協力をもうちょっと強くして、当然、青少年対策地区委員会の主催になっているからで、どうも学校側の協力度がちょっと弱いような気が前からしているので、その辺をもう少し協調できないかなということを、できれば要望しておきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-039"},{"speaker":"山路委員","kind":"質問・要望","question":"すみません、私もちょっと要望があったんですけれども、ケーブルテレビとかで表彰の模様とか、状況とか、テーマとかをお伺いして、ああ、すばらしいなというのを感じていたんです。それで、例えば審査委員長の賞に輝いた人の内容も広報に載せるとか、もう少し区民全体に啓発できるような宣伝をしてあげる方式をとっていただきたいことを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-040"},{"speaker":"飯沼副委員長","kind":"意見","question":"本当に努力されて、この場ができているわけなんですけれども、発表される方の思いをみんなで共有したいなと思うことで、選ばれてくる過程を、ここで言っていいのかちょっとわからないですが、その辺がもしわかったらと、この後、冊子をつくったりとか、いろいろあるんだけれども、身近な同級生とか、学校の中で生かしていってほしいなという。すみません。もし、わかれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-041"},{"speaker":"稲川委員","kind":"意見","question":"ちょっと関連性が飛んでしまうかもしれないんですが、この安心安全ステーションはあそこにあった交番がなくなって、地域センターの前にプレハブ小屋みたいなのが建っているんですが、実際にステーションができたことによって、地域は何か変わりましたか。それをつくったことによって、地域で何かよくなったとか、悪くなったとか、そういう話は聞いていますか。","respondent":"高濱生活安全担当課長","answer":"このステーションができて犯罪状況については、大きな変化はありません。ステーションについては、地域の方の立ち寄りがございまして、一定の皆さんの安心の場という形はできています。ただ、目立ってこれができたからどうこうという意見はどこからもいただいておりません。","voiceIndex":95,"id":"exchange-042"},{"speaker":"稲川委員","kind":"質問","question":"ちょっと、私も地域を回って、あそこで事故が起きたんです。これ、１週間前なんですけれども、商店街の人が間に入ってとめたとは言うんですけれども、警察に全然連絡がとれないという話が出ていたので、ちょっと質問させていただいているんですが、推進員制度が発足しました。地域の安全は地域の人が守るというのはあるんですが、警察との連携というのはどうなっているんですか。","respondent":"高濱生活安全担当課長","answer":"交番がなくなったことによりまして、浮いた人員について、地域のパトロールが増強されております。今、お話のありました事件につきましては、今回の安全推進員が対応するという話ではございませんで、何らかの１１０番なりを受けて警察が動くということになります。","voiceIndex":97,"id":"exchange-043"},{"speaker":"稲川委員","kind":"質問・要望","question":"よくあるんです。交番の中にも電話があるけど、通報しても警察が来なかった。多分、あそこの場所だと源氏前交番から来る形になるんですかね。なかなか来てくれないというのが地域の要望だったので、できればこういうのを発足した中で、やっぱり地域の安心安全をつくるためにも、ちょっと警察との連携を深くとっていただけないかなというのが地域の要望でした。これは要望です。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問","question":"せっかく区民の方にやっていただくのに、責任体制、その人たちの責任という問題がどう出てきてしまうかは最初から気になっていたんですけれども、この方たちには責任は持たせるべきではないですよね。危ない話だと思うし、ですから、逆に私は現場を見ていないんですけれども、ここにいらっしゃる方たちは、警察ではないということははっきり出ているんでしょうね。","respondent":"高濱生活安全担当課長","answer":"逆に詰めていただくことによる危険を避けるために、時間的にも区の生活安全パトロールを行っている時間帯。後ろの地域センターがあいている時間帯を選定して、当初スタートさせる予定です。","voiceIndex":100,"id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ、他区から来た人とか、何も知らないでちょっと寄ったときに、何でここにいる人たちがやってくれないのなんてことになっちゃうと、せっかくやっていただく方にかえって迷惑がかからないかなというのがちょっと気になっている部分なので、何か、この方たちはこういう人なんですよということが表に見えるような形で出してほしいなという気がするんです。その辺は出してあるんですか。","respondent":"高濱生活安全担当課長","answer":"こちらのステーションに滞在していただく方には、ジャンパーをお貸しするわけですけれども、明確に警察官や警備員とは違う形のジャンパーを想定しておりますので、その点ではご心配は少ないのかと思います。","voiceIndex":102,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問","question":"現場は見ていないですけれども、ステーション自体は、はっきり私はわからないんですけれども、そのステーションに、ここにいる人たちはボランティアの人たちですよというようなことを表示しておいたほうがいいんじゃないかなというのは、そういう表示というのは、今のところ何もないのか、考えていないのか、できればそういうのを張っておいたほうがいいような感じがするんですけれども、その辺。","respondent":"高濱生活安全担当課長","answer":"現状では、まだ制度は発足しておりませんので、掲示はございません。おっしゃるとおり、安全のためにも、それについてはちょっと考えさせていただきたいと思います。","voiceIndex":104,"id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"今、人員１１名、発足時ということなんですが、これはもう１２月３日スタートの時点が１１名なのか、それと、今後、例えば増員の計画はあるのでしょうか。これからそういうボランティアを募集していくのでしょうかというのが１つと、あと時間帯が月曜から金曜の午前中２時間、午後３時間というのは、必ずいる時間帯なのかという点について教えてください。","respondent":"高濱生活安全担当課長","answer":"時間帯につきましては、最大限、うちの生活安全パトロール車がある、７時半から午後８時までの間であれば増強することが可能ですので、今回スタートを切りまして、様子を見させていただきながら増員については考えていきたいと考えております。","voiceIndex":106,"id":"exchange-048"},{"speaker":"渡部委員","kind":"質問","question":"その場合はどういうふうな対応になるんですか。あそこって人がいないなと。例えば、１時間でも２時間でも座っててやろうかみたいな話がいっときあったのも事実なんですが、そういった場合、じゃあ、このボランティア体制ができ上がって、この推進員がいるというふうになった中では、例えばそういうのを私もやってみたいわというような方がいたらどういうふうに受けつけてもらえるんでしょうか。","respondent":"高濱生活安全担当課長","answer":"ただ、現在発足時につきましては、一たんこれでスタートさせていただきたいと思いますので、そういうご希望の方とはご連絡を取りながら、できるだけ常に中に人がいらっしゃるような形で進めていきたいとは考えております。","voiceIndex":108,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"現状、仮の施設みたいな感じになっている小さいところですけれども、これはいつまでこのような状態なのかということと、また、もともと交番があったところなので、やっぱりどうしてもあそこへ、質問にもありましたけれども、ついつい犯罪にも対応してくれるんじゃないかというような期待というか、誤解というか、地域の人が持っちゃうのは無理もないかなと思うんですが。","respondent":"高濱生活安全担当課長","answer":"警察との協力につきましては、警察でもあの交番を廃止した時点で、あの地域に犯罪を起こさせるわけにはいかないという強い意識を持っておりまして、現在のステーションについても、１日に１０回程度の立ち寄りをしてもらっております。","voiceIndex":110,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"ステーション自体もあそこに残るということなんでしょうか。それとは代替で東急との関係で新しい施設ができるのか。その辺、ちょっとお願いします。","respondent":"高濱生活安全担当課長","answer":"今の施設は一応仮という位置づけです。東急と交渉がうまくまとまれば、きちんとしたものを建てるわけです。","voiceIndex":112,"id":"exchange-051"},{"speaker":"飯沼副委員長","kind":"提案","question":"１万名を多分超えた署名活動をなされたと聞いているんですが、今、パトロールがあり、とりあえずの居場所ができてはいるんですけれども、地域から今進んでいる中で、またこういった提案があって安全推進委員が発足したわけですけれども、地域からどんな声が上がっているんですか。私は本当にこの１１名の方がありがたいなとは思うんですけれども、また大変な、新しい仕事が増えてしまったと。","respondent":"高濱生活安全担当課長","answer":"年齢構成ですけれども、高齢の方が多くなっております。７０代の方が５名で、６０代の方が４名、そして５０代の方が２名だったというふうに記憶しております。","voiceIndex":114,"id":"exchange-052"},{"speaker":"飯沼副委員長","kind":"質問","question":"今のこれでとりあえずやるんだったら複数体制でやるのが大事であるなと思うのと、あと、あそこにボックスは建っていますけれども、ちょっとあまりにも居場所としては居心地が悪いのではないかなと思うので、その辺も十分お声を聞いていただいて、これから寒くもなるし、改善が必要であると思うんですが、その点はいかがでしょうか。","respondent":"高濱生活安全担当課長","answer":"道案内が１日に四、五回、落とし物の届けが月に二、三回、緊急連絡というものは現在まではありません。家の前に変な男の人がいるというような相談事が全部で二、三回という内容でした。それを受けまして、一応の安全については大丈夫であろうということを判断しております。","voiceIndex":116,"id":"exchange-053"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"要望なんですけれども、ほかの地域でも交番がなくなることに関しては、ものすごく地域の関心が高くて、意見もたくさん出ています。積極的に聞いていただきたいんです。いろいろご努力はされていると思うんですけれども、ぜひ地域の声を聞きながら改善していく、私はできたら本当に交番を戻してほしいなと思うところなので、よりプロの方にいてほしいなという思いを要望して終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"日時なんですが、金曜日と土曜日ということなんですけれども、日曜日のほうが多くの方は参加できると思うんですけれども、この日程になった理由についてお伺いしたいのと、最後の一番下の犬のしつけ方教室なんですけれども、ちょっと協定という話がありましたが、ちょっとよく理解できませんでしたので、もう一度説明をお願いしたいなと思います。","respondent":"久保田防災課長","answer":"獣医師会のほうなんですが、これは一昨年災害時協定を結びまして、震災時等については、いわゆる各家庭でペット等を飼っていらっしゃることについての対応として、獣医師会も区と協力して実施するという中身になってございまして、その一環として。","voiceIndex":124,"id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問","question":"投票の関係なんですけれども、５５,６７４票あったんですが、これは投票場所がありますよね。どんな傾向が多いんですか。やっぱり、インターネットが多かったのかという、私のほうから見ていて、インターネットで５軒まで投票できるというのがあったらそっちに行くのか、とりあえず実際どんな感じだったのかというのを１点教えてください。場所がとりあえず決まっていれば教えておいてもらいたいと思います。","respondent":"金子産業振興課長","answer":"そういう意味では、もっと詳細に分析しているわけではありませんけれども、投票される方の年齢層が影響しているのかなという気がしております。それから、大商業祭ですけれども、予定ではきゅりあん７階のイベントホールでやっていく扱いです。","voiceIndex":130,"id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"インターネットが少ないという、意外に驚いたのだけれども、商店街の方、地元の方がいろいろな取り組みをやってもらうのがいいのかなとも思いますので。これからもよく判断してやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"２番目のビジネススクールのほうなんですけれども、どういう方の支援を講じていますかというので、魅力的な、お客様に選ばれる店づくりというのも支援しているんでしょうか。","respondent":"金子産業振興課長","answer":"そういう意味では、さまざまな分野からお呼びしながら、個々の商店がどのようにしたらレベルを上げて集客力がつくのかというような内容のものにしていくというふうに聞いてあります。","voiceIndex":133,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは要望なんですけれども、やっぱり、商店街の魅力というのは、そこでしかないというか、その人の個性がすごく出ているというのが買い物をしていてもおもしろいし、今はすごくいろいろなチェーン店とかフランチャイズとかが多い中で、そういうのがやっぱりすごくいい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-059"},{"speaker":"稲川委員","kind":"質問","question":"申し込み状況３,７１０名、大体８割ぐらいということだったんですけれども、去年は大体どれぐらい。実質把握はできないですよね。何人参加したのかというのが１点。ここに東急電鉄のインターネットの申し込み、こちらも大きくホームページに申し込み受付があるんですが、観光協会にもホームページがあると思うんですが、観光協会ではネットでの申し込みはされないんですか。","respondent":"金子産業振興課長","answer":"ホームページの受付の関係なんですけれども、ホームページで受付の申し込みのフォーマットをつくるというのが、少し、経費あるいは時間がかかるものですので、今回はたまたま、８０周年プロモーションで東急電鉄のほうでつくっていただけるという申し出がありましたので。","voiceIndex":141,"id":"exchange-060"},{"speaker":"稲川委員","kind":"質問","question":"すみません、もう１点。参加費無料で定員３,０００名なんですけれども、商店街を見ていれば、別に、ここに申し込みをしない人もいっぱいいると思うんですけれども、そういうのはどういうすみ分けというか、そういうのはあるかどうか。例えば、ここを見ると、無料の商品をつまみ食いだとかって書いてあるんですけど、それにちゃんと参加申し込みをしている人というのは、チケットか何かがあるんですか。","respondent":"金子産業振興課長","answer":"問題のつまみ食いなんですけれども、一応、当日お配りするものの中に、チケットの紙がありまして、つまみ食い１食につき券１枚を入れていただくというふうにしております。１人の方に券を１０枚配るようにしてありますので、それで区別をするというふうにします。","voiceIndex":143,"id":"exchange-061"},{"speaker":"山路委員","kind":"質問・要望","question":"すばらしいイベントだと思うんですけれども、このイベント、昨年の例でいいんですけれども、相乗効果というのは何かあったんでしょうか。何かあったらちょっと聞かせていただきたいんですが。","respondent":"金子産業振興課長","answer":"１つは、やはり当日においてもお昼時を中心にしておりますので、つまみ食い以外にもいろいろ飲食をとられる方がいて、一応、統計的には全員が全員お金を落としたわけではないんですけれども、お金を落とした方では大体５００円から１,２００円ぐらい、平均的に落としていると。","voiceIndex":145,"id":"exchange-062"},{"speaker":"山路委員","kind":"質問・要望","question":"やっぱり、イベントというのは多くの人が集まるという状態で、地元の商店街にとっても活性化というのものと両方がうまくいって大成功するのではないかなと思っているわけですけれども、すばらしい例を出していただきましたけれども、さらに多くの人が観光の再発見とともに商店街の活性化という両方が、あくまでも上手くいくように行政のほうで支援していただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"参加者の方々、参加された方の声というのをどのように集めているのかということと、あと、もし、特徴的な声を伺っているようなものがあれば紹介していただきたいのと、あと、これは７kmというのが、なかなか運動としてもいいんじゃないかなと思うんですが、ゴールまで行った場合に、何か特典みたいなものはあるのかなと思ったんですけれども、よろしくお願いします。","respondent":"金子産業振興課長","answer":"参加者の評価等々ですけれども、ほぼ全員の方にアンケートをとっていまして、「満足」、「やや満足」、「どちらでもない」、「やや不満」、「不満」という５肢選択でお願いしたところ、「満足」と「やや満足」を加えると８７.６％の方がはいと答えていただいていますので。","voiceIndex":148,"id":"exchange-064"},{"speaker":"渡辺委員","kind":"質問","question":"その中でちょっと伺いたいのが、先ほどありました経済的な波及効果、先ほどもご質問がありましたが、ほんとうに、これの部分でも産業振興の趣旨にも沿っていますし、この開催時期も、春と秋にやればいいのかなと安易に考えていたんですが、既存のイベントもあるし、既存のイベントの空き日の、年末の前のタイミングは時期的にそういうねらいがあって１２月１日だったのかなというのが伺いたいのと。","respondent":"金子産業振興課長","answer":"３点ほどのお尋ねかと思いますが、まず１点目で、なぜ１２月初めに設定したかということですけれども、先ほど申し上げましたとおり、１２月２日の土曜日が昨年実施でした。","voiceIndex":150,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"今年はどれぐらいの人がお手伝いをいただいているのかというのがまず１つと、今回、東急電鉄から後援といいますか、共催で入っていただいて、これってまた、次年度以降やっていこうと思ったら、東急電鉄から継続的にお手伝いをいただけるのか。これから人数を増やしていけるのかなと思ったので、その２点を教えていただけますでしょうか。","respondent":"金子産業振興課長","answer":"実際、昨年度どのぐらいの人数で対応したかといいますと、時間も長いので、それぞれ休憩時間も入れますから、交代交代になりますけれども、大体、５０人から６０人ぐらいで対応していまして、この中には、例えば、ポイントポイントでガイドボランティアの方に。","voiceIndex":152,"id":"exchange-066"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大変、裏方の方もご苦労だと思いますけれども、１２月１日、天気がよくて、また昨年並みにうまくいくことを期待しています。こんな番組をやるよということでやれば、やっぱり見る人が増えるのではないかなと思うので、ぜひその辺を活用してもらえればと思うんですが、その共催という面ではなぜ入っていないのかなというのを教えてください。","respondent":"金子産業振興課長","answer":"ただ、非常にご協力いただいて、昨年は初めてでどれほど人が足りなくなるかもわからないので、受付等に人手も出していただきました。そういう意味では、おっしゃっているような趣旨で、今後どういうふうにあらわしていくかというのは課題として認識させていただきたいと思います。","voiceIndex":154,"id":"exchange-067"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"難しいこともあると思うんですけれども、ぜひ、みんなに見てもらう、ケーブルテレビに入っていなければ見られないという前提で、これは事業部が違うと思うんですけれども、そこら辺の、もうちょっと積極的な取り組みをこちらがアピールしてもらえればどうかなと思います。これは要望にしておきます。","respondent":"川西委員長、原国保年金課長","answer":"ほかになければ、本件につきましては、以上で終了いたします。その方々に３５％を実施するということになりますと、約２万３,０００人というような状況になってまいりまして、その中でも動機づけ支援、それから積極的支援ということで、ちょっと新しい言葉が出ていますけれども。","voiceIndex":156,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"９ページのところで、これまでの健診から特定健診に変更をされるときに、例えば改めて新しい項目でやるということで、それ以外は同等の健診項目であるというご説明もあったんですが、医師の判断により貧血検査、心電図検査、眼底検査を行うとなっているんですけれども、今まではこちらは実施状況はどうだったのかということと、それは、全く、項目としては全く同じで。","respondent":"原国保年金課長","answer":"そういった意味では、そういう経過も踏まえながら、私ども、これから実施する項目についても、現行の区民健診を十分考えながら、具体的なものについては検討してまいるというところで考えているところです。","voiceIndex":161,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"今回、心疾患、あるいは脳疾患につながるメタボリックシンドロームの予防ということで、今回の特定健診というのがかなり強調されているんですけれども、やはりそういう心疾患を予防できるのは貧血検査ですとか、心電図検査ですとか、眼底検査、これまで区民健診のほうでは普通に実施項目に、条件といいますか、加えていたということもあると思いますので、非常にこれは重要な検査だと思いますので。","respondent":"原国保年金課長","answer":"そういったものを今までの区民健診の状況を、先ほども申し上げましたように、踏まえて、この健診項目がなくなることによって、２次に含まれることによってどういうリスクがあるのかとか、そういったところを検討しつつ。","voiceIndex":163,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"負担のことなんですけれども、これまでの基本健診ですと、国が３分の１で、都が３分の１で、あと区が３分の１ということで行っていたと思うんですが、来年から、これが特定健診となりますと、保険料および自己負担というふうに、３分の１で、今まで区が負担していたところがそういうふうになるということなんですけれども、この自己負担分を区が補助するということで、今回無料というふうになるんですか。","respondent":"原国保年金課長","answer":"基本的には、国が基準単価の３分の１、都が３分の１、こういったのは公的で、法律というか、政令の中で定めるようになっておりまして、この額がまだ出てまいりませんけれども、そのほかに保険料、それから先ほど言いました上乗せ等々の部分については。","voiceIndex":165,"id":"exchange-071"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば２０年４月ですから、４月の時点で発送するということは、ある程度詰まってないと間に合わないんじゃないかなという気がするのと、このことに対するお知らせというのはどんな文書になるのかというのがちょっと気になるかな。今までがん検診があったのがどうなっちゃったのというような、書類をもらった方がわかりやすい形にしてほしいなという点で、その３点。","respondent":"原国保年金課長","answer":"そうしますと、最初の動機づけ支援と積極的支援は、その健診結果をもとの保健指導を実施していくという、そのようなことがございまして、一定期間保健指導の期間を、およそ６カ月になるんですけれども、そういった期間を確保していかなくちゃいけない。","voiceIndex":167,"id":"exchange-072"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"説明はわかりました。それから、厚生委員会の健康課のがんのほうの問題も、できれば、データが、別のものが入るというよりも、１枚のものでやったほうが、かえって何で２枚になるのというのが、今お聞きした中で、一連でやるべき話じゃないかなという気もするので、もうちょっと調整していってもらいたいなというふうに感じました。その辺、あと、どうやっていただくか。今お答えいただいたので、要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-073"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"特定健診を行って、メタボリックシンドローム、また生活習慣病を予防していくという、そこの観点は同感なんですけれども、なぜこの時期に出てきたのかなというところで、医師の話を１回聞いたところによると、本来だったらば、基本的な健診を行う。その辺で、指導の中身がどうなっているのかという、今の疑問に答えていただきたいなと思います。","respondent":"原国保年金課長","answer":"死亡原因の約６割がこういったものが原因で死亡というような状況、こういったものを踏まえて、国といたしましてもどういうふうに対応をとっていくのか、こういった考え方の中で、これは生活習慣病に特化をしておりますけれども、生活習慣病のみのものではなくて。","voiceIndex":170,"id":"exchange-074"},{"speaker":"飯沼副委員長","kind":"意見","question":"９ページの健診項目のところなんですが、先ほどのご説明だと、基本が現行と大体同等、あと、詳細な健診項目あって、同じぐらいできるというご説明だったんですが、特に詳細な健診項目というところで、貧血の検査、心電図検査、眼底検査、これが医師の判断ということで、私、別の、厚生労働省の手引きのところを見たらば。","respondent":"原国保年金課長","answer":"ヘモグロビンＡ１Ｃ等につきましても、２次検査ということで、１次検査の結果により必要な項目を実施すると、こういうふうな形になってあります。","voiceIndex":172,"id":"exchange-075"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その点が１点と、あと、財政負担のところなんですけれども、今まで無料で、これからも自己負担はないということなんですけれども、国と都と区の財政負担のところで、実際に今までだと国と都と区が３分の１ずつ負担をして、あと、基本単価の３分の１ということでしたけれども、１箇所の保険者および自己負担というところで３分の１になって、ここのところが変わってきているわけですけれども。","respondent":"原国保年金課長","answer":"財政のところですけれども、平成１８年度の決算ベースで、現行の区民健診、約５億７,０００万かかっておりまして、その中で区の負担というのは３億５,０００万円余というような状況になってあります。","voiceIndex":174,"id":"exchange-076"},{"speaker":"飯沼副委員長","kind":"質問","question":"指導内容のところでお伺いしたいんですけれども、指導内容のところは、具体的にどのような中身になっていくのかということと、ここの上のところに、「民間事業者に委託」と書いてあるので、どのようなところがどのように指導していくのかというところを教えてください。先ほど「受診券」という言葉が出てきましたね。","respondent":"原国保年金課長","answer":"どのようにして形を変えて、その後状況を変えていくかということで、個別に行動目標、行動計画というのをつくりまして、この行動計画で例えば食生活をこういうふうに少し変えてみようとか、あるいは運動習慣をつけるためにウォーキングを週３回、３０分ずつ頑張ってやってみよう。","voiceIndex":176,"id":"exchange-077"},{"speaker":"飯沼副委員長","kind":"質問","question":"上を見ると、重度の７４８人。この人たちで支援を受け入れているのが２５％ということですが、じゃ、あとの７５％はどうなってしまうのかなと。重度の人というところにおいては、もうちょっと積極的なものがないといけないのではないかなと思ってしまったんですけれども、その辺はいかかでしょうか。","respondent":"原国保年金課長","answer":"今、ご意見がございましたように、国のほうでは、この実施率を２４年度には４５％に持っていきなさいということです。","voiceIndex":178,"id":"exchange-078"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ぜひ、特定健診といって、中身が変わってきてはいますけれども、必要な方がきちんと受けられて、予防につながるように、また財政的なところも、必要なところにぜひ財源を充てていただきたいなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-079"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１１月９日に、大規模テロ災害対処訓練が品川の大井競馬場で行われました。なぜかというと、国民保護計画のご説明を１回いただいたんですが、この計画ができて初めての東京都と一体になった訓練だと思うので、ぜひ中身を知りたいなと思うのと、国民保護計画のときも、なかなか勉強不足で質問ができなかったので、ぜひ明日にでもお時間をとっていただいて、ご報告いただけたらなと思うんですけれども。","respondent":"田中区民生活事業部長","answer":"ただ、一般区民の方を動員したりとかということではありませんので、また、その点では、細かい内容についても、いわば所管といいますか、責任を持って実施している主体ではないので、このところにつきましては責任を持った形でご報告するのは難しいかなということで。","voiceIndex":187,"id":"exchange-080"},{"speaker":"飯沼副委員長","kind":"意見","question":"東京都の主催ですけれども、品川区も、あと消防庁、消防団、あと陸上自衛隊、あと大井競馬場も一緒になってやっているということと、あと、品川区の職員が４６名、私、最初、電話で報告してくださいとお尋ねしたら、六、七名だというところだったんですけれども、職員も４６名参加、あと大井消防団が３０名も参加をしているんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":189,"id":"exchange-081"},{"speaker":"飯沼副委員長","kind":"質問","question":"突然のお尋ねで、詳しくありがとうあります。だから、警察とか消防から連絡が、こういう事態に入ったというときに、危機管理に報告が入って、そこで動くということでは、この日の訓練においてもそういう態勢がとられたんですか。区の役割というか、区の職員がどういう役割をしたのかというのと、あと、もう一個、消防団が何をされたのか、ちょっとその辺をお聞かせください。","respondent":"斉藤防災安全担当課長","answer":"先ほど委員のほうから、事前に私、電話で、概要を説明させていただいたんですけれども、そのときに６名と申し上げましたのは、今現在の現地対策本部の人数です。区のほうから、実質的には当日は４６名の職員が参加をしております。","voiceIndex":192,"id":"exchange-082"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった面で、やはりかなり危険なお仕事であるなと思うところにおいては、やはり計画自体をきちんと理解されたり、伝達されることが今すごく大事であるのではないかなと思うのが、それが１点と、あと、今日質問したのは、私は電話で課長にお伺いして、ある程度のところは知ったわけなんですけれども、一般の区民が避難で参加する訓練ではなくしても。","respondent":"斉藤防災安全担当課長","answer":"今後の訓練の報告の関係ですけれども、今回につきまして、私どもはそういった形で、都の主催、または内部的な訓練という判断でおりましたけれども、今後こういった機会、訓練があるわかりませんけれども。","voiceIndex":194,"id":"exchange-083"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"団員の方の、組織の問題はあると思いますけれども、保護計画自体をたくさんの方がそろって、協議をしてつくったというところにおいては、区もかかわっているので、ぜひその辺がより伝わっていくように、よその組織のことではあると思うんですけれども、その辺も心にとめておいていただきたいなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-084"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私の中で、これは今日出るのかなと思ったのは、ケーブルテレビではやっていたんですよね。放映されていました。ですから、何でないのかなというのをちょっと思ったので、その辺、区のほうでもどういうケーブルテレビと絡みが。きのうの放送もたしか出ていたんじゃないかなと思ったので、ちょっとその辺、確認しておいてもらえませんか。","respondent":"早津区民生活事業部次長","answer":"開催場所が品川区であったということで、地元自治体に対する協力要請がありまして、区としてはそれに協力をしたと、こういうことですので、全体を、あるいは、例えば一般に周知するのはだれかといえば、これは主催者責任において行うべきものと考えますので。","voiceIndex":198,"id":"exchange-085"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それは、もう、今言ったように主催者側との問題があるから、どう判断するかは、今のお答えでよしとするしかないんでしょうけれども、今後において、また少しその辺を検討してほしいなと。このケースは別の団体ということでありますけれども、全く報道がなければ、ケーブルテレビがなければしようがないなと思うけれども、偶然私が見ていたもので、その辺引っかかりがありまして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"今回、千代田区と品川区など関係６区が参加して、東京都としては２回目の訓練ということなんですけれども、先ほどちょっとお話もあったんですが、都のほうからどのような要請があって、それをどのように検討して、受けたのかというのをもう一度、開催場所が品川区内でたまたまあったのでみたいなお話もあったんですけれども、そこら辺ちょっと、どのような要請があって、検討して。","respondent":"斉藤防災安全担当課長","answer":"先ほど申し上げましたとおり、９日の日、東京都のほうでは１日かけて訓練をやっているようです。ただ、私どもは、大井競馬場の話は聞かされておりましたけれども、ほかの、例えば千代田区ですとかを巻き込んでの訓練というものは、実は私どもも知りませんでした。","voiceIndex":201,"id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2502#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":66710,"voices":203}},{"id":"h19-20071126-7","meetingId":"h19-cm11","date":"2007年11月26日","dateIso":"2007-11-26","committee":"厚生委員会","time":"午前１０時０３分～午後４時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を110件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"提案趣旨については、本会議で説明をしていますので、重複しないように条例に沿ってその内容について説明をさせていただきたいと思います。これが受給資格です。今回の提案は、既に港区が２００６年の４月から実施している、そういう中身、同じ中身のものです。品川区でもぜひ実現できるように、十分ご審議をいただいて、決定をしていただきたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"},{"speaker":"須藤委員","kind":"提案","question":"何点かお聞きします。それから第５条、虚偽の申請その他不正の手段というのは、どういうことを考えられているんでしょうか。それでできないというようなお話があったんだけども、これは出生後にお祝いを出すわけですから、健診時には直接云々というような影響はないと思うんだけど、そのあたりはどういうふうに考えているのか。そのあたりを提案者にお聞かせ願いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここのところも、区のほうにもお伺いしたんですが、お金を貸し付けるに当たって一定期間品川区に在住しているということで、６カ月という規定を設けたということでお伺いして、それを参考にして今回６カ月ということにしたわけですけれども、出産してほかに行ってしまうというご心配だということなんですけれども、ここで出される出産費用というのは１５万円ですので、これがもっとすごい多額であれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-003"},{"speaker":"須藤委員","kind":"質問","question":"質問の中で、いわゆる我が国の人口動態というのが１００年、２００年単位できちんと見ていった場合に、近年だけで経済的な云々だけで見るということ自体がどうですかと質問させていただいたんだけども、そのあたりのご回答はなかったように思うので、最初の１点だけ、万が一というのは何かわかっていれば教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-004"},{"speaker":"宮崎副委員長","kind":"意見","question":"それと、どういう想定なのかということなんですけども、はっきり言えば、いろんなことがあるかもしれないということで、こういう規定にしております。実際に、私ども、いわゆる具体的なものがあれば、当初から条例の中に盛り込むということが考えられますけど、いろんなこと、私も想定できないこともあるかと思うので、こういう書き方をしています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-005"},{"speaker":"須藤委員","kind":"意見","question":"条例をつくったりなんかするときは、こういう返還させるということが条例の中に必要ですよというお考えでつくられたということですよね。はい、わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"先ほど来お話ししていますように、我が国の人口動態というのが、何百年単位での増加減少ということで来ているので、そのときのやはり心情的なものというんですかね、気持ち、そういったものをしっかり掌握していきながら対処していかなければ、単に経済的支援というのももちろん大切な一つの要素ではあるけども、一自治体としてどこまでできるということを考えていかなければいけないだろう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-007"},{"speaker":"堺委員","kind":"提案","question":"この条例について、結論から申し上げますと、同意できないといいましょうか、賛成できないというんでしょうか。理由については、今須藤委員からもお話がございました。そういう中の一つに、出産育児一時金についても現行３５万円になっておりますが、これを近い将来５０万円まで引き上げていこうじゃないか、こういうことを既に国会の中で提案をしていますし、議論もしているというふうに聞いております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-008"},{"speaker":"高橋委員","kind":"意見","question":"会派のほうの話は二つ出ました。やはり、品川区の福祉政策の全体、出産を含めた子育て政策、その他でのバランスから見てどうかということと、あとこの条例によって先ほどからお話がありますけども、どういう影響があるかということも含めて、国の政策の審議の動向を見ていくべきではないかという形で、会派としては賛成できないということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"提案","question":"私は提案者の一人なんですけど、今日審議していただきましてありがとうございました。ちょっと今うちのほう以外は賛成できないという態度だったので、非常に残念です。そういう意味でも、今都内２３区の中でも資料にあるようにいろいろやっている。ですから、こういう国の動きを見守るというよりも、国の制度の充実を促進するということが自治体の制度であるというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-010"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この請願なんですが、所得制限を緩和していただきたいということなんですが、今の説明で４割の方が所得が多くて受けられないということでしたけれども、この所得というのは、どれぐらいの額なのかということ、どれぐらいの収入の方が受けられないのかということをひとつ教えていただきたいのと、それとあと、去年の議事録を改めて読んでみたんですけど、この中で、所得制限をつけている区が２３区の中で。","respondent":"高橋幼保一元担当課長","answer":"５区が所得制限をしていますが、これは変わりなく、今年度も引き続き５区に所得制限があるです。","voiceIndex":22,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"年収、４人家族で３人を扶養しているということで７５０万円というのは、１６万２,００１円というのが所得税ですか。そこのところをひとつ教えていただきたいのと、では３２万円というのは、かなり高いのではないかなという感じがするんですけど、３２万円、３３万円、ここのほかの２区というのは同じ条件で言えば、どれぐらいの収入なのかもあわせてお聞かせください。","respondent":"高橋幼保一元担当課長","answer":"申しわけありません。先ほどの税の部分ですけども、特別区民税所得割課税額ということです。そしてもう一点が、２区について約３０万円というところについては、ちょっと手持ちがないのでどのぐらいの収入か、申しわけありませんがわかりません。","voiceIndex":24,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"住民税のフラット化で、一律１０％になりましたけども、それでも所得割額が１３万円ということは、それの１０倍の１３０万円が課税所得額ということで考えていいんですか。たぶんフラット化になって、住民税の所得割課税額ということで、所得制限をつけていくとなれば、所得制限の基準そのものを変えざるを得ないのではないかなというふうに思うんですが、いかがでしょうか。","respondent":"高橋幼保一元担当課長","answer":"その層につきましては、１３万５,０００円の特別区民税の所得割課税額になってあります。","voiceIndex":26,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっとよくわからないんですけど、所得制限がつけられていて、補助の対象にならない方は、全体の４割の方ですよね。それで、６割の方は該当して年間１８万２,８００円。この額が６割の方は全員その額が補助金として支給されていて、４割の方は全員が支給ゼロということで、そう考えていいんでしょうか。","respondent":"高橋幼保一元担当課長","answer":"一番多い４ランクにつきましては、公私立の格差というところでは、私立のほうが１万９,９００円の年間負担になっていまして、月額にすると１,６００円ぐらいの負担を公立よりもしているという状況になります。","voiceIndex":28,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、どちらにしても、この、４人家族で７５０万円の年収です。そういうところからすれば、救貧対策ということではなくて、子育て支援というところで、ほとんどの区がそういう形でやっているわけですから、所得制限をなくすという方向で足を踏み出すべきではないかと思うんですが、いかがでしょうか。","respondent":"高橋幼保一元担当課長","answer":"今のご質問、所得制限をなくすべきではないかというお話ですが、これは、趣旨としては保護者の経済的負担を軽減する観点と、公私立の保護者の負担の較差の是正ということでございまして、先ほど細かくてわかりにくいご説明をしてしまったんですけれども、所得の低い方というか。","voiceIndex":30,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの中でも、本当に生活に占める教育費の負担増というのが大変で、税金、教育費の負担が多くて、子どもといる時間も割いて仕事をせざるを得ないと、そういうふうなことも訴えられていますし、この所得制限はぜひ子育て支援を充実させていくという観点から、なくしていくという方向でぜひご検討いただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-016"},{"speaker":"須藤委員","kind":"質問","question":"今請願のほうを見ていると、所得制限を撤廃してくれというようなことはうたっていない。ですから、行政自体も全体のバランスをとりながら税金を使っていく仕組みをつくっていかなければいけないと思うので、そのあたりは、この請願は「制限を緩和していただきたく」というような表現になっているので、我々委員会としても間違いないようにしなければいけないなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、去年に比べて保育料が値上げをされて、区立と１,６００円の差が生じているということなんですけれども、毎年３.２％から５％の値上げがされていくということで、先ほどご説明ありましたが、この値上げの根拠というのはどういうことで値上げをせざるを得ないということなのか、お聞かせいただきたいと思います。","respondent":"高橋幼保一元担当課長","answer":"値上げの根拠というのは、ちょっとお話を私立幼稚園に聞いていないのでわからないんですけれども、２０園ございまして、２０園が毎年上げているというわけではなくて、ある一定の年度が来たら値上げをするということですので。","voiceIndex":34,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区立の幼稚園と差がどんどん開いてくるというふうなところですが、去年９０５円から今年１,６００円の開きがあるというところでは、この値上げに合わせた形で差は広げない。できるだけ区立幼稚園に近づけるということで、補助金を上げていくべきではないかと思うんですが、そこら辺の考え方はいかがでしょうか。","respondent":"高橋幼保一元担当課長","answer":"私立の保護者の負担ということでは、平成１９年度、先ほど請願の中でも感謝の言葉で申し上げられていましたけれども、私立幼稚園協会と、それから全園児に対して所得制限のない入園料に対する補助金を８万５,０００円から１０万円にしたところと。","voiceIndex":36,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ差がどんどん広がっていくということがないような補助金を考えていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-020"},{"speaker":"堺委員","kind":"質問","question":"今ご説明いただいた平成１７年度で９０５円、平成１８年度が１,６００円、平成１９年度はまだ具体的な金額というのは出ていないんですか。その辺ちょっと教えてください。","respondent":"高橋幼保一元担当課長","answer":"これまでベースとして決算が出てからということでやってきましたので、平成１９年度大枠では見えているところもあるんですけれども、請願についての説明は、いつも決算が出た時点でということでさせていただいていますので、それはもうしばらくお待ちいただきたいと思います。","voiceIndex":39,"id":"exchange-021"},{"speaker":"堺委員","kind":"質問","question":"今の質疑のやりとりの中で、少し理解できてきたんですが、それによると、入園料補助金が８万５,０００円から１０万円に、保護者の負担軽減策としてなど、いわゆるそれなりに区として私立幼稚園、あるいは私立幼稚園に通わせる保護者の、要するに公私格差の是正という面からの努力はしてきていますというふうに今の説明の中では理解できたんですが、それでも。","respondent":"高橋幼保一元担当課長","answer":"そのほかに、入園料補助金は今回１０万円にさせていただいたところなんですけれども、入園料につきましては、平均で１１万５,５００円というところで１０万円の補助をすることによって、その分が幾分か軽減になったということで、全体をあわせてやると。","voiceIndex":41,"id":"exchange-022"},{"speaker":"須藤委員","kind":"質問","question":"我々未就学児のお子さんたちの教育という点でいろいろ行政にお願いをしてきているんですけれども、私立の幼稚園のお子さんたちというか、そういう状況について、行政との連携はどういうふうになっているのかなと。行政がいわゆる保育園、幼稚園、そういうお子さんたちに学校に上がる前の教育連携というのをきちんとされているかどうか、そのあたりを教えてください。","respondent":"高橋幼保一元担当課長","answer":"そういう中で、確かに私立幼稚園におきましては、未就学の３歳未満児の保育も週に２回とかやってくださっているところもあり、私立幼稚園協会全体としては、先ほどもお話ししましたように、子育て支援ということで、百反にある金春湯のところで、１歳児、２歳児について。","voiceIndex":43,"id":"exchange-023"},{"speaker":"須藤委員","kind":"意見","question":"ここはあくまでも私立幼稚園ということで請願が出されているので、私立幼稚園は私立幼稚園のよさというものをそれなりにつくってもらわないと、全部が公立と同じになってしまうというのもまたおかしなもので、ただ、連携をやはりとっていくということは、お子さんたちにとっても大切なことなので、それなりの請願内容に趣旨的には了解すると考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-024"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと１点だけ伺いたいんですけれども、園児保護者補助金の趣旨からいって、所得制限があるということは、私、どうもちょっとよく理解できないんですが、私は所得制限そのものは緩和というよりも、なくしたほうがいいというふうに思うんですけども、例えば子ども医療費の場合ですと、所得制限なしにしたわけですよね。","respondent":"高橋幼保一元担当課長","answer":"この制度自体に所得制限を設けるということはどういうことなのかというようなお尋ねですが、もともと私立幼稚園で幼児教育を受けたい方々に、義務教育ではないという部分が一つありまして、あともう一つは、やはり均等にどの子にも幼児教育を受けさせたい。","voiceIndex":46,"id":"exchange-025"},{"speaker":"宮崎副委員長","kind":"質問","question":"ですから、公私で義務ではないとか、そういうことでいくと、なかなかこれは私は理解がよくできないなと思うんですよね。ですから、均等にということであれば、私はこれが所得制限を設けている意味にならないのではないかというふうにますます思えてしようがないんですけども、そこのところを何かもう少しわかるような説明をお願いしたいと思います。","respondent":"古川児童保健事業部長","answer":"まさに公立私立の幼稚園の置かれている状況はそれぞれありますが、公立に比較していかがなものかというような視点、そういった部分を考えますと、ここで述べられている請願の趣旨については、私は理解をいたしますが、制度のあり方としては、先ほど来課長が申し上げているように。","voiceIndex":48,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、平成８年までは所得制限がなかったわけですから、それから、１８区はそのまま所得制限なしでやっているわけですから、だから、品川区でもやっぱり所得制限をここでは緩和してくださいということですけども、そういうことで言えば、それまでは所得制限がなかったということから考えると、今までの説明というのは単に東京都が補助金をあれしたからというふうなことということなのか。","respondent":"古川児童保健事業部長","answer":"将来この制度がどう変わっていくかは、またそのときどきの社会状況なり、あるいは少子化対策、さまざまな施策をバランスよくとらえて進めていくものだ、こう思っております。","voiceIndex":50,"id":"exchange-027"},{"speaker":"須藤委員","kind":"質問・要望","question":"私は結論を出していただきたいと思います。それと、結論の出し方も、内容的にすべてストレートにという考えでなくて、趣旨的には、内容的には理解できますよというような形で、趣旨での採択ということも配慮していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-028"},{"speaker":"堺委員","kind":"意見","question":"私も、今日この件については結論を出すということで、気持ちとしては、やっぱり今自民党の須藤委員がおっしゃっていましたように十分理解できますので、ただ、先ほど来から理事者のほうからもご説明いただきましたように、この中では、ここ数年多少是正されてまいりました公私の教育費格差という問題が、再び拡大されるのではと強く懸念しておりますと、こんな趣旨のお話等も出ておりますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今までも審議を通じましても、やっぱり２３区の中で５区しか所得制限はとっているところがないという状況の中で、この前の条例でも提案をさせていただきましたけれども、そこの中で１００年を見通したというふうなところでは、ちょっとこちらの意見も言いそびれてしまった部分があるんですが、本当に少子化というのは大変な状況で、これをこのまま放置すると。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-030"},{"speaker":"須藤委員","kind":"意見","question":"先ほど来所得制限なしとかありとかいろんな話が出て、本当にこのあたりはしっかり情勢を見ないと、医療費についてだって、それぞれ親御さんが保険料をそれなりに納めているとか、全体のいろんな状況があるので、ここだけ見て所得制限を撤廃するしない、他区がどうだからということではないと思うので、内容的には、まして請願者が緩和してくださいという表現がされているのを。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-031"},{"speaker":"本間委員","kind":"質問・要望","question":"私どものほうでも一応紹介議員になっております。そのような関係もありますし、先ほどいろいろやりとりも聞きましたし、十分行政側のお話の趣旨を理解しているというふうなこともありますので、この件につきましては、私どもはこうせいああせいというよりも、十分この趣旨をくんでいただきたいということで、趣旨採択を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-032"},{"speaker":"高橋委員","kind":"意見","question":"無所属クラブのほうも、趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-033"},{"speaker":"堺委員","kind":"意見","question":"そういう面では、改めて保護者の経済的な不安も解消されて、安心して子どもを私立幼稚園に預けられる、そういう意味での行政が取り組んでいただく配慮という面でも、いろいろお願いできればありがたい、こういう意味で、この件については趣旨採択ということでお願いをしたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここにあります重度障害者の在宅生活における人工呼吸器云々と書かれているわけですが、こういう重度障害の、人工呼吸器をつけているような特に重度の方が大変な状況にあるのかなというふうに思うんですが、人工呼吸器をつけながら在宅生活をされている方というのは、この品川区でどれぐらいの方がいらっしゃるのか。","respondent":"高橋障害者福祉課長","answer":"人工呼吸器をつけている方の人数はちょっとつかんでおりませんが、障害者の福祉サービスを利用しながら、訪問看護を利用している方は、現在７名の方がおられます。","voiceIndex":71,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者の福祉サービスを受けながら訪問看護、これは医療のほうの訪問看護ということになるんでしょうか。こういう人工呼吸器をつけながら在宅生活をされている方の実態というのは、区としてはつかまれているんでしょうか、そこら辺のところもお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"人工呼吸器を使いながら在宅医療をし、なおかつ訪問介護を利用している方は、先ほど申し上げたとおり７名の方です。","voiceIndex":73,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"たぶん熱を出したとか、急にぐあいが悪くなったとか、そういう急性疾患になったときは、ドクターの指示があれば毎日２週間までは訪問できるという仕組みがあると思うんですけど、ここで言われているのは、もっとこの日常的な訪問看護のいっとき、１時間や１時間半来てもらうだけでは足りないというところを何とか埋めてほしいということだというふうに聞きました。","respondent":"高橋障害者福祉課長","answer":"したがいまして、急遽必要になれば、救急車、もしくは訪問の医師が来ていただくというような状況だと思いますので、ここの中で、在宅生活を継続できる中で訪問看護師を派遣するということについては、今の医療制度、また福祉サービスの中で役割分担しておりますので。","voiceIndex":75,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もちろん急にぐあいが悪くなって病院に行かなくてはいけないとかというときは、救急車を呼べば、それで対応できると思うんですが、通院というときも人工呼吸器をつけながら通院するということになると、たぶんヘルパーではなかなか難しいということがあるというふうに思うんですね。そこのところはいかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"現在のところ、そういう制度はございませんが、ただ、ショートステイということで、医療的な必要があれば、東京都の療育センター等を利用しながら、家族の方が急に必要となったときは、そちらのほうに預けながら在宅生活を送っていただいているというふうに思っております。","voiceIndex":77,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当にこういう方は数も少ないので、実態というのを理解するのがなかなか困難ということはありますけれども、それでもこういう中で、本当に３６５日２４時間気を抜かずに頑張り続けている、その父母を応援するという形で、私はこういう制度の狭間のところでの対応ができるような制度、本来であれば、私は区でこういうのがあってもいいのかなというふうな思いもしているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-039"},{"speaker":"山元委員","kind":"意見","question":"先ほど課長のほうの話の中で、ちょっと耳に引っかかったものがあるんですが、この文面の中に日常的医療的ケア云々というお話をされた後に、矛盾があると一言おっしゃったんですね。その矛盾というのはどういうことなのか、ご説明いただければと思います。","respondent":"高橋障害者福祉課長","answer":"現在も医師が指示書を書き、看護師を派遣できるような医療制度ということでは、健康保険法または介護保険法による派遣の制度はありますので、その辺についての制度的なところがちょっといかがなものかというふうに感じたところです。","voiceIndex":80,"id":"exchange-040"},{"speaker":"堺委員","kind":"質問・要望","question":"確認をさせていただけますか。したがって、それに基づいての看護師の派遣は行われていますよと。したがって、今できる範囲の中での対応については、現在行われているんですよというふうな説明に聞こえたんですが、そういうふうに我々が理解をしていいのかどうかをちょっと確認したいんです。","respondent":"高橋障害者福祉課長","answer":"委員おっしゃるとおり、現在、健康保険法、介護保険法による医師からの指示書に基づき、看護師が行う訪問看護制度はあります。それが実態です。そして、生活を継続するためには、障害者自立支援法の訪問介護または先ほどの医療とあわせて生活を継続しているというのが実態です。","voiceIndex":82,"id":"exchange-041"},{"speaker":"堺委員","kind":"質問・要望","question":"これはやはりそういう方を抱えているご家庭でなければわからない、いろいろな要請かなという気はするんですね。したがって、これからもいろいろな形でこういう方々へのサポートについて極力、できることについては順次改善をしながら対応をしていただければ大変ありがたいなと、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-042"},{"speaker":"須藤委員","kind":"質問","question":"介護保険制度ができてきて、こういったいろいろな支援法とそれから医療保険制度とだんだんとそれが接点というか、重なってくるような場面というのがいろいろ出てこようかと思うので、ここでは文章なんかを読んでいると、排泄や入浴、通院等という、いわゆる介護支援的な、いわゆる障害者の支援的なものと医療とをくっつけてしまうような仕組みをつくりなさいというような表現に読めてきてしまうんだけども。","respondent":"木下福祉高齢事業部長","answer":"介護と医療の切り分けという部分では、平成１２年に介護保険がスタートしたわけですけれども、当時医療保険で対応していたものを介護に移行したのがこの訪問看護の部分と、それから老人保健施設であったわけであります。","voiceIndex":85,"id":"exchange-043"},{"speaker":"須藤委員","kind":"質問","question":"我々も障害者の方々といろいろな意見交換をさせていただいています。ですから、国へ医療制度云々という意見書を持っていくというのは、このとおりにはなかなか困難だなというふうには思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-044"},{"speaker":"須藤委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。先ほどちょっと理事者に質問したように、この制度自体を混乱させるというような方向性というのはなかなか議会として出しにくいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本日、結論を出すということでお願いしたいと思います。態度は、趣旨採択でお願いしたいと思います。そういうふうなところをヘルパーが障害者のほうで見てもらえているように、看護師として認めてほしいというのがこの請願の趣旨だと思いますので、ぜひ趣旨採択ということでお願いしていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-046"},{"speaker":"本間委員","kind":"質問","question":"既にお話が出ておりますように、医療制度と福祉サービスの非常に難しい部分も含まれてはおるようですけれども、それぞれの立場でそれぞれのサービスなり機関があるわけですから、それを十分連携をとりながら上手にサービスを使っていくということが大事だというふうに思います。この件については、少し無理な部分がありますので、私どもは願意に沿いがたいということで結論を出しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-047"},{"speaker":"堺委員","kind":"質問・要望","question":"本日、結論を出すということで申し上げます。態度につきましては、この件につきましては、私も先ほど何点か確認をさせていただき、なおかつ要請、要望させていただきました。ただ、この本請願につきましては、先ほど課長あるいは部長からご答弁がございましたように、この請願そのものについては願意に沿いがたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-048"},{"speaker":"須藤委員","kind":"意見","question":"請願の前のほうで、趣旨の中で「毎日の保育にゆとりがなく、在園児にも地域の子にも手が行き届いた保育ができない状況です」というふうにうたってあるんですけれども、このあたりは保育課のほうはどういうふうに考えておりますか。","respondent":"小林保育課長","answer":"日ごろの保育園の運営に当たっては、職員の配置、こちらは国の基準配置を基本としながらも、状況に応じた配置をし、また各園の中で協力体制等を踏まえて円滑に運営されているというふうに考えております。","voiceIndex":103,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"待機児解消のところなんですけれども、今年の４月の時点で、認可保育園に申し込んだ人数が、今年の４月というか、１月が締め切りだと思いますけれども、４月から入るというふうなことで審査会にかかった認可保育園の申込者の人数と、入れた人数を教えてください。","respondent":"小林保育課長","answer":"入園実績のお尋ねですけれども、直近の平成１９年度につきましては、４月１日の入園を前提にいたしまして、新規の申込者が１,３３８名、入園児は９７４名という状況です。","voiceIndex":105,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、３６４名の方が認可保育園に申し込んでも入れなかったということで考えていいのでしょうか。それが一点です。それともう１つ、現在の認可保育園に申込者がどれくらいあるのかということを教えていただきたいと思います。何保育園で何名という定数が増えたのかということを教えていただきたい。","respondent":"小林保育課長","answer":"入園実績のお話ですが、先ほどご報告した数の相差、こちらには転園希望等もありますので、具体的に３月末の時点で申し込みを出したんだけれども、まだ入っていない状態だった方は１８７名です。","voiceIndex":107,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つ、次のところの認証保育所なんですけれども、認証保育所では、運営費の２分の１が区のほうから補助金として出ているということなんですが、これはもともとは東京都のほうからも出ていたと思うんですが、それが品川区からだけというふうなことで今、全額区の負担というふうなことでご説明がありましたけれども、この経過というか。","respondent":"小林保育課長","answer":"そういった数字になります。ただ、これが比較が難しいと申しますのは、認証保育所は、先ほどご説明いたしましたように、補助のほかに保育料を加えて運営しているところから比べますと、その保育料を加えた額と支弁単価とを比べるという考え方もあるかと思います。","voiceIndex":109,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この１２万３,５７０円ですか、０歳児で運営費補助ということで出されているということで、１つ確認をさせていただきたいのは、この４月から、今までは東京都が５０％、品川区が５０％という、こういう形で出されていたものが、財調の算定になってしまったということで、区としてどこにでも使えるという一般財源にこの東京都からのお金の来方が変わってしまったということですよね。それが一点。","respondent":"小林保育課長","answer":"つまり、提供しているサービスが違う。したがって、一概に区の運営費が認証保育所に比べて極めて高いのかというふうには考えておりませんが、ただ、私どもも日ごろの運営の中でなお一層効率的に喜ばれるサービスに対応できるように努力をしてまいる所存です。","voiceIndex":111,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今まで私は保育園の、特に０歳児はこんなにお金がかかっていると、こういう話ばかりずっと聞いてきましたので、認証保育所の保育にかかっているお金と、区のかかっているお金が変わりないという、保育の時間とか、そういうふうなことで言えば、変わりないというふうなことには、ちょっと驚くんですけれども、ということは、品川区の公立保育園の０歳児で５４万２,０００円という、この数字というのは。","respondent":"小林保育課長","answer":"もう１点、認可保育園が、そうは言っても認証保育所の倍以上なんだからむだが多いのかという点ですけれども、先ほど申し上げましたように、区の認可保育園ではいろいろなサービスを展開しておりますので、認証保育所では対応できない役割を果たしている、それから言うと。","voiceIndex":113,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう本当に４月の段階では７割というお話もありましたけれども、アルバイトに出ざるを得ないというふうな話も聞いていますし、何と言ってもここで働く保育士の賃金がすごく安くて、年収が３００万円も行かないという中で、本当にこの保育士の頑張りのおかげで成り立っているというのがこの認証保育所の運営の実態だというお話もお聞きしているんですが、ぜひ私は改めて財調ということにはなりましたけれども。","respondent":"諸岡児童課長","answer":"遊具及び備品等の更新といいますか、買い替えですけれども、こちらのほうも基本的には計画的に老朽備品の買い替えということで毎年の予算編成の中で対応していっているところです。","voiceIndex":115,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際に機械的にはできないというのはあると思うんですけれども、ここにこういうふうに書かれているような実態というのは多分あるんじゃないかなというふうに思いますので、ぜひ使いやすいものに変えていただくように要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-056"},{"speaker":"須藤委員","kind":"質問","question":"今、品川区の保育園では全体でどのくらいのお子さんたちをお預かりしているんですか。全部のトータルでは。","respondent":"小林保育課長","answer":"認可保育園では０歳児から５歳児まで、これは定数ではなくて４月１日の在園児数でご報告いたしますと、３,５５１名。これに私立保育園６４２名を加えまして、合計で４,１９３名の在園児がおります。","voiceIndex":118,"id":"exchange-057"},{"speaker":"須藤委員","kind":"質問","question":"４,１９３名、この請願自体が２,６３５名の方の請願書ですよね。いわゆる請願者の数というのかな、保育園に本当に問題があるというのでしたら、もっと多くの声が上がってくるのではないかと思うことと、それから、昨年度のそういったことについて、そういう資料が町の中に入っているということ自体がちょっとおかしいなと思うんだけれども、そのあたりのお考えを教えてください。","respondent":"小林保育課長、諸岡児童課長","answer":"いずれにしましても、区の保育、認証保育所も含めてですけれども、それに対して区民の支持をいただけているのかなという認識です。これは昨年、東京都のほうでそういった制度の変更を打ち出してまいりまして、ただし東京都のほうは所得制限があり、また自己負担を伴うものでございましたが、それをきっかけにして各区のほうでそれぞれ区においての対応を考えたです。","voiceIndex":120,"id":"exchange-058"},{"speaker":"須藤委員","kind":"意見","question":"我々も議会のほうで夜間保育をしてくださいというような、医者の先生あるいは看護師とか、夜間勤務される区民の方々からそういう仕組みをつくってくれと大分前に言われて、なかなか２３区でつくろうという意識がないときに、品川区は保育園の勤務の方々にご理解をいただきながら、そういう仕組みをつくっていただいたり、延長保育をやっていただいたりという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-059"},{"speaker":"宮崎副委員長","kind":"質問","question":"二点ほど伺いたい。今のお話だと、実際に例えばこういう遊具だとこのぐらいの間隔で取り替える、あるいは、専門的な知識を持っている方がちゃんと見るだとか、何かそういう一定の考え方があるのかなと思うんですが、そこら辺のところはどういうふうにされていますか。","respondent":"諸岡児童課長","answer":"その安全確認の中で問題が起きれば、ただちに対応し、また老朽化が激しいために安全面で問題があるということであれば、これは最優先でただちに対応を図っていくです。","voiceIndex":124,"id":"exchange-060"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"もう１つ、認証保育所のほうなんですけれども、先ほど課長は認証保育所について、この請願のほうでは運営は大変苦しいものになっていますと、そういうふうに訴えているんですけれども、課長のほうは全部経営は順調ですというお話だったんですけれども、大分見解が違うかなというふうに思ったんですけれども、そこのところは、運営が順調だというのは、請願のほうとはちょっと違うんですけれども。","respondent":"小林保育課長","answer":"先ほどご指摘の期間によって増減があるのもありますけれども、それは逆に企業体としての努力で人員調整等を自社内で行っているところもありますので、そういった意味では柔軟に対応する、そういった体制が生かされているのかなというふうに認識し、総体といたしまして。","voiceIndex":126,"id":"exchange-061"},{"speaker":"宮崎副委員長","kind":"質問","question":"その一方では、認証保育所も開園してきているんですけれども、そういうところでまだまだ待機児も出ているといった、今日の説明でも４月１日以降、７０名、そういうお話だったんですけれども、今、認証保育所にウエイト、私はそういうふうに移してきたかなと思うんですけれども、なかなかそれに見合った数ができていないのかなというふうにも一方では思うんですけれども、区のほうは。","respondent":"小林保育課長、古川児童保健事業部長","answer":"ただ、一時的にすべての需要に対応するということは困難ですので、そういった意味で、結果的に認証保育所が都市部における需要の一部を代替しているということについては、そのとおりだけれども。したがいまして、基本的には品川区、認可保育園が中心となってさまざまな保育需要にこたえてまいりましたけれども、当然に認証保育所が今後さまざまな展開をしていく素地はあるわけでありますので、認可保育園は当然基本ではありますが。","voiceIndex":128,"id":"exchange-062"},{"speaker":"宮崎副委員長","kind":"質問","question":"私は現実問題、待機児がいるというのは、やはりそれだけのニーズがあるわけですよね。先ほど、区のほうの認可保育園が基本的な役割を果たしているという、そういう趣旨の答弁だったと思うんですけれども、もう一度、現在では７０名という待機児をどういうふうに解消していくのか、その基本的な考え方を伺っておきたいと思います。","respondent":"小林保育課長","answer":"待機児の解消に向けましては、現在運営しております認可保育園を軸としながらも、その認可保育園の弾力化、あるいは施設計画の工夫、認証保育所の活用、そういったいろいろな方策を総合的に活用して、それぞれの地域の需要を充足していくように努めた結果、結果的に待機児が減る。","voiceIndex":131,"id":"exchange-063"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"私の知り合いでも、認可を申し込みながら入れなくて認証保育所に入った方もいましたけれども、やっぱり一番の問題は保育料なんです。この負担は非常に重いというふうに思います。このところの保護者の負担軽減と保育園の運営改善、この２つの面から要望が出されていますけれども、この負担軽減、こっちのほうについてはどういうふうにお考えでしょうか。","respondent":"小林保育課長","answer":"一般的に子育ての時期についてはかなりの負担が発生しますので、それにつきましては、負担の推移を見極めながら保育料の水準を検討してまいりたいと考えております。","voiceIndex":133,"id":"exchange-064"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"先月、行政視察に行った先では保育料の減額なんかも断行して子育て支援をやっておりましたけれども、私は今の格差貧困と言われる中で、今、とりわけ働き盛りの収入が落ちているという中では、ぜひ保護者の負担軽減等も大いに取り組んでいただきたいなというふうに思います。このことを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-065"},{"speaker":"堺委員","kind":"確認","question":"明日ご説明いただけるのだと思いますが、そういういわゆる小中一貫校の施設建設に伴ってと言っていいのでしょうか、そういう流れの中で、いわゆる幼保の受入施設といいましょうか、そういうものが拡大されていくように見受けられるんですが、そういったものも当然こういう待機児解消のための方策の一環として、もう既にスケジュール化されていると。その辺をちょっと確認させていただけますか。","respondent":"小林保育課長","answer":"委員ご指摘の一体施設の取り組み、あるいは原小学校等も含めた認可保育園あるいは認定こども園等につきましても、子どもの健やかな保育、教育が達成できる環境を必要な需要に応じて対応していくという形で計画をしているその途上にある成果というふうに考えております。","voiceIndex":136,"id":"exchange-066"},{"speaker":"堺委員","kind":"質問・要望","question":"大変なんだから、すぐ区のほうから補助金をよこせというのでは意味がないだろう。そういう意味から、請願趣旨あるいは請願項目に述べられておられるようなことについては、相当、請願を出された側から見ればご不満もあるかもしれませんが、区当局については大変な努力もしていただいているというふうに私は理解ができるんですけれども、その辺についてもう１回確認の意味で教えていただきたいと思います。","respondent":"小林保育課長","answer":"各保育事業についてのお求め、これにつきましては、そのニーズを真摯に受けとめて対応していく所存ですが、現在いただいている項目につきましては、それぞれ成果を一定収め、一定の水準が確保できているという印象を持っております。","voiceIndex":138,"id":"exchange-067"},{"speaker":"須藤委員","kind":"意見","question":"私どもは、内容的には、我々がいろいろ言っているところなんですが、いろいろ経緯等々もございまして、今、理事者からご答弁いただきました、それなりの対応をしているということで、あえてここで請願を上げていく必要はないというふうに考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-068"},{"speaker":"堺委員","kind":"質問・要望","question":"私も、今、意見要望等も含めて理事者のお考えもお尋ねをさせていただいたわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、採択を主張したいと思います。そういうところでぜひこれは見ていただいて、補助金の増額もしていただきたいし、また認証保育所に預ける子どもの父母に対しての負担軽減、これも私たち共産党も随分前から求めてきているものですけれども、ぜひこの負担軽減についても取り組んでいただきたい、特にこの２点を申し上げて採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-070"},{"speaker":"本間委員","kind":"確認","question":"児童センターの件につきましても、遊具等の件につきましては、安全確認をきちっとやっているということと、着々と施設整備、改修を進めてきているということをもってして、きちんとした努力が進められているですので、この出されました請願項目につきましては、願意に沿いがたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その辺も含めて今後はどういう状況なのかということを聞きながら、今年度は既に予算編成が終わっていますので無理ですが、先々の研究課題にさせていただきたいと、こういうふうに答弁されているんですけれども、その結果、どうだったでしょうか。お聞かせください。","respondent":"高橋障害者福祉課長","answer":"この間、他区の状況も含めまして研究しています。団体の方にもちょっとお聞きしたことがありますが、今のところ、そういう要望が、あったらいいねというご希望はありますが、特にどうしてもというようなご意見はございませんでした。","voiceIndex":159,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"視覚障害者の団体の方にも聞いていただいたのでしょうか。","respondent":"高橋障害者福祉課長","answer":"障害者７団体懇談会の中でお聞きしました。","voiceIndex":161,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしたら、まだ来ていないということを言われたんです。会としてもぜひこれを実現させる方向で取り組んでいきたいし、今年はもう要望書を出してしまったので、その中には載せられなかったけれども、今後は要望書の中にもぜひ載せていきたいということで言われていたんです。そういう点では、今の課長の答弁と随分違うんですけれども、どうなっているのでしょうか。","respondent":"高橋障害者福祉課長","answer":"この状態像から考えると、やはり私どもも検討していく余地があるのかなというふうに思っておりますので、今年度、検討を進めさせていただいている状況です。","voiceIndex":163,"id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この議事録を見ると、今までこういう要望は出てこなかったので、今度はその視覚障害者の団体にも聞いて、そして研究をするということで答弁されていたんですが、このことは、されていなかったということなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"団体の会長には直接お聞きしていませんが、懇談会の後に障害者団体の方が参加されてましたので、そのときにお聞きしたところです。","voiceIndex":165,"id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、品川区は１カ月２,３００円で、年間２万７,６００円ということで、これは２３区の中でも下から２番目という、そういう支給の額になっていますけれども、この制度そのものがいつからできて、支給額がどう変化してきたのか、また２,３００円の根拠というのはどう考えているのか、このことについてお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"そのときの金額についてはちょっと経過もわかりませんが、平成１６年からは同じ金額でやっている状況です。他区の状況につきましては、視覚障害者のところについては、品川区と同様はほかに１区です。ほかの区につきましては、視覚障害２級まで拡大されているところです。","voiceIndex":167,"id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"なぜ２,３００円という額なのか、この根拠について先ほどお聞きしましたので、この答弁をお願いしたいということと、あと、他区の状況というのは、視覚障害の２級を対象にしていないのは、品川区ともう１区だけだというのは前の委員会でもそういう答弁はありましたし、それ以外に他区の状況を調査してどうだったのかというところでの新たな区の認識というふうなところはないでしょうか。","respondent":"高橋障害者福祉課長","answer":"金額についても各区の財政状況、また地域状況によりかなりばらつきがございまして、２万円台から７万円台まであるということがわかった状況です。","voiceIndex":169,"id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、本当に失明してしまったためにそういう生活を余儀なくされる、そういう方にその生活を拡大するということで出されているのがこの福祉タクシー券ということだと思いますので、視覚障害の２級を対象にしてもらいたい、このことが切実な願いの１点ですけれども、同時に、この２,３００円というのを拡大してほしいというふうに思うんですけれども、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"それと、視覚障害２級の方につきましては、先ほど申し上げたとおり、やはり検討していく必要があるのかなということは感じております。","voiceIndex":171,"id":"exchange-078"},{"speaker":"須藤委員","kind":"質問・要望","question":"一時、福祉タクシー券ももう少し出していたような気がしたんですけれども、それがどこかで換金されたりなんかというような話もちらっと聞いていたりなんかするので、最初のスタートの時点、それから現状使われた状況、そういったもののあり方をちょっと教えていただきたいのと、それから、今度、都内のタクシーで値上げが１２月３日から始まりますよというのはもう既に案内されているので、そうした場合に。","respondent":"高橋障害者福祉課長","answer":"金額の問題につきましては、なかなか相当な人数ですので、検討していきますが、難しいかなというふうには感じておりますが、ただ、対象のところにつきましては、先ほども申し上げたとおり、視覚障害２級の方につきましては。","voiceIndex":173,"id":"exchange-079"},{"speaker":"須藤委員","kind":"質問","question":"いろいろな事情で障害者という立場になられた方にできるだけ社会参加してもらう仕組みづくりは大切だと思うんですけれども、やはりそれに対して、今、品川区でも、福祉タクシー券が金券ショップに流れているよという調査をしてもらって、全部が全部ではないんですけれども、そういう使われ方をしたというのも現実に我々は見てきていますので、そうした場合に、本当にその人たちが社会復帰できるような立場。","respondent":"高橋障害者福祉課長","answer":"委員おっしゃるとおり、全体の状況を見ながら検討を進めしますので、その辺のことをご理解いただければと思います。","voiceIndex":175,"id":"exchange-080"},{"speaker":"須藤委員","kind":"質問","question":"今話に出ている、北海道でやはり通院するので生活保護の人がタクシーのところと提携して何億円という費用をと、そんなふうなものも出てきて、そういう人ばかりではないと思うけれども、こういったせっかくのサービス自体が本当に理解できるような仕組みづくりというものが大切だなというふうにつくづく思います。ですから、そのあたりも考えておいていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-081"},{"speaker":"高橋委員","kind":"質問","question":"視覚障害の２級の方をもしここで対象にすると、何人ぐらい増えて、予算的には幾らぐらい増えることになるのでしょうか。","respondent":"高橋障害者福祉課長","answer":"２級の方ですと、今、１５５人程度です。この方が重複の場合でしたら除かれるかと思いますが、それで４３０万円程度、ざっと計算したところそのぐらいの数字になります。","voiceIndex":178,"id":"exchange-082"},{"speaker":"堺委員","kind":"確認","question":"先ほどお話が出ていました今年の２月の厚生委員会のときのやりとりの中で、当時の課長が今もちょっとお話に出ていましたような福祉タクシー券の不正利用という課題がありますと。これは私どもは中身を確認できませんので、それ以上は現在、追及はもちろんしておりませんけれども、ある区では、チケットとして売っている現場を押さえたというようなこともございました。","respondent":"高橋障害者福祉課長","answer":"それが適切かどうかというのは、ちょっといかがなものかというのもあるし、どれがいいのかということで、今、研究させていただいていますが、検討の俎上に乗っているのが、通し番号なり、ナンバーリングを打つのを１つの方法ということで考えています。","voiceIndex":180,"id":"exchange-083"},{"speaker":"堺委員","kind":"確認","question":"意地悪な質問をして申しわけないんですけれども、やはり２月にそういうやりとりがあったので、今申し上げたように、せっかくのいいサービスが一部の方のそういう行為によって区民の皆さんからご批判をされるようなことになってはいけないので、ちょっとお尋ねをさせていただきました。その辺についてご見解をもう１回確認していきたいと思います。","respondent":"高橋障害者福祉課長、木下福祉高齢事業部長","answer":"堺委員がおっしゃったとおり、こちらのこともありましたので、私としましては、来年度に向けて検討を進めていたところですのでそういう発言になったかと思います。タクシー券に問題が絞られておりますけれども、タクシー券の今後のあり方という部分では、先ほど課長が申し上げましたように、視覚障害の２級については検討課題ということと、それから金額の問題については。","voiceIndex":182,"id":"exchange-084"},{"speaker":"須藤委員","kind":"意見","question":"先ほど来ちょっとお話ししていますように、通院に全部費用を出しますよというと、またこれは大変な金額になってこようかと思うので、そういった全体の社会参加という意図を酌みながら、内容的には趣旨として採択していただいて、タクシー券ではなくて福祉タクシーがあったり、そちらのほうをどういうふうに重点的に見ていくんだとか、先ほど来お話に出ましたまちづくりの中で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":193,"id":"exchange-085"},{"speaker":"堺委員","kind":"質問","question":"我々も今お話がありましたように趣旨採択ということで取り扱いをいただければと思います。部長からもお話がございましたように、やはり福祉のまちづくりという視点からとらえれば、相互の支え合い、よく言われる自助、共助、公助というんですか、あるいは最近では協働というような言葉も出ているようです。ぜひこの辺については趣旨採択ということでお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は採択を主張したいと思いますが、皆さんが趣旨採択ということで一致できるのであれば、趣旨採択でも結構です。視覚障害２級については、区のほうも検討していただけるということですので、ぜひ来年度予算で実現できるようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-087"},{"speaker":"本間委員","kind":"質問・要望","question":"私どももこの請願につきましては、会派で紹介議員になっております。そのような観点から、さまざまなお話をお伺いしました。視覚障害者に対する支援の仕方は幅広い支援策が必要であるというお話もお伺いいたしました。１、２それぞれこれ、あわせまして、趣旨採択という形で意を酌んでいただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-088"},{"speaker":"高橋委員","kind":"意見","question":"私たちの会派も紹介議員になっておりまして、予算的にもある程度見えていますし、検討対象ということも課長がおっしゃっていましたので、福祉のまちづくり全体の視点として、ぜひ趣旨採択という形でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":197,"id":"exchange-089"},{"speaker":"須藤委員","kind":"質問・要望","question":"説明いただいたので、ちょっともう１回確認させてもらいますけれども、現状では、前期に１回、後期に１回、公費で健診を行っていますよという、そのほかに国保連で前期に２回、後期に２回ということなのかな。そのあたりをもう１回ちょっと教えていただきたいと思います。その人の状況によっても対応は違うと思うんだけれども、どのくらいの回数を受けられているでしょうか。","respondent":"太田健康課長","answer":"１点目のご質問ですが、説明を複雑にして申しわけございません。現状では前期に１回、後期に１回、都合２回の健診について公費負担で実施をしています。","voiceIndex":205,"id":"exchange-090"},{"speaker":"須藤委員","kind":"質問","question":"さっき言った受診票を持っていけば云々というのは、その１回、１回ということを言っているということですか。","respondent":"太田健康課長","answer":"そうすると、母子健康手帳というのを区で交付をさせていただいています。その際に、妊婦健康診査票というのを前期分と後期分、それからその他の子育てガイドとか、一連の制度の説明の入った袋、これをそのときにお渡しをさせていただいている、こういうことです。","voiceIndex":207,"id":"exchange-091"},{"speaker":"須藤委員","kind":"質問","question":"それで、今度、この通知があって、今言った東京都地域保健事業連絡協議会のあり方検討会から１０月に結論が出て、２回から１４回の間で、それは各市町村に対応を任せますよというお話になってくるんだけれども、そのあたりは品川区としては、これから予算とかいろいろなってくるのでしょうからまだ決められてはいないと思うんだけれども、方向性としてはどういうふうな考え方をされているのでしょうか。","respondent":"太田健康課長","answer":"これと１月に出ています国の通知、これらを踏まえて子育て支援と、より安全な出産を支援するという観点から、妊娠期の健診等に要する経済的負担を軽減するため、具体的に平成２０年度の予算編成の中で現在検討している、こういう状況です。","voiceIndex":209,"id":"exchange-092"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、今、何点か検査項目を挙げていただきましたけれども、そのほか医師が特別に云々するような項目については自己負担になりますよと。そういうケースは非常に多いのでしょうか。通常はこの項目の健診で母体とも成育が健全性を保たれていますよということなのかどうか。","respondent":"太田健康課長、倉橋品川区保健所保健サービス課長","answer":"回数を２回から１４回の各自治体で判断する回数増に対応できるような健診項目を決めましょうということで、問診、体重、血圧、尿検査、これは２回から１４回の間でもいずれも実施をしていくです。正確なデータは今この場に持ち合わせておりませんけれども、全部の妊娠からいたしますとそう多くはない。何％かの割合で、起こり得ることですけれども、そう多くはございません。","voiceIndex":211,"id":"exchange-093"},{"speaker":"須藤委員","kind":"意見","question":"ここでは１回当たりに健診が５,０００円から１万円ほどかかりますというような表現になっているんだけれども、そうすると、いわゆる５,０００円から１万円かかりますというものが、今度、来年度からある程度そういった２回から１４回で項目をやります、それから７項目もその中でかかるうちで今回はこれ。","respondent":"太田健康課長","answer":"２回目から１４回、回数によりますけれども、その自治体の回数に合わせてが前提になりますけれども、その妊娠週に応じてこういう検査をしたほうがいいというものがありますので。","voiceIndex":214,"id":"exchange-094"},{"speaker":"須藤委員","kind":"質問","question":"今いろいろな出産までに健診をしないで救急車で運ばれて病院へ入って出産費も払わないでそのままいなくなってしまってとかというようなことがいろいろ出ているんですけれども、そういった結婚して妊娠をするということを、やはり夫婦間でいろいろきちんと話をして、そういった対応を今若い人たちはそれなりにしっかりやっていると私自身は聞いているので、私もちょっと若い人たち。","respondent":"太田健康課長","answer":"もちろん当然東京都の医師会の役員の方も入って検討をされたものですので、今回、一定の結論が出た妊婦健診の健診項目については、主立った健診項目が網羅されているということで考えておるところです。","voiceIndex":216,"id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それで、五者協議の中で、国の通知のほうからも最低でも５回は公費にするようにというような通知だったと思うんですけれども、そういう５回まではというような、そういうふうなものも五者協議の中の確認というのはなくて、あくまでも１４回までのうちでそれぞれの自治体がということで行くのでしょうか。","respondent":"太田健康課長","answer":"五者協議、これはあり方検討会、何度も言うように五者協そのものではございませんので、五者協の代表者プラス学識経験者等が入っているですので、ちょっとそこは認識をいただきたいと思います。","voiceIndex":218,"id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこれはどこでもやっているというふうに聞いたんです。そうすると、この初回の検査というのが全部自費というふうなことになって、これがかなりの高額になるということが大変だというのを現場から聞いたんですけれども、そこら辺のところはいかがでしょうか。","respondent":"太田健康課長、倉橋品川区保健所保健サービス課長","answer":"ただ、聞いていますところは、初回の検査の金額と、２回目以降１４回までの検査の金額については、当然検査項目が違うので差が出てくる。２回から１４回については同じ単価で検討しているという状況を聞いているところです。妊娠判明時の初回の検査というお尋ねですが、病院の方針にはいろいろありまして、自費診療ですので、すべての病院がどうだということはなかなか言えないところですが、私どもとしては、標準的な病院の対応というのは。","voiceIndex":220,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"実際に病院に調査をした結果、そういうことだということで確認されていますでしょうか。だから、そういうところで一番初めのときの検査をして、そこで分娩の予約もするという話も聞いているんですが、今のお話というのは、実際の病院の状況というものを今の段階で調査をされてそういう状況になっているということでよろしいのでしょうか。","respondent":"倉橋品川区保健所保健サービス課長、太田健康課長","answer":"実際に調査はいたしておりません。先ほどのちょっと追加でご答弁します。初回の検査で子宮がん検診とＨＩＶ抗体については、検討会の中では区市町村によりがん検診を実施しているところもあるので、それについては妊婦健診の公費負担の項目には入れないです。","voiceIndex":223,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"新聞でも本当にこういうふうな報道がされていますけれども、私も助産師の友達から聞いたところでは、あと３日後が予定日だとかということで、もう本当に今まで全く受診をしていないで飛び込みで来られるという方がいらっしゃるということなんですよね。それで、もう本当に現場は大変だという話を聞くんですけれども、品川ではそういう実態というのはつかんでいらっしゃるでしょうか。","respondent":"太田健康課長、志村生活福祉課長","answer":"ただ、朝日新聞等で出ていた駆け込み、飛び込み出産ですが、先ほど申し上げたように、現行でも前期で１回、後期で１回の公費負担による妊婦健康診査を実施していますので、妊娠届が出て母子健康手帳を交付する際には。お尋ねの件ですけれども、今日現在、私は聞いたことがございません。それと、平成１６年度、平成１７年度、平成１８年度の３年間ですけれども、出産扶助の適用はありませんでした。","voiceIndex":226,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"品川ではそういう状況がないということで、現実問題としては、でも、多分、大変な実態というのはあるんじゃないかなというふうな思いがしているんですけれども、大体初回のところで保険がきかないということで、健診のお金がとられて高いのにすごくびっくりして、その後の健診に来られなくなってしまうというふうなこともあるということで聞いていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":229,"id":"exchange-100"},{"speaker":"堺委員","kind":"確認","question":"今のご質疑の中である程度理解ができたんですが、重ねて確認しておくと、回数については、各自治体の判断と、これは五者協の中でそういう結論が出たということは、品川区は品川区の判断で回数についてはできるんですよという理解をしていいんですか。それは例えばどういう検査項目なんですか。","respondent":"太田健康課長、倉橋品川区保健所保健サービス課長","answer":"それから２点目のその他の選択項目に載っている検査項目以外の項目、これは現実に平成１９年度までの２回の健診の公費負担の中でも、時として問題になっていたといいますと変なんですけれども。共通以外の検査項目について補足しますが、現在、東京都が報告書で考えている内容から考えまして、以前対象とならなかった検査項目についても、先ほど健康課長の説明しました選択項目の中に取り入れておりますので。","voiceIndex":230,"id":"exchange-101"},{"speaker":"堺委員","kind":"質問・要望","question":"各自治体の判断によって回数は決めていかれると、こういうことなので、品川は品川独自にそういう判断ができるというようなお話がございましたから、平成２０年度の予算に向けて今現在、その辺も含めて検討されているというふうに受け取れましたので、ぜひその辺につきましては、私どももいろいろな形で機会あるごとにこの件については要望してまいりましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-102"},{"speaker":"堺委員","kind":"意見","question":"本日、結論を出すということで取り扱いをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":236,"id":"exchange-103"},{"speaker":"堺委員","kind":"質問・要望","question":"先ほども申し上げましたように、私どもの思いはこの妊産婦の無料健診の回数の拡大ということについてはかねがね強く要望してきたところですが、この請願については、全額公費負担で無料ですので、これはちょっと願意に沿いがたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"共産党としても５年前からこの問題は繰り返し繰り返し一般質問、予算特別委員会、決算特別委員会で予算修正提案も行いながら提案をさせてきていただきましたので、ぜひ何としても実現をしていただきたいということで、この請願そのものも採択をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":244,"id":"exchange-105"},{"speaker":"本間委員","kind":"意見","question":"すべての妊婦健診というふうな部分と、それから全額無料化という部分に抵抗があります。その辺の判断を見ながら回数増は見るけれども、１４回まで行くかどうかというような部分はこれはまた別だと思います。それから、無料化につきましては、公費負担のあり方と、それから一部自己負担もあり得るというふうなことですので、全額無料化ということには賛成できません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":245,"id":"exchange-106"},{"speaker":"高橋委員","kind":"意見","question":"あり方検討会のほうで出た結論等を福祉の子育て政策の品川ということで、さらに充実させる政策を平成２０年度の予算の中で回数検討ということでしていただけるということですので、そちらに期待いたしまして、今回のこの請願項目に関しては、会派としては願意に沿いがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":246,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この点で区長の考えをお聞きしますという質問に対して、区長が、今後は第四次長期基本計画の中で整備してまいりますが、ご指摘の介護のセーフティネットの視点から、特別養護老人ホームの整備につきましても、居室の形態という問題もありますが、将来の課題として検討してまいりますという、こういう答弁がありましたけれども、具体的にこの中身と、それからこういう状況に至った経過。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今までは、そういう特別養護老人ホームの整備について検討するという答弁というのは、ずっとこの間なかったわけですよね。今までの答弁と明らかに変わったと思いますので、ここら辺の区の考えを、これは明日でもいいと思うんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":253,"id":"exchange-109"},{"speaker":"須藤委員","kind":"質問・要望","question":"事業量、それから物についてという中での話なので、それをつくりますから、急に方向転換したということは、私自身も決して意図していないので。その中でしているわけですから、そういう意味での質問で、それ以上云々というのも、私のほうは考えていないと思っているので、理事者のほうにそれ以上の回答を今求めても、これは酷なところだと思う。","respondent":"山田副区長","answer":"本会議での問題を取り上げて、この委員会の中で質問として明日やりたいということであれば、これは否定できることではございませんので、ただ、お答えが満足かどうかについては明日ということで、させていただきたいと思います。","voiceIndex":254,"id":"exchange-110"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":74020,"voices":260}},{"id":"h19-20071126-8","meetingId":"h19-cm11","date":"2007年11月26日","dateIso":"2007-11-26","committee":"建設委員会","time":"午前１０時０２分～午後４時３１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８３号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第８３号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"意見","question":"この旧東海道のところが景観まちづくりのモデル地域として指定されているのとあわせて、地域の方たちの発意でこの計画をつくられてきた経緯があるかと思うんですけれども、今、説明にありました良好なまちづくりの誘導という意味では、ここのエリアは２０ｍ、両方で２haということなんですが、今後ここの部分は今できましたけれども。","respondent":"阿部都市計画課長、齋藤住宅課長","answer":"１点目の景観まちづくり、これからモデル地区検討はどうしていくのかということですけれども、今、委員ご指摘のとおり、この地区については景観ガイドプランに基づくモデル地区として景観まちづくりを進めております。その謄本を受けて初めて区長まで意思決定をもって公布をするという決定がなされますので、当日以降、一般的には二、三日のうちに公布をするという手はずになっています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"今、地域のほうからの発意は支援をしていくという話でしたけれども、景観まちづくりのモデルのガイドプランに沿って、さらに目黒区なんかで言いますと、近々の新聞で都市計画審議会の中に専門部会をつくって、そういう景観の地域を行政主導とは言いませんけれども、そういう誘導していく取り組みを積極的に進めていこうというのがあるんですけれども。","respondent":"阿部都市計画課長","answer":"一方地区計画につきましては、やはり地区の方々、地域の方々が合意形成をしていくというのがやはり基本になってありますので、そういう意味では地域の方々の合意ができるような南品川三丁目のような動きがあれば、区としては支援をしていくというふうに考えています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっとまだここもよくわからない部分があるので教えていただきたい。今回１３ｍにするということですけれども、その１３ｍとした理由というんですかね。今のお話の中で地域の方々の合意の中でというお話がありましたけれども、その辺の経過を教えてください。それとあわせて、５０cmのセットバックですけれども、その５０cmという理由ですか。それを教えていただけますか。","respondent":"片田建築課長、阿部都市計画課長","answer":"用途地域の関係での高さの考え方ですけれども、これまで最高の高さ、限度として用途地域の中で決められてきているところについては、第一種低層住居専用地域ということで、かなり住環境がいい場所については。広い敷地もありますけれども、そういう中で、セットバックがどのぐらいが有効なんだろうかという検討をしてまいりまして、これは最低限度ですけれども、５０cm以上下がっていただければ両方が下がりますので。","voiceIndex":11,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"もうちょっと詳しくご説明いただきたい。それと日時は覚えていないんですけど、以前、建設委員会でこの神社の大イチョウの話が請願で出ましたけれども、そういうところとの経過をもう少し教えていただけますか。","respondent":"阿部都市計画課長","answer":"１３ｍの件ですけれども、当然のことながら、地域の方々も今あるまちなみを維持していきたいというのが前提です。ですから、そういうことを考えますと、現状で自分たちがお住まいですから、それも建てられつつ景観も守っていきたいということが希望です。","voiceIndex":14,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"今回、具体的にこの地区計画という中で具体的に都市計画の手段を使うわけですけれども、そういう自分たちのまちでこういうまちのルールをつくることができますよ。そういう説明的なチラシというのか、パンフレットというのか、こういう手段がありますよという広報物というのは今あるんでしょうか。","respondent":"阿部都市計画課長","answer":"私どもでそういうものをつくっているということはございませんけれども、ただ、品川区では自主的なまちづくりの支援ということをやっておりますので、そういう面での広報はしているです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"そういったときにいろいろな方法の１つとしてこういう地区計画というものがあるんだよと、そういうＰＲというか広報のそういうチラシは必要なのかなと思うんですよね。やはりそこに住んでいるまちの人たちの残したい景観、住宅の保全というのがあるでしょうから、ぜひその辺のことは検討されたらと思うんですけれども、いかがでしょうか。","respondent":"阿部都市計画課長","answer":"地区計画というのはそもそも１つの手法ですので、まずはその前に自分たちのまちづくりをどうしたいか。そういうものを考えたいというときには、先ほど申し上げましたけれども、そういう支援制度がありますので、まずはそこからというふうに思っております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば建築確認申請を出してあったものはもうかからないのか。建築確認申請がおりたものだけなのかとか、そこら辺の法的なことを教えていただきたい。その法的な部分でそれは未整備というか決まらないところもあると思うんだけれども、こういう地区計画をかけるときの官民境界というのはどうお考えなのかというところを教えていただきたい。","respondent":"片田建築課長、齋藤住宅課長、阿部都市計画課長","answer":"法的なお話で、どの段階で規制がかかってくるのかという具体的なお話ですけれども、一般的な考え方としては。補足して説明しますが、いつ工事に着手したかではなくて、その適用したときに既に容積を超えていれば既存不適格になります。基本的には今、既存不適格ということで住宅課長の説明がありましたが、建築とのかかわりにおける法の適用についてのご質問ですけれども。３点目の電線の地中化のことですけれども、委員ご承知のように、北品川のほうはもう始まっていますけれども、当然ここにつきましても。","voiceIndex":20,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"法的なことがわからないので教えていただきたいんですが、確認がおりた。それで工事着手というのは今のお話だと根切りなのか。例えば解体工事に着手した。こういうことは法的にしようがないと言うのならしようがないんだけど、それを理解して、例えばこういう今話がありますよということを、確認のときだって事前審査なり何なりあるわけだから、そのときにお話をするのか。","respondent":"片田建築課長、岩田まちづくり事業部長","answer":"計画が出てくると、当然随時都市計画課と私どものほうは連携をとってありますから、その情報のやりとりをしながら指導していくというようなことになります。こういった形で地主自体に１年前から徹底した周知を図っておりますので、おおむね１年あれば、今回告示をされて、そのときにトラブルというのはよほど悪質な駆け込みをねらってこない限り、あり得ないと考えておりますので。","voiceIndex":25,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"さっき聞けばよかったんだけど、官民境界の部分はそれはそれとするならば、用途地域と地区計画は用途地域は今、多分変更にならないんだね。そうすると、前の用途地域のときも官民境界が決まっているかというとそうではなくて、１つひとつ建て替えとかいろいろあるときに決めていく。地区計画もそれと同じだという理解でいいわけですよね。","respondent":"片田建築課長","answer":"今回の場合はたまたま用途地域の界が地区計画の区域と合致したですから、今後やはり１つひとつの官民境界の指定ではなくて、地域の合意の状況とかを含めた中での用途地域の変更も一般論としてはありますけれども。","voiceIndex":28,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"よくわからなかったんだけど、用途地域は用途地域でいいんです。用途地域は今の段階ではあまり変わらない。だけど用途地域と同じであるならば、建て替えだ何だとそういうときに、改めて官民境界を決めているわけじゃないですか。逆に地区計画が決まった中で、誘導してどういうふうにしていくかというのがよくわからなかったんだけど、用途地域と同じ感覚でいればいいんですかというところだけ。","respondent":"片田建築課長","answer":"地区計画は用途地域と同じでよろしいということで考えてあります。","voiceIndex":30,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"ちょっと１つ確認させてもらいたいんですが、今、建築に着手という部分での問題に絡む話になってくるんだけれども、この建設委員会でも問題になったりしている話の中で、建設会社と住民と協定を結ぶという話になったときに、いつもトラブルになるのは解体の時点でめちゃくちゃな解体をやった。ほんとに住民の、近隣の皆さんに気を遣って解体。それをまずお聞かせいただきたいと思うんですけど。","respondent":"齋藤住宅課長、片田建築課長","answer":"解体は２年ほど前までは周知といったことをしておりませんでしたが、要綱を設けて１０日前に看板を設置して、周辺の方にどういった手法でどういったものを使って解体するか説明するようにと義務づけております。区のほうとしてもそういう事前の解体の機会をとらえて、８０m2以上のものを対象に近隣への説明を行うよう指導していますので、連携の中で対応していきたいと考えています。","voiceIndex":32,"id":"exchange-011"},{"speaker":"三上委員","kind":"質問・要望","question":"そうしないと、１３ｍには統一したけれども、結局はできてきたら隣と全然別個の、なんだ、このまちづくりはというふうに言われるようなまちなみということになっていっても、せっかくの地区計画というものが意味をなしているのか、なしていないのかというところが問われていく話になるので、そこらあたりについてはこの地元の皆さんたちはどういうふうに意見調整をされているんでしょうか。","respondent":"阿部都市計画課長","answer":"まちなみの件ですけれども、今回の地区計画の中でも、例えば建物の色とかデザインというものにつきましても、旧東海道にふさわしいものを図ってつくっていくという表現ですけれども、ただ、先ほど申しましたとおり、区は景観計画をまず定める予定です。","voiceIndex":35,"id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"もう一つちょっと聞かせてもらいたいんですが、旧東海道の道路に面して東西になるまちなみを考えている。ジュネーヴ平和通りそのものを青物横丁の駅からそこまでの間だとかという部分について、そういう考え方というのは起きてきていないんでしょうかね。結局そういう部分は取り残されてということでいくのか。そのあたりはどうなんでしょうか、地域の声として。","respondent":"阿部都市計画課長","answer":"地区計画の件ですけれども、今回はたまたま２０ｍ、用途界のところまででしたけれども、この計画を定めるときに、この京浜急行から下の元なぎさ通りまでの方も含めまして説明会をして、原則的には地区計画では１つの街区で囲まれたところですけれども。","voiceIndex":37,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問・要望","question":"言葉から教えていただきたいんですけど、先ほどご説明の中にありました根切りってどういったものなんでしょうか。すみません、わからないものでまずそれを教えてください。","respondent":"片田建築課長","answer":"専門的な言葉を使って大変申しわけございませんでした。根切りという言葉は、工事をやるときに基礎を打つときも土を掘って基礎を設置しなければなりませんから、そのときに土を掘る行為です。それを根切り工事ということでご理解いただければと思います。","voiceIndex":39,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"要するに解体工事が終わってから基礎をするまでの土地を整える作業ということですか。違いますか。","respondent":"片田建築課長","answer":"根切り工事というのは工事を着手する目的で、新しい建物をつくる目的で、まず基礎の工事をやるという場合に、杭を打つ場合もありますけれども、土地の切り下げですよね。土を掘る行為という、目的に沿った形で掘る行為だということでご理解いただきたいと思います。","voiceIndex":41,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"何となく段階としてはイメージできたかなと思います。それで、品川寺の隣のマンションに関してなんですけれども、今、どの段階にあるかというのがちょっとよくわからなかったのですが、たしかあそこは今、覆ったような状態であったかなと思うんですけれども、あれは結局この条例が施行された場合にどうなるんですか。","respondent":"片田建築課長","answer":"既に工事は着手されていまして、安全の観点から周辺を仮囲いしているため、工事の状況はなかなかわかりづらいというのはあろうかなと思いますけれども、基本的には今、工事を行っているものという意味では着手しているわけですから。","voiceIndex":43,"id":"exchange-016"},{"speaker":"阿部委員","kind":"質問・要望","question":"今から計画の変更などを求めるということも順番から言えば成立しないということで、今後の建て替えのときにということになるわけですね。あるいはその地区計画というのは、それだけでは歴史的なまちなみを感じるには十分ではないということで、条例なり地区計画なり規制ということではなくて、より積極的に歴史的なまちなみを整えていくための次のステップというものは念頭に置かれておりますでしょうか。","respondent":"岩田まちづくり事業部長","answer":"これをやらないと、色とかデザインとか、そういったものの規制というのはできないわけです。","voiceIndex":45,"id":"exchange-017"}]},{"id":"topic-02","title":"第８７号議案、専決処分の承認を求めること","agenda":"第８７号議案、専決処分の承認を求めること","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけど、第１７９条には次の会議と必ずこれは地方自治法でもうたってあるわけですよね。そうなってくると、この８月３１日というのが、下記のとおり専決処分というか、この言葉の意味合いを教えていただきたいのと、今の９月２１日とは書いてないわけだから、それが提起の部分とこの８月３１日の意味合いの違いを教えてもらいたいのが１つ。","respondent":"齋藤住宅課長","answer":"８月３１日の専決処分というのは、訴訟を提起するそういう意思決定をしたです。訴訟の目的の価額がその時点で確定できておりませんでした。１００万円程度で議会のご承認をいただく議案ではなく、報告で足りるというふうに思っておりました。","voiceIndex":53,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると次の会議とうたってあるけど間に合わなかったというお話だと思うけれども、今おっしゃった日にちの関係もわかりましたので、総務課を含めて、こういうのはほんとにひどい話なので、それはぜひそういうことを厳格にやっていただきたいと思うので、そこら辺のところ、こちら側の体制もぜひしっかりやっていただきたいというのを要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明の中で６カ月以上の滞納者が９名ほどいらっしゃって、そのうちお一方がいわゆる拒否をされたというご説明でした。残りの８人の方のご説明もありましたけれども、今の生活状況など何か原因になっているものがあるのか。そこをもしつかんでいらっしゃったら教えていただきたいのが１つ。家賃の滞納額でいくと１００万円程度とありましたけれども、正確にはお幾らほどになるのか教えていただけますか。","respondent":"齋藤住宅課長","answer":"細かいところまで１つひとつというのは難しいんですが、サラ金からお借りになったり、毎月の収入が安定していない方もいらっしゃいます。ただ、お話をお聞きしますと、高利のところから払って、区は甘いから後回しになる。それが私の受けた感想であります。","voiceIndex":56,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"今回のケースだけではない。中には、今お話がありましたけれども、生活状況の変化だったり、失業、病気、いろいろな中で滞納も生まれますので、具体的に相手の状況を把握することにどういうふうに努めているのか、もう一度伺いたい。それと区民住宅の明け渡しについて、区はどういう姿勢で今後それを進めていくのか。その基本的な姿勢のところをもう一度ご説明いただけますか。","respondent":"齋藤住宅課長","answer":"その方はお一人は入院された。入院期間中は厳しい対応はいたしませんでした。退院されて私ども３回のお話をして、観念されてこれ以上払えないということで、退去しました。相手方の事情によって強制的に出ていかせるということはしていません。","voiceIndex":58,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういう場合はこうするというふうに形づくることはやはりできないと思いますので、相手の状況に応じてよくご対応していただきたいと思います。ちょっとお伺いしたいのは、家賃滞納分が１４１万円で、訴訟の目的の価額が７３７万円余と家賃の数倍になるわけですよね。この７３７万円の訴訟の目的の価額のこの考え方、訴訟でとるもの、そこをちょっとご説明いただけますか。","respondent":"齋藤住宅課長","answer":"したがって、滞納額は１００万円弱であったのにかかわらず、訴訟の目的が７００万円になっている。訴訟に提起する印紙代が４万円になったです。","voiceIndex":60,"id":"exchange-022"},{"speaker":"中塚委員","kind":"意見","question":"なかなか専門的でわかりにくいのですが、マンションの価値というのは当然でき上がった時点から減価償却される部分がありますよね。この場合ですと、区は固定資産税を払う関係じゃないから近隣との関係で価格を出すというお話なんですけれども、そのマンションの価値というのは、できた当時から減価償却される部分をどういうふうに兼ね合いとして見ているのか。","respondent":"齋藤住宅課長","answer":"減価償却を勘案するという発想はありません。今、この占有の価値は幾らかを算定します。したがいまして、固定資産税で評価額を割り返して出すというふうになっております。","voiceIndex":62,"id":"exchange-023"}]},{"id":"topic-03","title":"第８８号議案、指定管理者の指定","agenda":"第８８号議案、指定管理者の指定","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"初めに資料についてちょっと伺いたいんですけれども、今回、提案型公募のプロポーザル方式を行ったということですけれども、初め６社で、一次審査で３社に絞られたという話ですけど、提出する書類は何種類あるのか。それで、審査の経過の中で選考基準というのがありますけれども、この選考基準というのはどういう基準のものなのか。","respondent":"齋藤住宅課長","answer":"緊急時の対応はどうか。次に入居者管理計画として、滞納者に対する納付指導対応をどうするか。入居者サービスの向上のための管理計画の評価、業務に対する研修はどのように行っているか。４番目、建築、維持管理計画。５番目、個人情報保護。６番目、環境に対する配慮。","voiceIndex":69,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"その辺の選考の基準がよくわからないんですよね。制度として公正さをきちんと担保するためにも、そういう基準というのは明らかにすべきではないのかなと思うんですけれども、総合評価１位というのは、どういう仕組みの中で点数化されたものなのか、その辺を教えていただけますか。","respondent":"齋藤住宅課長","answer":"この資料は当該候補者の事業活動に営業の秘密にあたる部分もありますので、議会であれ、お出しすることはできません。したがいまして、区が審査した内容についてご信頼いただき、審査の内容についてご説明いたしますので、これに基づいてご判断をお願いしたです。","voiceIndex":71,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"事業計画書には企業の秘密があるというお話ですけれども、私が伺っているのは総合評価１位というそういう書き方をされているので、それぞれの評価に何か点数化があるとか、それとも何かそれぞれの公的住宅に関する基本的な考え方、これが一番ウエートが多くて、そういうふうに濃淡があるのか。","respondent":"齋藤住宅課長","answer":"点数化をして優劣を決めました。その点数をどういう基準でしていたか、その点数の基準も含めてこれは公開できないです。","voiceIndex":73,"id":"exchange-026"},{"speaker":"中塚委員","kind":"提案","question":"私はやはり制度としての問題点だなと感じています。経営会議における検証のところでは、総括シートの内容どおりであり、特段の指摘事項はなしというふうに評価されていて、ただ今回は年間の実績は多分評価できるだろうけれども、新しい提案など弱点もあった。その辺きちんと裏づけできる資料は議決に当たって必要な資料ではないのかなと思うんですけど、いかがでしょうか。","respondent":"齋藤住宅課長","answer":"総括した点数表はあります。それは別段お出しすることは構わないんですけれども、庁内の調整の中でお出ししませんでした。しかし、きちんと基本的な考え方、業務執行体制、こういったものを点数化してこれは誰が審査してもそれほど変わるものではありません。","voiceIndex":75,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の議案は入居者の方にとっては区の説明だと満足を得られる変更だという説明ですから、議案に対しては反対するものではないと私は思っていますけれども、今の説明でも、例えば出すことは構わないけれども庁内の合意の中では出せない。そうした視点からも審査にあたっての、特に議決にあたっての審査はもっと透明度を高めるべきではないのかなと思いますけれども、いかがでしょうか。","respondent":"岩田まちづくり事業部長","answer":"緊急時の対応はどうなっているかということです。それから３つ目に、入居者の管理計画、管理計画というと語弊はあるんですけれども、入居者の方々に対する滞納を中心とした管理方法をどう考えているのか。どうするのかということですね。４番目に、建物の維持管理計画。","voiceIndex":77,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"今の説明の中でも個人情報保護が基準の中にあるというお話でしたけれども、当然株式会社であろうがなかろうが、個人の情報を不正に利用するということは決してあってはならないことで、そこに関して今回の東急コミュニティーがどういうふうにお話ししているのか。今後基本協定を結ぶと思うんですけれども、どういう中身の協定を結ぶのか。そこを教えていただけますか。","respondent":"齋藤住宅課長","answer":"社員の研修も充実しておりました。点数を公にしないという理由の１つは、こういったところで点数をつけるとその他の会社はしていないと。これで落ちたところは劣っているなど、応募された会社に対して誤った印象を与えるということで、信用を害することがあるのではないか。","voiceIndex":79,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の説明で今回変更で、住まわれている方にとってはより満足度が得られる変更だと、そういう説明なので、反対するまでもないんですけれども、その説明の根拠となる資料をしっかり議決に際する資料の中にお示しいただいて、業者からはこういうふうな説明がある。そういう説明で公平性、透明性を担保することが必要だなと、それは最後に意見だけ述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"ここにもありますけれども、前にやっていたところで４年半の実績は高く評価できる。もう一つは、経常経費のところで出ていますけれども、こういったところで何か判断をするにあたるものがこの辺では見られたのかどうかということが１つ。そういうところは何かお考えがありますでしょうか。","respondent":"齋藤住宅課長、岩田まちづくり事業部長","answer":"経常経費で判断することはない。５年ごとで変えるかということではございません。５年ごとに審査されたうち最もいいものであるです。今回結果として変更になってしまったということです。他の部署につきましては法人が主ですから、あまりそういうことはないのかもしれませんけれども、統一的に今後できるだけ議会の方に内容がよくわかっていただけるように、これは企画当局ともご提案の趣旨について調整してまいりますので。","voiceIndex":82,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ検討を進めていただきたいというふうに思うんですけれども、そういう細かいところの企業ノウハウみたいなところを書いたものということでなくても、一覧として点数化をしたのであれば、その点数化によってそういう判断がまたトータルをして総合評価がそうだったのかということも１つの入り口ではあると思いますので、検討していただく中で判断基準となるようなものというところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-032"},{"speaker":"阿部委員","kind":"質問・要望","question":"計上経費について教えていただきたいんですけれども、各社維持管理経費というのはそんなに大差がないんですが、入居者管理経費というのは前のＡ社と比べると１,０００万円の違いがありますね。先ほどのご答弁ではそういう経費の額を勘案することはないというふうに聞こえたんですけれども、この１,０００万円の数字が違うということをどう考えていらっしゃるのか。","respondent":"齋藤住宅課長","answer":"この１,０００万円の差は何だというと、ちょっと中身に入ってしまいますけれども、人を正社員でやるか、委託でやるか、そういったものの各企業の積算の詳細についてはちょっと控えします。","voiceIndex":86,"id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、幾らかかるかというのが、これが民間のマンションのように、結局それは入居者が頭割りで払うんだよということでしたら、居住者の方が納得すればそれでいいと思うんですけれども、これが試算ではあっても区のお金で払われるということでしたら、あまり値段は幾らでもいいという話にはならないのではないかと思うんですけれども、その辺いかがでしょうか。","respondent":"齋藤住宅課長","answer":"この金額は応募された企業にこの施設を１年間指定管理者として委託する委託料として幾らかかるというふうにあなたは考えますかという提案をしていただいた金額です。この金額で決まるわけではありません。","voiceIndex":88,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"冒頭のご説明の中で、例えば東急コミュニティーですが、コミュニティ形成支援というような形で市町村交流をするとか、民間と提携して、趣味の講座みたいなものをされていると。コミュニティ形成自体は非常にいいことだと思うんですけれども、これはある程度受益者負担みたいな形になっていくんでしょうか。あまりここのところに公金が入ってしまうのはちょっと違和感があります。","respondent":"齋藤住宅課長","answer":"提案のとおりに市町村交流してくださいというわけではございません。こういった形で提案ができるということは、組織があって人がいて何か新しいものをこの住宅でやってくれるのではないか。こういう可能性があるということです。そこを私たちが評価をしたです。","voiceIndex":90,"id":"exchange-035"},{"speaker":"阿部委員","kind":"提案","question":"おっしゃることはわかりますし、８割方納得はしているんですけれども、ただ、そういう提案をしたから選んでいらっしゃるということは、提案内容は実現する価値があると思っていらっしゃるから選んでいるのではないかなと思うんです。","respondent":"齋藤住宅課長","answer":"大井町にわざわざ支社までつくり、あと関連会社が目黒の駅のすぐ近くにありまして、今までの会社だと保守業務についても再委託をしていますので、１日、２日かかるようなこともありました。特にさくら会のほうから大変要望がございました。今度は直でやってくれる。","voiceIndex":92,"id":"exchange-036"},{"speaker":"阿部委員","kind":"確認","question":"確認なんですけれども、そうすると主に業務の執行体制のような部分でまずは評価をされて、東急コミュニティーを選んだけれども、その後の例えば、どれだけのメニューを使って実際に契約まで持っていくかというのはこれからまだ詳細は詰めていくという理解でよろしいわけですね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"提案","question":"だから、区民住宅にお住まいの方はいいわけだけれども、その中の提案の中で、先ほど言った天体観測とか、それはもちろんそういうのもいいんだけれども、あくまでもここは収納を含めた管理をしていく指定管理者であるならば、その前段階の提案をしてもらう８項目については、１回やはり議論を議会ともしていただきたいなと思うんだけれども、そこら辺の考え方を教えていただきたい。","respondent":"齋藤住宅課長","answer":"先ほど区は先進的なことをやっているみたいなことを言いましたが、悩みながら考えているのが事実でございまして、ご理解のほうお願いいたします。","voiceIndex":95,"id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"提案","question":"指定管理者も今４０幾つあるのかな。そうすると、今言ったプロポーザルの提案項目なんていうのは、先ほど阿部委員も言ったようにここまで管理の中でというようなものを我々も思うときがあるから、その１つひとついろいろな委員会にかかるんだろうけれども、これは議会全体の中のところでやったほうがいいと思うんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお伺いしたいのがこの審査資料ってありますよね。そうすると今度東急コミュニティーを使うということになれば、今までやっていた指定管理者に対してこういう理由で今回変更になりましたと一応事情は話をするんだと思うんですが、そういう説明というのはほかの会社にもあるんでしょうか。","respondent":"齋藤住宅課長","answer":"両社とも結果については是非を問いませんけど、こういった点は至らなかったという点、来られまして、プロポーザルの仕方から提案を含めて東急コミュニティーの事業秘密にかかわらない範囲でご説明して、Ａ社もＢ社もこれで落ちたのはしようがないですねえとおっしゃり。","voiceIndex":98,"id":"exchange-040"},{"speaker":"須貝委員","kind":"意見","question":"もう１点、いろいろな方からありましたが、指定管理者制度というのはでき上がったばかりなので、これからどんどん発展していくのかなと。そのサービスの内容とかそういうところも、もっと区のほうもどんどんいいものは取り入れて項目にどんどん追加していっていただいて、よりいい指定管理者制度、より透明性が見えるような制度につくり上げていってほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"東急コミュニティーがまたどこかの業務を指定管理者として受けた後、何か再委託のことを考えているのか、ちょっと教えていただきたい。いわゆる委託の委託というのは原則やめようということを思っていまして、それはきっかけになったのは埼玉のプール事故も１つそうでしたけれども、責任の所在が不明確になる。そういう話で再委託の話はどういうことなのかなと思ったんですけど、ご説明いただけますか。","respondent":"齋藤住宅課長","answer":"東急コミュニティーはマンション管理会社では日本で３番目、丸紅コミュニティは１９位ぐらいに位置しております。東急コミュニティーは関連会社として、これは三井不動産もそうなんですけれども、メンテナンスの会社を持っておりますが、すべてに対応できるものでもありません。","voiceIndex":101,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"いわゆる委託の委託は責任の所在が不明確になるから原則やめようじゃないかという話があったと思うんだけれども、つまり今回の指定管理者についてどういうふうに判断されたのか。その説明をお願いします。","respondent":"岩田まちづくり事業部長","answer":"誤解のないようにしていただきたいんですが、５年間やっていただいた丸紅コミュニティ、これは私どもの評価としても非常によくやっていただいたという評価をしております。","voiceIndex":103,"id":"exchange-043"},{"speaker":"三上委員","kind":"質問","question":"こういう形で選定されてきてあれですけれど、この協定を結ぶにあたって、重大な瑕疵があった場合の解約事項については、どの程度の問題が生じた場合を考えていらっしゃるんでしょうか。","respondent":"齋藤住宅課長","answer":"私どもとしても一般論として、入居者の生命や身体といったものに当たるような事象を起こした場合については、必ず解約せざるを得ないというふうに考えております。","voiceIndex":105,"id":"exchange-044"}]},{"id":"topic-04","title":"第８０号議案、平成１９年度品川区一般会計補正予算、建設委員会所管分","agenda":"第８０号議案、平成１９年度品川区一般会計補正予算、建設委員会所管分","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、委員長がおっしゃったように、あくまでも補正予算の議案なんですから、これだけはお願いしておきますが、ほかの部分を言っていただくのは構わないけれど言い過ぎ。この中身のことでお伺いします。それからこれだけは一般質問でもやったので確認だけしたいんだけれど、耐震シェルターの設置の助成はいいんだけれど、頭出しは結構です、どんどんやっていただきたい。そこへ補助金をつけてくるんでしょう。","respondent":"片田建築課長","answer":"もう１つリーフレットについてですが、今考えているのは促進計画の概要版と個別の施策、例えば耐震シェルターであればシェルターを１枚ぐらいでわかりやすく助成額、対象者等々を記載したものを、それぞれメニューごとにＡ４版の表裏をうまく活用して考えてございまして。","voiceIndex":112,"id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"質問","question":"シェルターのことだけお願いしておきますが、静岡の、会社名まで言わないけれど、確かにすごくいいものをつくっていますよ。某社、そこも多分選ばれるんだろうけど、その２社のひとり勝ちになるのか。１日何軒ぐらい回ろうとしていて、どれぐらいで全部回れるとお考えなのかというのも。今のお話だとすごく長い話になりそうな気がしてならないんだけれど、その辺の考え方をもう少し教えてください。","respondent":"片田建築課長","answer":"いろいろ別の方が行きますと、地域のほうでも不信感等を持たれるということも一方ですけれど、今考えているのは基本的には１軒１軒回って、資料を含めて手渡しをして説明していきたい。","voiceIndex":114,"id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"要望だけにします。今お話があった１,６００世帯、またほかに７４町丁ぐらいあると。とりあえず地域が決まっているから地域の中で手厚くやってほしいと思いますので、私は全地域でやってほしいと思うけれど一応地域を決めてやるわけですから、そこでぜひ実のあるものにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"私も個別訪問のことを伺おうかなと思って。質問したいことは、うがった見方をすると、今悪質な住宅リフォームの詐欺も残念ながら発生しているので、確かにピンポンと来られて「おっ」とびっくりされる方はいらっしゃると思うんですよね。最近では品川区の職員を装って来るというお話も伺っていますので、下ごしらえをどう考えているのか、もう少し具体的にお考えを教えていただきたいのが１点です。","respondent":"片田建築課長","answer":"今回の個別訪問の普及についても、いろいろ支援策として国が考えている、あるいは区が考えている助成等々の作成についても、基本的には委託を条件としているところもございまして、これは本筋とはちょっと違いますけれど、基本的にはできるだけ事前の町会長への説明。","voiceIndex":117,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回まずは４ランク以上のところから重点的にという、それはそれで理解できますけれど、区内に住んでいる方の住宅は密集であろうがなかろうが、耐震補強が必要な住宅というのはそこに住まわれている方の命と同じですから、最終的には個別訪問は全部やるというお話ではなかったのか、そこを教えていただきたい。それと建替えとかも地域が限定されているものがありますよね。","respondent":"片田建築課長","answer":"少なくともその地域については木造の集積が高いということで、緊急な課題であるということで説明していますので、そういうところをまず優先的に進めていきたいと考えています。","voiceIndex":119,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"せっかく寝室が耐震化されても、阪神・淡路大震災や近年の地震でも、テレビが飛び上がってきたり、襲いかかるというふうに感じたり、そういうことがあるわけですから、家具転倒防止もしっかり助成制度をつけて進めてあげることも、少なくとも高齢者年金暮らしの方は無料でしっかり支えていくことも踏み込むべきじゃないかと思うんですけれど、その点は今どんなふうにお考えですか。","respondent":"片田建築課長","answer":"ということも含めて、これまではシルバーセンターの制度の中でそういう支援を行ってきたところがありますけれど、区の防災課も含めて検討していく必要がありますので、関係機関との連携の中でそういうＰＲも含めた形を考えていきたいと思います。","voiceIndex":121,"id":"exchange-050"},{"speaker":"阿部委員","kind":"質問","question":"今回、この補正予算が通った場合に、助成制度などは具体的にいつからスタートするのか。それだけ教えてください。","respondent":"片田建築課長","answer":"ただ制度の要綱を年内に調整したいということがありますので、何日からということはまだ難しゅうありますけれども、１月のできるだけ早い時期にやりたいということで、１月１日を目途に頑張っていきたいと考えています。","voiceIndex":123,"id":"exchange-051"},{"speaker":"阿部委員","kind":"質問・要望","question":"方法はまたいろいろあると思いますが、これは要望です。ぜひ職員の方にもできるだけ多く足を運んでいただきたいと思います。６０歳を過ぎたら細かい字は読まないとか、説明書なんか、はなから読まないという声もご高齢の方からはありますし、そういった意味からもどういう人がこれを読んで、その人にどういう気持ちになってほしいのかということを、重々ご検討をしてつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-052"},{"speaker":"須貝委員","kind":"提案","question":"それならばこれは提案なんですが、わかりやすい高齢者に見やすいリーフレットをつくっていただいて、そういうものを高齢者に一番接点を持っているのは町会だと思うんですね、町会なり高齢者グループが多々あるので、二重三重にはなると思いますがそういう方たちに手渡しを何とかしていただいて、場合によっては町会の口コミでこういう内容ですよと簡単な説明、もし何かわからないことがあったら区のほうに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":126,"id":"exchange-053"},{"speaker":"三上委員","kind":"質問・要望","question":"そういうことを考えていくと、パンフレットなりリーフレットのつくり方そのものについても、区の担当者の名刺ならびに、区からきちっとした委託を受けた人の名刺の形はこういうものですよとか、今は皆さん名札をいろいろつけていらっしゃるけれど、こういう形の人たちが委託されている人ですよとか、身分証明書をきちっと持っていますよとか。","respondent":"片田建築課長","answer":"耐震の仕方についての現場等、わかってもらえれば一番望ましいわけですので、今のタイミングで間に合うかどうかわかりませんけれど、一応検討しているものとしては、実際に区の診断を受けて改修を行っている現場も中にはありますので。","voiceIndex":127,"id":"exchange-054"},{"speaker":"三上委員","kind":"質問・要望","question":"今、８町丁ということで説明がありましたけれど、とりあえずその範囲ということになれば、狭いですからそれはできると思いますけれど、次の７４町丁に広げていくという話になれば、ある意味で品川区全域にまたがるような話になってくるということならば、それはそれで工夫をもっとしっかりとしていっていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-055"}]},{"id":"topic-05","title":"平成１９年請願第４１号、（仮称）大崎五丁目共同住宅新築工事に関する請願","agenda":"平成１９年請願第４１号、（仮称）大崎五丁目共同住宅新築工事に関する請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、住宅課長の話だと、我々の考えをもし飲んでくれるのなら、いつでも工事協定書はつくりますよと、これも先の話で、まず１番があって３番がある話なんだから、１番のまず話し合いの場についてくださいと、そこでもめたら、訴訟になったって工事が進むとなれば、それは協定書なんかできないわけだから、物理的に、それは今までだってそういうことはたくさんあるわけですから、だけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-056"},{"speaker":"石田（秀）委員","kind":"意見","question":"そういう中で、しかしながら、ここで今、請願者の方々が話し合いの場に出る、その中で、例えばここはすべてワンルームからファミリータイプにしてくれということではなくても、ほかのところでも、例えば管理人が地域とのつながりも持ってほしいということで、全体の中でファミリータイプを１戸でも２戸でも入れてもらう、もしそういうことができれば、それは地域との交流。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-057"},{"speaker":"阿部委員","kind":"質問・要望","question":"それからもう１つ、駐車場の関係なんですけれども、これはどうなんでしょう、近くに保育園なんかもあって、これは駐車場から出ていく形なんですけれども、ちょっと道路の幅の関係なんかを考えて、どの程度の危険が予測されるのか、その辺が図面だけでは私はわからないので、理事者のほうで思っているお考えがあれば教えてください。ちょっとワンルームの話と駐車場の話だけをお願いします。","respondent":"齋藤住宅課長","answer":"したがって区としても、住民の皆さん方にご理解いただくために説明を尽くしなさいと、こういう話はさせてもらいまして、工事協定書、管理協定書も住民の方に出したようで、現在住民の皆様の回答待ちだというふうに、先週のときだったか、事業者は言っています。","voiceIndex":140,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"両者の言い分がよくわからなかったんですけれども、例えば工事協定書を結ぶためには計画を理解すれば応じるというのか、事業者の言い分をもう少し教えていただきたいのと、あとこの請願の中に、事業主が１回目には出席したけれども、その後、顔を出していないと書いてありますけれども、事業主がなぜちゃんと話し合いの場に出席しないのか、その理由をもし把握されていたら教えていただけますか。","respondent":"齋藤住宅課長","answer":"施主の判断は、今申し上げたとおり計画変更をする考えはないということですので、これ以上説明することはない、あるいは代行業者がすべて施主の意に従って回答しているから、出なくてもいい、そういう理解でおります。","voiceIndex":142,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"業者が、うちは変更しないから、そういう協議の場には出ないというのは、まさに不届きな話だと思うんです。業者は建てたい、だがそれによって地域の方々は日影、住環境が変わると、お互い困るわけですよね。区として、事業主がきちんと出席をして、計画について説明をして理解を求める、そういう姿勢を持たせるように、ちゃんと事業主に説明会に出なさいと、そういう指導というのはされているんでしょうか。","respondent":"齋藤住宅課長","answer":"したがって、双日としては出席するかしないかに関係なく、事業者の意向を伝えて、開発についても答えているんだと、一成開発設計を窓口として対応させてください、ご理解ください、こういう回答をしているです。","voiceIndex":144,"id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"事業を進める主体であるからして、近隣の方々にきちんと説明による態度を私は示すべきだと思うんです。その１点をもう一度お伺いしたいのと、それと日本経済新聞の記事では、ワンルーム建設でのトラブルが絶えないと、そういう中で各自治体で規制が始まっているという記事なんです。もし他の区の様子、どういう動きがあるのかを把握されていましたらご説明いただけたらと思います。","respondent":"齋藤住宅課長","answer":"したがって双日本体として出るのも難しいということでございまして、歩み寄れる部分について、例えば工事期間の時間を何時から何時までにするだとか、そういったものであれば、幾らでも説明もするし、できると、こういうことであれば事業者も検討できるということのようです。","voiceIndex":146,"id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"それについてお考えを教えていただきたいのと、今期の建設委員会でもワンルームマンションに関する請願も増えておりますので、実際、建設も増えているというお話ですから、あちこちでこういう同様のトラブルが広がっているのかなと感じているんです。","respondent":"岩田まちづくり事業部長","answer":"こういう都会ですから、ファミリー向けだから地域とつながりが持てるかというと、必ずしもどうもそうではないみたいで、ファミリー向けのマンションでも地域とのトラブルは起きているようですから、そこら辺もじっくり我々で調べまして。","voiceIndex":148,"id":"exchange-062"},{"speaker":"中塚委員","kind":"意見","question":"だから１つのまちの仕組みとしての顔のつながる関係をつくりたいということが、そのときよくお話があったんです。実際、きょう日本経済新聞にも、住民票を移さず町内会にも参加しない根なし草のような単身者が増えることは、地域社会の重荷になるという懸念があるという指摘がありましたけれども、もっと地域との関係、もちろんまちのルール、検討すべきものがあるなと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":150,"id":"exchange-063"},{"speaker":"井上委員","kind":"確認","question":"請願に対しては、これは先ほども皆さんからご意見を出されているように、協議の場にまずはついてほしいということなので、賛同できると考えているんですけれども、その中で、行政側がこういう住民とのトラブルの中に入っていろいろな指導をされる中で、説明会の会議録を行政は把握をしているわけなんですが、会議録の提出をする、そういうルールというのは何を根拠にそこにあるのかということが１つと。","respondent":"齋藤住宅課長","answer":"ただ、原則は情報開示請求を行い公開するというのが手続きです。計画の最低の床面積は１８m2ですが、建築確認の詳細のものがまだ出ておりませんので、具体的なものはまだ承知しておりません。","voiceIndex":151,"id":"exchange-064"},{"speaker":"井上委員","kind":"質問・要望","question":"今まで会議録というのは、行政の側が住民から要望があるから出してくださいと言われたときには、すんなりいっていたのか、そうではなく、情報公開請求しなければ公開されないので、そういうふうな手続になったのか、事例のほう、状況はどういうふうになっているのか。","respondent":"齋藤住宅課長","answer":"原則は情報公開が必要ということです。事例でどちらが多いかといいますと、数は把握しておりませんので、詳細はわかりません。","voiceIndex":153,"id":"exchange-065"},{"speaker":"井上委員","kind":"質問・要望","question":"何回かは、きちんと住民側に要望があるので出してくださいという指導は何件というか、具体的に今、住宅課長が以前のことはわからないと思いますけれども、当事者になったその時期にあったことで、実現しているんでしょうか。","respondent":"齋藤住宅課長","answer":"何件かの事例といいますか、情報開示の請求は、住民の方といえども、行政から義務づけの形で情報公開を事業者に強制することは難しいです。","voiceIndex":155,"id":"exchange-066"},{"speaker":"井上委員","kind":"確認","question":"先ほどの居室の件なんですが、各区でワンルームマンションのそういった２５m2以上にするとか、そういうふうなことがもうでき上がっているところがあるということで言えば、これは確認申請が出されていないのでわかりませんけれども、住民の方々の情報によりますと、１８m2ぐらいのところもあるということは事前に伺いました。","respondent":"岩田まちづくり事業部長","answer":"あえて言えば、ワンルームをつくらせないために居住平米を何m2以上ということは言うことはできるかもしれませんけれども、私どもの今のレベルでは、まだまだそこまで踏み切る段階ではないだろうと考えています。","voiceIndex":157,"id":"exchange-067"},{"speaker":"井上委員","kind":"質問・要望","question":"分譲のそういうところで言えば、ある程度の空間があって、住み分けができる、ただ本当にそういう少しのスペースがあるようなところをつくっていって、地域コミュニティーを広めていくというところもとても重要なことだと思いますので、まちづくりという視点で、あと品川区もニーズがあるからということではないところで検討していく時期に来ていると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-068"},{"speaker":"須貝委員","kind":"質問","question":"もう一度ちょっとお聞きしたいんですが、さっき話し合いが何回かあったという部分をもう一度だけ、すいません。","respondent":"齋藤住宅課長","answer":"それは高さの見直しがメインです。大崎第二地域センターで行ったです。次に、理事長、理事の方と９月７日、１０月１３日に２回お話を、あと全体、それと１０月２１日にも第２サンライズ五反田にお住まいの方を対象に説明会をして、１８名の方が出席されているです。","voiceIndex":160,"id":"exchange-069"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、これはなかなか一般の方からすると、こういう話し合いの場で建築主、双日なんかはプロですから、住民の皆さんからとると威圧されているような感覚というのはあると思うんです。終わりのほうに、３番目に工事協定ということがあります。今、とりあえず双方がぶつかっているというような状態ならば、もう少し当委員会としてももうちょっと見守ってやるという姿勢が大切じゃないかなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-070"},{"speaker":"三上委員","kind":"質問・要望","question":"最初に石田委員から質問があったときの住宅課長の答弁で、ちょっと私は一番最初にひっかかったことがあったんです。そういう自分がやっているということと別に、請願項目ということについて、この３つの請願項目がきちっと整理されて、こういう形で請願されたということであるわけですから、これについてきちっと聞かれたならば説明すべき問題であるということでこれはあると思います。","respondent":"齋藤住宅課長","answer":"ただ、住民の方は近年はもめますとボイスレコーダーというものをお持ちで、ボイスレコーダーで証拠としてとっていらっしゃる方は多いですし、私どもも建築紛争が生じた場合は、住民の方もきちんと自分たちで記録をとる、こういう話はさせてもらっていますが。","voiceIndex":163,"id":"exchange-071"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう流れからいったならば、当然、工事協定書、これをつくるためにはそれなりの回数を重ねた話し合いというものが当然必要になってくると私は思いますので、そういった点からの、お互いの要求はぶつけ合うことはぶつけ合ったとしても、どこのところで折り合いをつけるのか、これはまた話し合いの場でも検討されていくことだと私は思っておりますので、そういった点での指導をするということであるならば。","respondent":"齋藤住宅課長","answer":"議会からのご要望でもありますので、またいろいろお話を聞きながら前向きに対応してまいりたいと思います。","voiceIndex":165,"id":"exchange-072"},{"speaker":"藤原副委員長","kind":"質問・要望","question":"だから請願した方は、この請願項目という、これで本当にいいのか、本当にといったら失礼かもしれませんけれども、近隣住民と協議の場をつくるように指導すればいいのか、調和を考慮するように指導すればいいのかというやわらかいのよりも、本当の趣旨は８階を５階以下にとか、補償を出してほしいとか、協定書とか、この辺の本当のお気持ちを知って判断をしたいもので、紹介議員の方に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-073"},{"speaker":"井上委員","kind":"質問・要望","question":"この方たち、今おっしゃった、これが通ったことによって自分たちが要望されることが通ると感じる住民の方がいらっしゃるんじゃないかというところについては、それは私はないと思いますけれども、それは住民の方たちが思うところで、先ほど来、協議の場での項目はそれぞれ皆さんが考えていることだと思いますので、そのことについて私がどこまでそういう思いがあるんですかということを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-074"},{"speaker":"藤原副委員長","kind":"確認","question":"具体的な数字がいろいろな形で出てきたので、８階を５階以下にしてほしいとか、補償の問題とか、あと道の問題、協定書の問題というのが出ましたけれども、改めて井上委員のお話を聞いて確認しますが、協議の場を持つように指導してほしいという形の請願でよろしいんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-075"},{"speaker":"石田（秀）委員","kind":"意見","question":"本日結論を出すべきだと、それだけ、意見は後にします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-076"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはどういう意味かというと、内容ではなくて、決裂状態が少しでも良好な関係にならなければ、２番目に言う周辺地域と住環境との調和、例えば我々の地域でもワンルームマンションが建ったときに、プライバシーの問題があるといって窓をこういうふうにちょっと変えましょうとか、それは業者の方とその近隣住民の方との良好なある程度の話し合いができたわけです。そういうことで変わる場合もある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-077"},{"speaker":"三上委員","kind":"質問・要望","question":"そんなことになると、やはりもう少し話し合いをされて、この確認が出せる最終図面というものが合意になったもので出していくということが私は理想だと思いますので、そこらあたり、やはりもう少し話し合いをしていただきたいなということで趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-078"},{"speaker":"中塚委員","kind":"意見","question":"私は採択をすべきだと思います。その理由、とりわけ強調したいことは、協議の場にすら事業主が来ないなんていうのは、本当に不誠実ですし、私は許されない、間違っていると思います。品川区も、事業主が説明会につくようにきちんと言うべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":183,"id":"exchange-079"},{"speaker":"阿部委員","kind":"質問・要望","question":"先ほど事業主がその後の話し合いに出なかった理由として、８階から５階にという要望が強くて、それがために行かなかったということだったんですけれども、普通に考えて、お住まいになっている方がいて、南側に高い建物ができると聞いたら、まずはウェルカムなはずがないんです。２番に載っています住環境との調和というのも、この文言については確かにそのとおりだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-080"},{"speaker":"須貝委員","kind":"意見","question":"私は先ほど申し上げましたので、双方なかなか行き違いということがあると思います。ただ私は、今、議事録も実際、読んでいるわけでもありませんので、そういうことを考えますと、やはりもう少し住民と事業者の話し合いを見守ってやるということが必要なのではないかなという考えでおります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":185,"id":"exchange-081"},{"speaker":"藤原副委員長","kind":"確認","question":"私は採択でお願いします。紹介議員にもこの請願についてはご確認をちゃんとさせていただきましたので、まず近隣住民との協議の場につくように指導していただくこと、これが一番大事だと思いますので、指導してください。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-082"},{"speaker":"中塚委員","kind":"意見","question":"私は採択すべきだと思いますけれども、全会一致というのも１つ重みがありますので、そういうことでしたら趣旨採択ということで結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":191,"id":"exchange-083"},{"speaker":"井上委員","kind":"質問・要望","question":"菊地委員の質問された広町を中心とした大井町駅の逆側といいますか、道路関係のお話とか、そういったところについて、今後、協議をする場面になれば、今まで協議したことが前提に進められていくというような答弁があったんですけれども、その辺のところをもう少し詳しく説明をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-084"},{"speaker":"井上委員","kind":"意見","question":"答弁の中で、広町のＪＲのところを含めて、協議しているときに、さまざまな開発による交通整備が必要となるため、そのためのシミュレーションを行ってきたということで、これからまたその先そういう場があったとすれば、インフラ整備は今後は協議した内容で、それを前提に進めていくということを示されましたので、そういう意味ではどういうシミュレーションが必要だったのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":199,"id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3896#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":74941,"voices":201}},{"id":"h19-20071126-9","meetingId":"h19-cm11","date":"2007年11月26日","dateIso":"2007-11-26","committee":"文教委員会","time":"午前１０時０１分～午後４時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第８２号議案、学校教育法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","agenda":"の第８２号議案、学校教育法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、説明がありましたけれども、現行法の資料はいただいたのでわかったんですけれども、入れ替わるほうの新しい条文、法律ですけれども、これをちょっと一つ一つ教えていただきたいと思うんです。内容的にほとんど変わりはないと思いますが、ちょっと改めて確認をさせていただきたいと思いますので、よろしくお願いします。","respondent":"市川庶務課長","answer":"基本的には、条数の移動だけのものは、各種学校と学校施設の社会教育の利用、この２つの条文が全くの条数の移動です。一番多い幼稚園の条文ですけれども、これも原文の第７８条が今般２３条ということで変わりますが、若干表現の改正が行われてあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"この条文がこのところの紹介がありましたけれども、２３条の２項のところの表現が、これは集団生活のみ、就学前の子どもにとって、集団生活するのは教育を行っていく上で、大事な中核だと思うんですけれども、そこの集団生活のところに、「規範意識の芽生えを養うこと」という表現があるんですけれども、２３条の２項にそういう表現があるということで、確認したいんですけど、そうですか。","respondent":"市川庶務課長","answer":"改正後の第２項を全文読み上げますと、「集団生活を通じて、喜んでこれに参加する態度を養うとともに、家族や身近な人への信頼感を深め、自主・自立および共同の精神ならびに規範意識の芽生えを養うこと」、こういう規定になってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そうしますと、７８条と２３条の内容は全く同じというふうに考えていいんでしょうか。","respondent":"市川庶務課長","answer":"先ほど、私の説明をとらえて、全く移動がないというところで、移動があるのではないかという限りにおいては、そういう若干の表現なり、考え方の違いがあるということは、今回の改正について言えるかと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"参考につけたという、教育基本法の改正の中身、私持ってきたつもりが、ちょっと見当たらないんですけれども、要するに教育基本法がちょうど１年前、今頃の時期に改正されましたよね。それをがらっとまた変えていくということで、私ども共産党は反対をしたんですけれども、その反対をした理由の１つに、この今、２３条の２項に書いてある「規範意識」。その辺をちょっと伺いたいと思います。","respondent":"市川庶務課長","answer":"その改正の条文を引用している区のほうの条例について、あくまで整理をするために、今回提案させていただいたものですので、今、委員がお話になったもとの学校教育法に対する考え方はあろうかと思いますけれども、これはあくまでも法律改正に基づく条例の規定の整備ということで。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"そして愛国心を国民に強制するという内容が、ちょっと貫かれた教育基本法になっちゃったわけですから、そういう点でどうかなと。愛国心というのは、ちょうど今日の１年前にいろいろ議論があったように、一人ひとりによって国を愛する心というのは、いろいろですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"先ほどから、たまたま変わった理由というのが、参考資料をいただきましたけれども、幼稚園を最初に規定するというふうになったわけですが、その考え方はどういう考え方なのかなというところ。この改正で、品川区の考え方として、どういうふうに運営していくのか。教育委員会としてのかかわりはどこまで変わっていくのかについてお聞きしたいと思います。","respondent":"市川庶務課長","answer":"これがこれからの品川区の課題でもあるかと認識しています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"幼稚園、就学前というところも含めて、義務教育という動きというか、その中での一環という、品川区ではそういう考え方なのだろうと思います。そこを品川区としては今後どういう連携をとっていくのか。その他の現場のところでは、こういうのが始まっているとは思うんですけれども、これをどういうふうに今後考えて、さらに推進をしていこうとしているのかというところがわかれば、教えていただきたい。","respondent":"市川庶務課長","answer":"ただ、この間、区長部局の現場のほうでは、いろいろと今回のご案内のとおりですけれども、教育委員会等で、例えば小中一貫教育と幼保との連携、こういった新しい視点も打ち出しているわけでございまして、この辺、現況どおりに具体的にこれからどうしていくかというところで。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"幼稚園もそうですし、幼稚園と保育園間もそうですし、就学前と小学校というところの教員間の文化の違いがあるでしょうし、その辺のところの修正というのは、今後どれだけつくっていくのかを最後にお聞きしたいと思います。","respondent":"河野指導課長","answer":"そういう前提のもとで小学校教育を展開しておりますので、どうしても一人ひとりの子どもに目を行き届かせるということに重点を置かれている。それに対して中学校の教員というのは、３年生になって卒業するときの出口を基準にして考える。","voiceIndex":19,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"事例が小学校、中学校よりはというところで、やはりそこに保育園が入ってくるという、やはり細かいところの調整は必要かと思いますので、それは今後とも教育委員会として、現場のほうに目を移していただいて、なるべく細かい手当といいますか、対策をしていっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"}]},{"id":"topic-02","title":"の８４号議案、品川区立学校施設設置条例の一部を改正する条例","agenda":"の８４号議案、品川区立学校施設設置条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"八潮のほうの問題からまず質問したいんですけれども、ちょっと改めて５校を統合するという方針に転換したあたりのことを思い返してみたんですけれども、学校関係者、ＰＴＡ、地域も含めて、いつの時点で了解というふうになったのか、日にち、どこのレベルでということについて、改めて伺いたいと思います。そして、また後で荏原のほうは伺います。","respondent":"古里学務課長","answer":"八潮の５校の統合につきましては、八潮南中学校が入学者ゼロになったことを契機に八潮地域の中で話し合いを進め、従来、八潮自治会連合会から、一貫校の設置についてのご要望があったということから、鋭意、それぞれの学校と話し合いをし。","voiceIndex":33,"id":"exchange-010"},{"speaker":"南委員","kind":"確認","question":"今の課長の答弁では、５月３０、３１日の説明の後ということですね、今の課長のご答弁では。ちょっとそこを確認したいと思います。","respondent":"古里学務課長","answer":"すみません、ちょっと資料の手持ちがございませんので、正確な日付については、今、記憶で申し上げておりますので、もし間違ってございましたら、後ほど訂正をさせていただきたいと思います。","voiceIndex":35,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"私は改めて、資料をとって調べて、読み直してみたんですけれども、この八潮のほうは、平成１８年の第１回定例会で代表質問があり、その中でそういう方針になっていくんだということが確認されて、一気呵成に５校統合という方向のレールが敷かれたんですね。ですから、どういうふうにその辺のリサーチをされてきたのかを具体的にちょっとご紹介していただきたいと思います。","respondent":"古里学務課長","answer":"それで、こちらにつきましては、それ以降、３月、４月という段階で学校それぞれ、ＰＴＡに関する説明会等も鋭意行ってきておりますし、それからＰＴＡ会長協議会を通して、ＰＴＡの会長のご意見、それから各ＰＴＡでの話し合い等をしていただき、それらを集約した中で。","voiceIndex":37,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"５月３０日に、これは八潮の５校のＰＴＡの説明会が教育委員会主催なんでしょうか、開かれて、この中で少人数で頑張っている学校もあるじゃないかとか、それから子どもの意見をないがしろにして、大人の意見を貫こうとするのはまずいとか、それから学校選択制度に従って、親子で相談して学校を選んだのに、こういうふうに切磋琢磨している。","respondent":"長田教育次長","answer":"私たちの認識としては、八潮にしても、荏原西の問題にしても、それぞれの段階で、地元の町会長さん、自治会長、あるいはＰＴＡ、それから関係者を含めた中で、意見を聞いた上で判断をしてここまできたですから、今、学校の統合をしていく問題については。","voiceIndex":39,"id":"exchange-013"},{"speaker":"南委員","kind":"確認","question":"そういう内容の議案だということは承知して議論しているつもりです。今度は繰り返しませんよという、教育委員会としての姿勢が表明されていかなければいけないと思うんですけど、それはいつなんですか、どういう形でされたんですかと聞いているんですけど、それについては、何回聞いても全然はっきりしないわけです。そのことをちょっと聞いているんです。","respondent":"長田教育次長","answer":"そういった意見を踏まえて教育委員会としては検討してきたわけですので、そういった中で、５月の段階では地域として、それからＰＴＡ関係者、こういった方々も了解をしていただいた。こういうような判断を私たちはしています。","voiceIndex":41,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"私は５月頃に了解をしていただいたということでありますけれども、しかし、ことここに至って、まだまだいろいろな意見があることは事実だと思います。そして繰り返さないための教育委員会としてのこの問題についてのきちんとした検証、学事制度審議会に投げるのではなくて、教育委員会自身が繰り返さない姿勢を確認しない限り、私はそうですか、了解されたからいいですと言うことはできません。反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"小規模というので、質問しますが、旧のところに（１）の小学校の表の下に（新設）と書いてあるんですが、これは関係ないんですね。それと、あと一貫校になった場合に、愛称という位置づけなんでしょうか。そこまで話が出されていないのかな。何のためにこの名前を使っているのか、どういう関係で、こういうふうに一貫校の愛称というのをつけているのかということをお聞きしたいと思います。","respondent":"古里学務課長","answer":"それと荏原西のほうの一貫校ですけれども、一貫校として立ち上がるのは、あと２年後になりますので、愛称名については、改めてその時点で今後も含めて、募集をした後に検討を進めていくということなります。","voiceIndex":45,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"わかりました。ありがとうございました。要するに、この順番というのは、新設校という意味で順番が下のほうになっているという理解でよろしいですね。そこを皆さんのご理解を得ながら、決定していただきたいと思いますので、あと２年間ありますので、十分にご検討いただきたいと思いますが、その考え方についてお答えをお願いします。","respondent":"古里学務課長","answer":"それから各校の名称もつけたいですけれども、そういうことも踏まえた上で、２年後に決定する段階では、そのようなご意見もあったことを踏まえて、議論を進めていくようにしてまいりたいと思います。","voiceIndex":47,"id":"exchange-017"},{"speaker":"市川委員","kind":"質問","question":"補正予算で、制服のことや統合された新しい学校に加配等の費用というのが盛り込まれたんですけれども、今後、ほかの学校との整合性ということをどのように考えているのかということをお伺いいたします。","respondent":"古里学務課長","answer":"そういうふうに一応考えております。","voiceIndex":49,"id":"exchange-018"},{"speaker":"市川委員","kind":"質問","question":"すみません、先ほど質問はありませんと言ったんですけれども、今後、こういう制服補助とか、加配等の補助ということが起こり得るのかどうかというあたりはどうなんですか。","respondent":"古里学務課長","answer":"そこにつきましては、まだ仮定の話になりますので、今のところ、荏原平塚中学校につきましては、この統合の形は、これは荏原西区の中学校の教育環境という点からは、看過できないということで進めたものですので、今後起こってくるということについては。","voiceIndex":51,"id":"exchange-019"},{"speaker":"金野委員","kind":"質問・要望","question":"やはり母校の名前が変わるよりも残ったほうがいいという地域のご意見がたくさんあるので、どちらが先かという議論もありますが、このように母校の名前を残していただく方向で、要望しまして、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-020"},{"speaker":"市川委員","kind":"意見","question":"ネットは反対です。それで、やっぱり途中段階で市民に公開をして、意見を聞くという、混乱を恐れずに合意形成を図るという、行政はそうあるべきだと思いますので、これに関しては反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-021"}]},{"id":"topic-03","title":"平成１９年請願第３２－２号 一人一人の子どもたちが大切にされる品川区を求める請願、項目の４、５、７","agenda":"平成１９年請願第３２－２号 一人一人の子どもたちが大切にされる品川区を求める請願、項目の４、５、７","exchanges":[{"speaker":"金野委員","kind":"確認","question":"５番については、学童保育機能を明確にしてというような文章があるんですが、このすまいるスクールは私ども認識としては、学童保育の機能も備えてのすまいるスクールと認識をしているところですので、そのすまいるスクールでの安心に過ごせているという、この安心というところについてもどのような形ですまいるスクールを行っているのかというのも、確認のため伺いたいと思います。","respondent":"市川庶務課長","answer":"その学校の生徒数の多い少ない、これがまた学校施設全体の使い勝手にも反映されてくるわけですけれども、ただその中で、先ほども少し触れましたが、学校との連携協力ということで、すまいるスクールの専用室が十分に確保できない場合、学校との共用スペースということで。","voiceIndex":66,"id":"exchange-022"},{"speaker":"金野委員","kind":"質問・要望","question":"そのご説明で、より学校教育の中におけるすまいるスクールの実現というのは今、確認させていただきましたので、今後のさらなる発展というんでしょうか、現時点であるすまいるスクールをさらにお母さん方の声を伺いながら、いいすまいるスクールにしていただきたいという要望も含めてお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-023"},{"speaker":"西本委員","kind":"確認","question":"学童保育というのが、かなり、私は学童保育を経験している中で、例えば出欠の確認であるとか、それから親への連絡事項であるとかということをかなり細かくやっていただいていると思うんですが、その辺の対応はどうされているのかなというところ。その辺はどういうふうに変化といいますか、放課後の生活の変化をどうされているのかというところについて、まずお聞きしたいと思います。","respondent":"市川庶務課長","answer":"それと、おやつの問題についてですけれども、現在、委員のご発言がございましたけれども、夏休みなどの長期休業期間中、それと個々の子どもに事情がある場合、補食というものについては対応しています。","voiceIndex":69,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"保育園が６時頃までになりますので、どうしても延長保育をやってほしいという気持ちもわからないでもないんですが、ただ学校に入ってくると、学校の生活というのは教育を担ってきますので、そういう意味では保護者の役割というのをしっかりとすまいるスクールの方も指導をしていただきたいなと、その点の考え方を伺います。１５人と１６人は教育環境としてどうなんだろうと、そういう点いかがなのかなと。","respondent":"市川庶務課長、河野指導課長","answer":"私からはすまいるスクール、まず１点目の学校、４０のすまいるスクールの全体のレベルアップ、このご指摘については、私どももそれが一つ大きな事業課題であるという認識は持ってあります。学級の規模が子どもたちに及ぼす影響ということを考えると、確かに教員１人当たり、指導する子どもの人数が少ないと、教員は非常に楽です。","voiceIndex":71,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば複数担任をつけたりとか、あとは習熟度別の授業をしたりということで、結構、今の品川区の学校の中で、人数だけ見てみると、いろいろな場面で少人数でやっているというケースがあるんじゃないかなと思うんですが、ですから、別に３０人と決めなくても、わりと現場サイドでは、工夫して少人数の場合にはそれをやっているとか、大きい人数の場合には、例えば学校の中で人数が少なければ。","respondent":"市川庶務課長、河野指導課長","answer":"そういうことも視野に入れて、今後事業をいろいろ取り組んでまいりたいと考えております。そういう点では、それぞれ、その状況に応じた適切な対応でさまざまな集団に対する指導を学校が展開しているです。","voiceIndex":74,"id":"exchange-026"},{"speaker":"山内委員","kind":"質問","question":"５番の「すまいるスクールに通わなければならない子どもたちが安心して過ごせるような」という、このような文言があるんですけれども、これも同じく、やはり理事者の方々、それから皆さんの地域の方々が綿密に計画をしてやっていると、私は認識しているんですけれども、本当にこういうことが挙がってくるということに関して、私はちょっと疑問に思うんですけれども。","respondent":"市川庶務課長","answer":"あるいは高学年、どうしても低学年の子の参加が多いもので、低学年の子のほうを軸にした事業展開をしていますので、やはり高学年の子がもう少し興味を持てるようなものとか、総じて事業内容についての声というものを承っておりまして、繰り返しになりますけれども。","voiceIndex":77,"id":"exchange-027"},{"speaker":"山内委員","kind":"質問・要望","question":"今、ご答弁いただきまして、非常に安心をしまして、やはりこういうような施設というのは、本当に大事なものだと考えていますので、これは要望になりますけれども、さらに小さなことでもしようがないと思うんですけれども、そういう意見というものはそういった段階で、対応していただければと思いますので、また計画を練っていただくとか、そういうことで計画をしていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-028"},{"speaker":"南委員","kind":"確認","question":"厚生労働省が新しく出した指針には、児童１人当たり１.６５m2となっているという、ちょっと資料を持ってこなかったので、正確な数字は出ないんですけれども、その辺の決められた望ましい基準から見て、すべてのすまいるスクールがそれをクリアしているのかどうか、ちょっとその辺をまず伺いたいと思います。","respondent":"市川庶務課長","answer":"これは学童保育の専用施設としては、そういう位置づけができるでしょうけれども、すまいるスクールは全児童対策ということで展開している事業ですので、こういう示されたものは、１つの方向性としては、私どもも意識はしておりますけれども、先ほど来申し上げているように。","voiceIndex":80,"id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"その６校は登録している子どもさん、日常的に参加をしている、利用している子どもさん、その現状から見て、１教室しかないというのは、スペース的にくつろげる空間とか、そういう部分のご要望のところを見たときに、どういうふうに理解したらいいのかというのがわからないので、ちょっと認識を教えてください。","respondent":"市川庶務課長","answer":"そういうことで現場の事業ニーズに対応しているということで、現場ではそういう学校との連携協力、努力をしているということで、先ほど来申し上げているところです。","voiceIndex":82,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"それで、なぜそういう機能をと、あるいはくつろげる空間をという、このところなんですけれども、ちょっとそれを聞く前に、大体すまいるスクールに参加している子どもさんたちが、大方の時間で結構ですけれども、授業そのものが５時ぐらいまでだと、私は思っているんですけれども、６時まで、ちょっとその辺を教えていただきたいのと、一番子どもたちがごっそり帰る時間帯というのは何時ぐらいなんですか。","respondent":"市川庶務課長","answer":"それとあと、今、過渡的に、例えば校舎改築している小山のように、経過的に１部屋というところもあります。ほかの学校では先ほど申し上げた、学校の教室との共用ということで対応しております。","voiceIndex":84,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、その辺についてちょっと非常に心配するので聞いているんですけれども、大体登録している子どもさんの７割ぐらいが、日常的にすまいるスクールを利用しているという話ですけれども、その中のどのくらいが学童保育なのか、そういうチェックを日常的に行って、親が働いていても、安心して親がいない時間、帰宅するまでの時間、子どもが学校の中のすまいるスクールで、友達関係を深め、交流し。","respondent":"市川庶務課長","answer":"区民に喜んでもらえない事業とおっしゃいますけれども、私は担当課長として、そういう認識は一切持っていませんので、そのことは冒頭申し上げておきます。","voiceIndex":86,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"今のところから、ちょっと申し上げますと、大体４０人から６０人というと、三、四割だということなので、十四、五人から二十数人という数ですね。したがって、その辺について、さっきから強調して伺っているんですけれども、確かに数的には少ないけれども、そういう要求に対して受けとめる意思というか、その辺についてはどうなんですか。それが１つ。その点について、ちょっと改めて伺いたいと思います。","respondent":"市川庶務課長、河野指導課長","answer":"１点目の障害児あるいは何らかのそういう事情を持った個々の子どもの要望というんですか、それについて受けとめる意思があるのかないのかということですけれども、これは就労家庭の子どもであろうとなかろうと、そのいかんを問わず。実際問題、各自治体でそれを全部負担するならば、自治体独自の教員採用試験で任用する制度もありますけれども、現在、品川区の中の状況を見ている限り、４０人学級のもとでの定数配置、それに加えてのいわゆる定数外配置。","voiceIndex":88,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"それは、少人数の体制、子どもたちを細分化した中で行うことが望ましい、そういう状況が意識として教育委員会にあってそういう体制を行っているということですよね。だから、その辺で、なぜ３０人学級、少人数学級を実現させてほしいという願いがあるときに、私はそれと一致するんだろうと思うんですけれども、なぜ違うのかということを聞いているんです。","respondent":"河野指導課長","answer":"すべての授業で少人数、あるいはＴＴの授業をしているわけではございません。それぞれの学習内容であるとか学習形態の中で、これは少人数でやった方がいい、これは大勢でやった方がいい、そういう場面に応じた指導をしているですので、その辺はぜひご理解いただきたいと思います。","voiceIndex":91,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"現実に品川区内の４０校の小学校、中学校もありますけれども、とりわけ小学校の方では、少人数学級を意識して、現実的にクラス編成をしている学校は幾つもありますよね。二、三日前に確認しました。したがって、例えば私の地域の八潮北小学校は、希望する子どもさんが少ないという現状、あるいはあの地域に暮らしている小学生が少ないという現状もあるけれども、少人数学級になっているじゃないですか。","respondent":"河野指導課長","answer":"一部の中学校についても同様のことがあるのではないかというご指摘ですが、学級編成としてはあくまでも４０人学級を前提としておりまして、この活動の場面を、学習以外の部分にも広げて少人数で実施しているという例については、私どもは把握しておりますけれども。","voiceIndex":93,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"４０人学級を前提としていますよ。だって、現実的に品川区の教育委員会が４０人学級編成を前提としてやっているわけですから。そういう状況がありながら、しかし現実的には学級を細分化して学級編成をするという表現をすると違うとおっしゃるのかもしれないけど、現実的には少人数教育をしているじゃないですか。ないんですか。そういうことができるんじゃないんですかと質問したんです。","respondent":"河野指導課長","answer":"先ほどから申し上げていますように、現在、すべての学校で少人数指導は実施しております。ただ、すべての授業で少人数をやっているわけではなくて、それぞれ場面に応じて、あるときには学年全体でやるときもあります。学級単位でやることもあります。","voiceIndex":95,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"そういう答弁をするなら、学校名を出すと後のいろいろな影響があるのかもしれないから私はあえて言いませんけれども、しかし、少人数の編成で、１クラスに二十数人、あるいは十数人という、２０人前後のクラスで、１クラスのところを２クラスに分けてやっているという学校はありますよ。知らないというふうには言えないと思いますけど。今の答弁からして、それはどうなんですか。","respondent":"河野指導課長","answer":"すべての学校で、例えば４０人のクラスを二つに分けて授業をするという、いわゆる少人数指導はやっております。場面に応じてやっております。それは全く否定しておりません。","voiceIndex":97,"id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"すべての場面じゃなくて、場面場面で少人数の教育をやっているということと、それは説明としては理解できますけれども、しかし現実的にどこどこ学校の何年何組何人、何年何組何人という、こういう体制をとっている学校は、すべての授業を２クラス編成でやっているわけじゃないんですか。言っている質問の意味、わかりますか。","respondent":"河野指導課長","answer":"あくまでも、それぞれの学校が教育活動を実施していく中で、より適切である、より効果的であるという方向に基づいて、ある場面で少人数指導をやったり、習熟度別の学習をやったり、あるいは大集団での指導をしたりです。","voiceIndex":99,"id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"あるいは中学校の場合、学級編成を、そこの学校の教育目標を達成するために２クラスに分けて、少人数で１組あるいは２組という構成にしている、そういう学校の授業は、国語あるいは数学、そういういろいろなすべての教科について、何年何組という、その１組単位の授業になっていない部分もあるんですか。","respondent":"河野指導課長","answer":"先ほどから申し上げているように、一つの学級、あるいは複数の学級を、例えば２学級を三つのグループに展開したり、１学級を二つのグループに展開して授業をやるということについては、現在品川区内すべての学校で行われています。","voiceIndex":101,"id":"exchange-039"},{"speaker":"南委員","kind":"確認","question":"そういう学校については、課長の説明では、場合によってはそういう３クラスに分けて習熟度別をやったりとか、そういうやり方をやっているわけじゃなくて、私が質問しているのは、１組、２組とあった場合に、１日の学校生活、授業のすべてがこの１組を単位として国語だの数学だのいろいろな教科の授業を受けているんじゃないかと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"だけど、その学校の教育の特色として、あるいは教育目標を達成させるために４０人というクラスじゃなくて、少人数の学級編成をやっているという現実があるのに、そこのところを見ないで「品川区は４０人学級編成なんだ」というところだけでやってきているというところは、区民の願い、子どもたちの求める学力を身につけるという願いに対しては、もっともっと配慮して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-041"},{"speaker":"南委員","kind":"意見","question":"そこのところは教育委員会としてもきちんと認識をされて、改善の努力をするべきだと思うんです。したがって、この請願については、充実してほしいというこの願いは、本当にこれからも大事に、区民の代表の議員としては、大事に扱っていくべきではないかと思いますので、ぜひこれを実践させていくためにも採択をしていきたいと思います。結論を出すということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-042"},{"speaker":"金野委員","kind":"意見","question":"現時点では、これらの請願の中の内容に関しては、理事者の答弁からは進めてくださっている現状もある。「ねばならない」というような発言が多く委員の方からされたことに関しても、「ねばならない」という観点ではなく、品川区としては、現状ちゃんとこのように進めていることというのもあるので、この請願に対しては不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"要望を受けとめていればいいけど、そういうところで残念に思っています。３０人にしなければならないということではなくて、教育全般において、子どもたちの状況を見て、いろいろな対策を使っているというところでは、むしろ柔軟な対応というところで残していただきつつ、現状の制度について変えられるものか、教育委員会にも対応していただいて、非常に今後も進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-044"}]},{"id":"topic-04","title":"平成１９年請願第４３号、学校給食の民間委託の充分な検証と、学校給食のあり方の再検討及び栄養士の未配置校に学校給食民間委託を拡大しないことを求める請願","agenda":"平成１９年請願第４３号、学校給食の民間委託の充分な検証と、学校給食のあり方の再検討及び栄養士の未配置校に学校給食民間委託を拡大しないことを求める請願","exchanges":[{"speaker":"南委員","kind":"確認","question":"確認したいと思います。荏原第四中学校のことについては知りようがありませんので、改めて伺いたいと思います。そして同時に、既に２６校民間委託をしているというふうに思っているんですけれども、この数の確認を改めてしたいんですけれども、その民間委託校には栄養士がどの程度配置されているのか。配置されていない学校もあるのか。その辺をちょっと伺いたいと思います。","respondent":"古里学務課長","answer":"この業者の方から、当初の予定どおり経験者を配置し、それからチーフにもそれなりの経験を持った人間を配置するという契約上の約束でしたけれども、それが職員の側で、例えばサブチーフが家庭の事情で休業を余儀なくされているとか、突然の職員の退職があったというようなことで。","voiceIndex":126,"id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"そのときに、担任が本を読み聞かせて子どもたちを待たせていた、これについても事実なんですか。「スープの味がおかしいなどとても食べられる状態でないことがありました」、これについてはどうなんでしょうか。ちょっと一つひとつ確認をさせていただきたいと思います。それをしないという考え方はどんな理由によるものなのかを教えていただきたいと思います。","respondent":"古里学務課長","answer":"それは、調理場の形が違ったりしていることから、学校別の仕様書というのがございまして、その対応状況が正確に行われているかどうか。それから人員体制、あるいは配置状況についてはどうなっているか。業務責任者の力量についてはどうか。","voiceIndex":128,"id":"exchange-046"},{"speaker":"南委員","kind":"確認","question":"そうすると、公表はしているというふうにとらえては不正確ですか。返す返すも、業者の選定も含めて非常に軽率な教育委員会の姿勢にあったんじゃないかということを率直に追及しなきゃいけないと思います。非常に残念だと思います。そういう立場に立てばと思うんですけれども、その辺の見解をちょっと伺いたいと思います。","respondent":"古里学務課長","answer":"大間窪小学校と荏原第四中学校のこと、これが軽率な判断であったというふうなご意見ですけれども、私どもは、総合評価という区が施行した制度の中で、一定の業者の評価をし、この業者が保育園の調理代行の方では極めて優れた評価を得ているということから。","voiceIndex":130,"id":"exchange-047"},{"speaker":"南委員","kind":"確認","question":"変わらないで、同じ方がずっと同じ学校に勤務をするんでしょうか。そういう契約内容になっているんですか。したがって、品川区の学校給食は安全でおいしいんだという評判が高まっていたわけですけれども、民間業者はそこの担保ができないんじゃないんですか。できるんですか。それがなければ、見せてくれるからいいんだというふうには私はならないと思いますので、そこもあわせて伺います。","respondent":"市川庶務課長、古里学務課長","answer":"私から１点、給食調理の職員による業務と委託業務、違いがあるんじゃないかというご指摘ですけれども、確かに、すべての学校で調理職員の手によって調理業務を進めていた、そういう時代があったわけですけれども、ご案内のように。公表の範囲ですけれども、これは学校給食で行っているものですから、この業務に関連をしている人については、例えば学校のＰＴＡですとか、保護者ですとかというところから公開をしてほしい、あるいは見せてほしいということがあれば。","voiceIndex":132,"id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"それから説明をよく伺いたいと思いますので、ぜひ、各学校での検証を、校長先生方が行っている２３項目の検証というのは、それはそれとしていいことですからやっていただきたいと思いますけれども、教育委員会としてもきちっとした実態調査を、私はするべきだと思います。それと、デザートのフルーツなどが出るのがほとんどなくなった、そういう状況についての認識があるのかどうかを伺いたいと思います。","respondent":"古里学務課長","answer":"大間窪小学校、それから荏原第四中学校で起こった事件について水に流して仕方がないみたいなことですが、私ども、決してそのようなことは考えてございません。","voiceIndex":135,"id":"exchange-049"},{"speaker":"金野委員","kind":"質問・要望","question":"この調理代行を品川区が進めていく、この給食のあり方というところに対しては、非常にこの調理代行の人たちのいわゆるいろいろな民間活力と言われている、そこをもって、よりよい給食をというところで見ていくときに、この調理代行の監督、運営をしていく栄養士の仕事のあり方というんでしょうか、というところを自分なりに認識はしているつもりなんですが、監督していくだけでなく。","respondent":"古里学務課長","answer":"代行を始める前、あとの検討ですけれども、先ほど庶務課長のほうからも申し上げましたけれども、必要なときに必要な人材を必要な量、配置をするということで、効果的な効率的な給食運営を行うとともに。","voiceIndex":137,"id":"exchange-050"},{"speaker":"金野委員","kind":"質問・要望","question":"私の中での調理代行という方たちへの業務の遂行に当たってのいい点と悪い点、その点での確認ができましたので、すごくこの調理代行ということに対して、何か直営じゃないといけない、ねばならないというような考え方というのは私にはちょっと理解ができません。そういう認識はぜひ持っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問・要望","question":"その方向性として何か手だてがあるのかどうかを、お考えがあればいただきたいと考えています。そうなってくると、何が違うんだろうかなというふうに思います。そういう何というか、表面ではなかなか見えないところを何か見えるような形ができると、せっかく一生懸命やっている業者を排除するということになりはしないかなと思うんですが、そのお考えについて、いかがでしょうか。","respondent":"古里学務課長","answer":"それからアレルギー対応についてのことがございましたけれども、確かに学校給食のあり方は、今後食育という問題を考えたときにも何らかの手だてが必要であろうというふうなことは考えているところでございまして、来年度、東京都教育委員会のほうで。","voiceIndex":140,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"これは順次委託化してくると、今、調理のほうが退職される方もいらっしゃると思うんですけれども、実際は何人か残っていて配置転換になるかとは思うんですが、そこの中でも優秀な方もいらっしゃると思うんですよね。そういう考え方をお聞きしたいと思います。先ほどの栄養士の補助的な役割として何か手だてがないかどうか、お考えをお聞きしたいと思います。","respondent":"市川庶務課長","answer":"この目的は、委員のご指摘のあったところを含めて、豊富な現場で得たノウハウを活用した上で、学校栄養職員の指示のもとで衛生指導、調理指導をはじめとして、必要な栄養士の業務の補助を行わせて調理代行の円滑な実施・定着を図る。","voiceIndex":142,"id":"exchange-053"},{"speaker":"西本委員","kind":"意見","question":"今ある人材というのを、活躍していただくということも一つ大きな視点だと思いますので、今、試験的にされている２名の方、その方たちもご更新いただいて、来年度、膨らませつつ、うまく民間の魅力が使えればいいかなというふうに思っていますので、よりよい取り組みを実現してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":144,"id":"exchange-054"},{"speaker":"市川委員","kind":"質問・要望","question":"私もちょっとわからないので教えていただきたいんですけれども、先ほどから代行業者へした検証はしっかりやっていますというような答弁があったんですけれども、現場と校長先生でやるのかどうかという点と、それからどういうやり方で検証をしているのかというところがわからないんですけれども、教えていただきたいと思います。","respondent":"古里学務課長","answer":"先ほど２３項目申し上げたのは、日々行われている業務、これを改善するという意味で２３に分けたですので、それを実際にどうやっているかですけれども、そのチェック表を持って栄養士が定点で何回か見ていきながら、最終的に評価会議の中で最終評価をつける。","voiceIndex":145,"id":"exchange-055"},{"speaker":"市川委員","kind":"質問・要望","question":"流れについてはわかりました。私たち生活者ネットワークの毎年の予算要望で、学校給食に関しては４者協議会を定期的に開いて当事者、保護者、例えば子どもたちの意見を聞くのが望ましいということで、予算要望でそのことを要望しているんですけれども、実際に４者まではいかなくても、そういう保護者などを入れた協議会の開かれている現状というのはあるのかちょっとお聞きしたいんですけれども。","respondent":"古里学務課長","answer":"教育的な配慮、判断ということもありますので、学務課としてはこのようにしていただけないかということは申し上げることはできますけれども、最終的なご決定はあくまでも校長先生の責任で行っている事業ですので、そのように考えているところです。","voiceIndex":149,"id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"ちょっとさっき、質問のときには申し上げませんでしたけれども、２３区の中でいくつかのところでは、やはり民間委託している学校には栄養士を配置しているというふうな、そういうこともあわせて区民の理解をいただいている、そういう努力している区があるというのを聞きまして、私もその角度で調べてみたら、大半の委託校に栄養士を配置しているという事実はありますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-057"},{"speaker":"市川委員","kind":"意見","question":"生活者ネットワークとしては、この請願に対しては採択ということで意見を言わせていただきます。それから検証を、やはり検証結果を公表するというところが民間業者の姿勢に大きく影響するのであるというふうに思いますので、ぜひ公表については、していくべきだというふうに思います。以上が採択の理由です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":154,"id":"exchange-058"},{"speaker":"山内委員","kind":"質問","question":"いや、そうだと思うんですよね。ですから、やはりそういう、ここは意識の問題だと思いますので、それはやはりプロがつくるというものであって、そういう部分では、民間であろうが直営であろうが、私は関係ないと思いますし、逆行しているのではないかという意味で、私はこの請願に対しては反対を表明いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-059"},{"speaker":"金野委員","kind":"質問","question":"いろいろな意味での力をかりて、よりいいものをつくる、その考え方に則ったときには、この力も、調理代行の力もかりていく必要があるのではないかという見方で私は発言をさせていただきましたので、その点に関して、改めて、その言葉の意味というんでしょうか、ご指摘があったことに対して意見を述べさせていただきました。その上で、この件に関しては不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-060"},{"speaker":"石田（慎）委員","kind":"意見","question":"ここの請願理由にちょっと出ているところの事故等という、非常にあってはならないことではあるんですが、直営でも民間でも事故が起きてしまうという可能性に関しては、どちらでも同じではないかと思います。理事者からの答弁を聞き、総合的な観点から、運営上でも十分対応できているということで、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、今の学校給食がどうあるべきかというところ、考えるべきところは再度考えていただくなり、今後、常に見直していく、それが民間の活力をどれだけ導入し、直営であるべき意味がその中にあるのであれば、それを採用すればいいわけですし、もう少し広い意味で、今後私どもは見ていきたいと考えていますので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-062"}]},{"id":"topic-05","title":"の品川区小中一貫校の設計事業者の決定","agenda":"の品川区小中一貫校の設計事業者の決定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"なかなか今の現状を見て、比較して、小中一貫校ですから当然一体になるわけですけれども、使い勝手がよくなるのかなというふうには印象を持つんですけれども、一つ、このプランニングに当たって、こういうプロポーザル条件というのを提示されたということですが、学校現場の方々の意見というのはどの程度反映できているのかというのが一つ。以上４点です。","respondent":"市川庶務課長","answer":"それを今回のこの計画の中で、どうにか改善できるかできないか、こういう視点です。","voiceIndex":166,"id":"exchange-063"},{"speaker":"南委員","kind":"質問・要望","question":"これから具体的なところをもちろんもっと詳細に詰めていくわけですけれども、学校の中のやりくりをしなくてもいいようなスペースを確保するということで、やはりきちんと位置づけていただきたいということを、先ほどの議論があるだけにちょっと気になるところなので伺ってみたいと思います。","respondent":"市川庶務課長","answer":"それと、２点目のすまいるスクール、これは、私自身がすまいるスクール事業の担当課長でもございまして、先ほど申し上げましたけれども、この事業に必要な施設の確保ということでは、この計画事業の中でも十分取り組んでいきたいというふうに考えていることが一つ。","voiceIndex":168,"id":"exchange-064"},{"speaker":"山内委員","kind":"質問","question":"選定理由のところでちょっとお尋ねしたいんですけれども、学校ニーズに対し柔軟性のある計画というのをもう一度具体的に教えていただければと思うんです。そういう意味での騒音とか、そういう今ちょっと具体的なことを話しましたけれども、どういう近隣住民に対する配慮なんですか。","respondent":"市川庶務課長","answer":"それとあともう一つは、やはり普通教室以外のスペース、多目的教室とか、その辺がやはり学校の中で学年ごと、あるいはクラスごとのさまざまな学習計画に対応できるような、文字どおり柔軟性。","voiceIndex":170,"id":"exchange-065"},{"speaker":"山内委員","kind":"質問","question":"最初のほうの多目的教室というのは、私も伊藤学園の開校のときにお邪魔させていただいたので、あのような形の間仕切り、要はああいうふうな形ということでしょうか。","respondent":"市川庶務課長","answer":"これはどちらがいいのかというのは、まだ試行錯誤の段階ですけれども、その辺は学校の意見、現場の意見を十分参考にしながら、設計に当たっていきたいというふうに考えてあります。","voiceIndex":172,"id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"そうすると、これは、この外観イメージからすると、削っちゃうのかもしれないと思ったんですが、そういうイメージで工事がなされるんでしょうか。いかがでしょうか。","respondent":"市川庶務課長","answer":"要は小学校と中学校の校舎を全部壊しまして、その丘の直下というんですか、すぐ擁壁の真下のところに新しい校舎を建ちあげるというイメージです。ですから丘の上に建てるわけではありません。","voiceIndex":174,"id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"わかりました。そうすると、擁壁というか、それを背にするというか、すごく日当たりが悪くないですか。そうすると幼保エリアと体験学習エリアになっているところが日当たりが悪くなっちゃう、幼保エリアのところにこれがつくられていけば、通常の保育棟と考えると前面のほうがいいのではないかなというのが、それがどうなのかなというところですね。","respondent":"市川庶務課長","answer":"日当たりに関係しては、こちらのこのイメージが、こちら側の建物は、当然、上が北ですけれども左側の校舎は４階建て、それからこの飛び地につくられます幼保エリア、それから体験学習棟、これは２階建てですので、幼保についての日当たりについては。","voiceIndex":176,"id":"exchange-068"},{"speaker":"石田（慎）委員","kind":"質問","question":"このプロポーザル条件の中で、経済体験学習棟というのは、詳しくどのような施設になる予定なのかというのを伺います。","respondent":"河野指導課長","answer":"今回、来年４月に八潮南小学校、中学校のほうに、再来年４月に開校する八潮地区の小中一貫校が工事の関係で１年間入る予定になっておりますが、この品川地区の小中一貫校を整備する際に、最終的には八潮南小学校のほうも空き施設になりますので、管理上等の問題もありますので。","voiceIndex":178,"id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"すまいるスクールについては十分確保していきたいという先ほどのご答弁だったので、それはそれで、今の時点では了解なんですけれども、私が申し上げたい趣旨というのは、１教室ではなくて、やっぱりいろいろな子どもが静かに過ごしたい、そういうスペースが確保できるということも含めた十分な施設ということで申し上げたので、庶務課長の先ほどのご答弁では、そこが非常にファジーだったので。","respondent":"市川庶務課長","answer":"一方で、校舎の改築計画を担当する課長の立場になれば、全体の中でのバランスには、やはり留意せざるを得ないという状況で説明をさせていただいたものです。","voiceIndex":180,"id":"exchange-070"},{"speaker":"南委員","kind":"質問","question":"幼保一体化と、調理室については了解します。すまいるスクールについても、私も、当然そのことを前提として質問しております。しかしながら、既存のすまいるスクールのところで必ずしも十分ではないという現状もありますので、新しくできるところですから、最大限の考慮、配慮をしていただければという意味で申し上げましたので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-071"}]},{"id":"topic-06","title":"八潮北小学校の施設活用","agenda":"八潮北小学校の施設活用","exchanges":[{"speaker":"南委員","kind":"確認","question":"八潮地域は全体が避難場所となっているので、何かあったときには、給食室の設備がそのままだと思うんですけれども、とりわけ八潮北小学校は防災倉庫になるという説明でしたけれども、非常時には、そういう対応が可能であってほしいという意見も地域からかなり出ておりますので、その辺についてはどういうふうに考えているのか、改めて、学校施設、区民の共有財産というところもあるし。","respondent":"市川庶務課長","answer":"２点目の、先ほど、私、ちょっとまた説明が漏れちゃったんですが、従来の学校避難連絡所としての機能については、この施設は基本的には継承していくということで、新しい施設管理者になる明晴学園と、今後についていろいろ調整してまいります。","voiceIndex":188,"id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"二つの問題とも非常時の対応ですけれども、ぜひきちんと対応していただきたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-073"},{"speaker":"西本委員","kind":"提案","question":"それぞれ状況が違う環境下にありますので、その調整といいますか、明晴学園は私立になりますし、マイスクール八潮は公立でありますので、そこの意見調整みたいなものとか、うまくいい関係を持っていけばと思っているんですけれども、全然事情が違う中でどういうふうにやっていくのかなという調整は、どのようにされていくのでしょうか。","respondent":"古里学務課長","answer":"ご心配の点がないように、二つの学校が一つの屋根の下にいて、双方の子どもたちにいい影響が出るような運営を心がけていくようになっていくと考えています。","voiceIndex":191,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"いい機会だと思いますので、調整会議できめ細かい調整をしていただきたいと思います。そのためにちょっと確認ですが、マイスクール八潮も１階の体育館を使いますよね。そうすると、移動は、明晴学園の中を通ってという形になるんですか。それとも、外から入って行く形ですか、どちらでしょうか。","respondent":"古里学務課長","answer":"私立学校としての学校法人としての許可の段階では、双方の子どもたちが入り交じって、安全に障害がないようにということで仕切ることを厳しく指導されておりますけれども、日常の活動においては、双方の関係者にとっては、あまり意味がないことだと考えています。","voiceIndex":193,"id":"exchange-075"},{"speaker":"石田（慎）委員","kind":"質問","question":"黄色い部分の教育委員会倉庫なんですが、これは、小中一貫校の工事にあたっての倉庫ということですか。もしそうであれば、その後はどのような活用法になるかということです。もしそうであれば、以前にも、ここは学校避難所になっていたので、そのときに防災倉庫というのが存在していたと思うんですが、それはどうしたのかということを教えていただけますか。","respondent":"古里学務課長","answer":"この後の跡地活用の問題については、また地域、それから、跡地活用の基本的な検討の責任所管は企画課となりますので、学校を中心にして地域の声を聞きながら、使用方法について検討を進めていくことになろうかと思います。","voiceIndex":195,"id":"exchange-076"},{"speaker":"石田（慎）委員","kind":"質問","question":"もしするんであれば、また次に違う活用をするときに、また工事をしなきゃいけないというと二重になってしまうので、非常にもったいないなと思いで質問させていただいたんですが、いかがでしょうか。","respondent":"市川庶務課長","answer":"その点、私のほうからお答えします。今回、実施いたします改修工事は、当面使い方として必要な部分、具体的に言いますと、明晴学園とマイスクール八潮については、来年４月から待ったなしに使うわけですので、その使用ニーズに応じた改修をいたします。","voiceIndex":197,"id":"exchange-077"}]},{"id":"topic-07","title":"平成２０年度小学校新１年生・中学校新７年生希望申請結果","agenda":"平成２０年度小学校新１年生・中学校新７年生希望申請結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"抽選になっているところですが、例年の傾向ですと、抽選で漏れてしまうというところをどうするんでしょうか。例えば中学校ですと、私立中学校に行くというケースがあると思うんですが、それで漏れてしまったというところはあるんでしょうか。","respondent":"古里学務課長","answer":"小学校につきましては、私立の進学率がそれほど高くはございませんので、抽選の結果、繰り上げ入学が図れない子どもたちがかなりの数、出てくるという状態になるかと考えています。","voiceIndex":205,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"中学校は全員が受け入れられる可能性があるんじゃないかということで、小学校はほかにということですが、そういう状況があるんだということは、保護者の皆さんの認識がどれぐらいあるのかと思うんです。それとも、最終的にぎりぎりのところまで頑張っておられる方がいて、申請が困難になるという事実があるのか、どうか、その状況はいかがでしょうか。","respondent":"古里学務課長","answer":"抽選で繰り上げにならなかった児童、生徒については、基本的には学区の学校に一たん戻して、就学指定通知を行います。その後、１月に入りますが、その就学指定通知を受領した後に、再度、指定校変更という手続があります。","voiceIndex":207,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"指定校変更して、またそこで入れなかった場合、転々とするという傾向はないんでしょうか。そうすると、教員の発令に影響してしまったりとかすることがあって、かなり混乱するケースが増えるかと思うんですが、どうですか。２月の、小学校の私立とか、国立の受験はいつかわからないんですけれども、それが終わったあたりで締めるとか、そういう形に早めるということはできないんでしょうか。","respondent":"古里学務課長","answer":"ただ、最終的な変更は、要するに転入してくる児童・生徒についても、現実的には３月３１日まで受け付けておりますので、既に居住していた子どもについても、相応な事情がある場合は、３月末まで丁寧に対応していくということで検討しております。","voiceIndex":209,"id":"exchange-080"}]},{"id":"topic-08","title":"品川区立学校の管理運営に関する規則の一部改正","agenda":"品川区立学校の管理運営に関する規則の一部改正","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ここには４月１日実施と書いてあるんですけれども、ちょっと私もよくわからないので、来年度の４月１日は、とりあえず主任教諭の部分では実施ではなく、先送りというんですか、実施時期を先送りするみたいな状況のように聞いたんですけれども、その辺は、品川区としての判断で、そういう実施時期をお決めになったのか。全体とのかかわりの中で、どうなのか、ちょっと教えていただきたい。","respondent":"河野指導課長","answer":"この施行について、平成２０年４月１日ということになっておりますが、東京都の教育委員会のほうで、都立学校の管理運営規則の改定を行った際には、来年４月１日から、統括校長および主任教諭、主任養護教諭の配置を開始するという予定で進めておりました。","voiceIndex":216,"id":"exchange-081"},{"speaker":"南委員","kind":"確認","question":"最後のところを、ちょっと確認ですけれども、手続がおくれているので、選考は平成２０年度中に、そして配置は平成２０年４月１日ですか。","respondent":"河野指導課長","answer":"平成２１年です。","voiceIndex":218,"id":"exchange-082"},{"speaker":"南委員","kind":"質問","question":"わかりました。あるいは、選考があるわけですから、ちょっとその辺が。その学校自体も、特色ある新しいタイプの学校、研究校等々、統括校長の設置についてと書いてある(1)の考え方と、品川区でやっている独自の教育の特徴というんでしょうか、そういう部分とどういうふうにリンクして考えればいいのかというのが、今ひとつとれなかったので教えてください。","respondent":"河野指導課長","answer":"当然、品川区立の小・中学校は、品川区教育委員会の所管ですので、東京都教育委員会のほうから、統括校長配置校ということで品川区内の学校を挙げなさいという指示がまいれば、当然のことながら、私どもは、まず小中一貫校を、統括校長配置校ということで申請をする予定です。","voiceIndex":220,"id":"exchange-083"},{"speaker":"南委員","kind":"質問・要望","question":"規則の改正の報告事項であるので、ここで賛成だとか、反対だとか、なかなかそれは言いがたい場面なのかなと思いながら聞いているんですけれども、しかし、当該の教員の方々の身分にかかわることなので、そこを組合なり、そういう組織のところで了解されているのであれば、外からどうこう言う中身にはならないと思うんですけれども、ちょっとその辺がどうなのかということを、１点教えていただきたい。","respondent":"河野指導課長","answer":"ただ、現行法で言うと、そういう教員も含めて、ほんとうに一生懸命子どものために、あるいは学校組織の活性化のために頑張っている教員も、手を抜いている教員も、全く同じ処遇であるということに対しては、今回、このような新しい職務の設置によって。","voiceIndex":222,"id":"exchange-084"},{"speaker":"南委員","kind":"質問","question":"したがって、どの先生でも、好きで選んだ職業ですから、自信を持って、自負を感じながら一生懸命仕事をしておられると見ておりますので、ちょっとその辺の、そういう表現というのは適切ではないのではないのかなと思いました。そのことをちょっとつけ加えて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-085"},{"speaker":"西本委員","kind":"質問","question":"例えば、学校によって、何とか先生とか、何とか校長先生ということで統括校長ということになるんですかね。もう一つは、どこがいいですかと聞かれるのかどうか、わかりませんけれども、品川区教育委員会が指定をするんでしょうけれども、今は小中一貫校ということですが、将来にわたって考えていくと、おそらく、一貫校は一貫教育をやりやすい環境だと思っているんです、私自身としては。","respondent":"河野指導課長","answer":"実際に教育課程の実施ということで考えた場合に、例えば品川区は小中一貫教育をやっていて、教育課程の実施だけならば、確かに小中一貫校のほうがやりやすくて、連携型の学校のほうがやりづらいという課題もあります。","voiceIndex":225,"id":"exchange-086"},{"speaker":"西本委員","kind":"質問","question":"統括校長が、小中一貫校に統括校長として配置されるんですよね。学校は、Ａ先生がもう異動になったとしますよね。そうすると、このＡ先生が異動した学校というのは指定校になるんですか。Ｂ先生が小中一貫校に来れば、Ｂ先生が統括校長という形になるんですか。そうすると、どんどん増えていくのかなと。","respondent":"河野指導課長","answer":"したがって、統括校長でなければ、統括校長配置校には着任できないという中身です。","voiceIndex":227,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"よく見えてこないんですけれども、そうすると、要は、統括校長設置校は、今後、明らかになってくるわけですよね。ほかのところからも、そういう人たちがいっぱいいるので、品川区内だけではないですけれども、学校間の力ぐあいが固定化する、ある程度見えてしまう、東京都の考え方でいくと、その学校が期待できるというふうに指定されちゃうということになるんではないでしょうか。","respondent":"河野指導課長","answer":"いろいろな見方がございまして、先ほどの私の説明でご理解いただけたと思うんですけれども、品川区のように、普通の学校の校長先生に比べて、小中一貫校の校長先生は確かに大変なんだなということが、どなたにもご理解いただける学校に対しては。","voiceIndex":229,"id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4618#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":86243,"voices":235}},{"id":"h19-20071126-5","meetingId":"h19-cm11","date":"2007年11月26日","dateIso":"2007-11-26","committee":"総務委員会","time":"午前１０時０２分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"もし随意契約の形式をとるということがある程度想定できるとすれば、どうしてその２工事、その３工事と分けていかなくちゃならないのか、その辺をちょっと、何か法的規制があるのかどうかということも含めて理由を教えていただきたいのと、それと随意契約の金額そのものが８億円を超えるという大変大きな工事なんですけれども。","respondent":"家壽田下水道河川課長、中島経理課長","answer":"今、委員ご指摘のことですけれども、区といたしましても、今回の工事というのは、その２とその３というのは一体のものですので、当然我々としても１本の工事として出したいということを東京都のほうに要請してまいりました。随意契約の金額が８億円を超えるという委員のお話ですけれども、契約につきましては競争入札、指名競争入札、随意契約等ありますけれども。","voiceIndex":7,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"随意契約ですから、一般競争入札みたいなときに出す積算した額というのは出ていませんよね。８億幾らというこの値段というのは、ＪＶのほうから出てくるものなのか、それとも区側というか都というか、示される金額になるのか、その辺をお聞かせ願えますか。","respondent":"中島経理課長","answer":"通常の工事請負契約でもそうですが、予算が当然先にありまして、事業を契約する前の起工といいまして、工事全体でどのくらいの額の工事になるのかというのを、積算書に基づきまして起工額を算出いたしまして、当然その額を基本として、それ以下の額でもってやるということで。","voiceIndex":10,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"幾らで受けてくれるかというのは、示した金額に対して幅があるという意味合いなんですか。例えば積算の中で、区なり都なりが積算したものが例えば８億円だとすると、それにプラスアルファ、ＪＶの値段として、話し合いの中では歩み寄らざるを得ないという金額の設定の仕方ということですか。","respondent":"中島経理課長","answer":"基本になってあります。それで私ども契約する場合、通常の入札でもそうですけれども、なるべく低い額でもって私どもが仕様で求めている工事をしてもらうというのが基本になってありますので、私どもとすれば上限を押さえた中で契約をしているです。","voiceIndex":12,"id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"民間のマンション建設でも非常に水のたまるエリアになっていまして、今回シールド工法ということだものですから、さほどは影響はないのかなとは思うんですけれども、まずこの鮫洲のほうの幹線に接合されていく、東京都とのつなぎについてお教えいただければと思うんですが。","respondent":"家壽田下水道河川課長","answer":"これも開削工法でやりますと大変周辺の地盤に影響が出るんですが、非開削工法で崩れるのを防ぎながら推進します推進工法という、やはりシールド工法と同じような工法がありますが、これで施工いたしますので、周辺への地盤には最小限、基本的に被害が出ないようにということで今。","voiceIndex":14,"id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"そうしますと、今のご説明からすると、山留めに関してはないという解釈でよろしいですか。","respondent":"家壽田下水道河川課長","answer":"基本的に非開削工法ですので、トンネルのところに山留めを打つということは行いません。","voiceIndex":16,"id":"exchange-005"},{"speaker":"原委員","kind":"意見","question":"非常にありがたい工事なんですけれども、というのは私は五反田に住んでおりまして、いつも一番強烈なのは、テレビの全国版で映る場所でして、ＪＲの下ですね。非常に大都会とは思えないような状況になりますので、ちょっと１点、この線を見ますとかなり折れていますよね。以前にご説明をいただいたかと思うんですけれども、もう少し詳しくいただければと思いますが。","respondent":"家壽田下水道河川課長","answer":"３ページ目のところの青い点線のところに、コの字型といいますか、２回右に曲がって左に曲がるというところがありますが、これはここのところは都道の下をくぐるためにやむ得ず急カーブをしているところでございまして。","voiceIndex":18,"id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"ご説明は非常にわかりやすいんですけれども、１点ちょっと心配なことは、意外と前回なんかもあったような話を聞くんですが、かなりの勢いで、後が問題で、マンホール等々が飛ぶ場合があると。これは非常に少々飛ぶんではなくて、かなりの勢いでそういった事故が発生するということがあるものですから、その辺の対処方法等、いろいろなことが何かありましたら教えていただきたいと思うんですけれども。","respondent":"家壽田下水道河川課長","answer":"現在つくりますシールド工法でつくるトンネルにつきましては、その辺もこれまでの経験をもとに、しっかり空気抜きといった対策を行っております。そのためマンホールが飛ぶということで区民の皆様方に事故を負わせるようなことがないように、そんな対処をしっかりやっております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"土井委員","kind":"意見","question":"この構造からいくと、この工事が終わると、ある意味では一定の区切りの中で供用、使うことが可能になるのではないかと思えるんですけれども、というのは、いわゆる貯水管として、そういう構造だと思うんですが、そこら辺はどのように計画されていますか。","respondent":"家壽田下水道河川課長","answer":"その工事につきましては、その３工事の次のその４工事で実施するようになっております。その４工事を実施しました暁には、１日も早く取り込めるような工夫をしてまいりたいと考えています。","voiceIndex":22,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"契約の件なんですけれども、その２工事がほぼめどがついていると思うんですけれども、例えばその３の随意契約をするにあたって、過去の、例えば人災とかそういうのは多分なかったと思うんですけれども、そのような経験上のことで業者を指導するとか、そういう契約にフィードバックできるようなことというのがあったのか、なかったのか、あればどういうことがあったのか教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"武内副委員長","kind":"質問","question":"１点だけ、勘違いしているとあれなので指摘しておきますが、目黒川のちょっと上流のほうに雨水調節池でしたっけ。そうすると、調節池のほうの役割というのは、それはそれであるんだけれども、それを許容量を超えちゃっているんだという判断なんでしょうか。この工事自体の目的というか。","respondent":"家壽田下水道河川課長","answer":"今、副委員長ご指摘の、目黒川には２カ所河川の調節池がございまして、それはうちの区内の荏原調節池、それから目黒区内の船入場調節池です。","voiceIndex":27,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問","question":"何点かお伺いしたいんですが、私は先ほど人事課長から説明いただいたこの中に書いてある、平成２０年度から土地収用事務において専門的知識を有する職員をということですけれども、これは当然今までこの仕事を区でやっていらっしゃったと思うんですけれども、あえてそれを必要とする内容は具体的に何なのかということをまずお伺いしたいというのが１つ、まずそれをお聞かせください。","respondent":"榎本人事課長","answer":"これは土地収用の部分で、特に今、都市計画道路の部分が進んでいるところで、かなり困難な事例に当たっておりまして、一定程度までは今までの職員で進んだんですけれども、最後の胸突き八丁あたりのところがさらに後押しした上で。","voiceIndex":39,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"確認","question":"つまりこういうことについて長年経験していらっしゃる職員がいる。場合によってはそういう民間の力を導入したらどうかということを質問した記憶があるので、あえて質問するんですけれども、やっぱり公務員であるがゆえの立場というのももちろんあるんでしょうけれども、１つ踏み出したのかなという思いが今しておりますので、個別的なことは別として、その確認をしたいと思います。","respondent":"榎本人事課長","answer":"２点目の他の分野の部分ですけれども、この条例の規定を整備する段階では、今現在はこの土地収用の分野だけを考えておりまして、今後またさらに活用できる分野があれば、その都度、この条例が制定されていれば、今度は人事委員会での承認だけでスタートできますので。","voiceIndex":41,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今、職の設置ができるかどうかという確認をするというお話をいただきましたけれども、確認なんですけれども、職の設置をするのは品川区じゃないんですか。だと思うんですけれども、それを人事委員会で承認していくかどうかということなんでしょうかということが１つと、それから例えば品川区がこういう職を採りたいということがあったとして、人事委員会に相談する、報告するでしょう。","respondent":"榎本人事課長","answer":"最初の職の設置の部分です。ちょっと説明不足で済みません。","voiceIndex":43,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これで最後にしますけれども、例えばこういうことをこれから具体的に展開していくにあたって、わかりやすいもの、例えばＩＴ関係のところとか、民間はどんどん進んでいる。それに基づいて行政がシステムを設計していくということが当然だと思うんですけれども、そういう方々をいざ採用する段階にあたっての、その方の技量を測定するノウハウが新しく求められてくると私は思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"午前中の説明のときに、法律の第３条ということの部分ということでお話がありましたけれども、ちょっと私も法律を見させていただいたら、法律そのものがいろいろな部分にかかっていますけれども、一部だけをこの条例に引くという理由のところをちょっとお聞かせ願いたいのと、それから専門的な知識、専門性というんですかね。","respondent":"榎本人事課長","answer":"それから専門性のもう少し具体的な事例ということですけれども、行政についての専門性はずっと蓄積はしてきているんですが、やはり今後の団塊の世代の退職を迎える中で、やはり専門性を維持継続、さらに発展させるとか、さらに技術革新がかなり進んでいる部分もありますので。","voiceIndex":46,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"今の高度な専門性というお話があって、条例そのものも育成に相当の期間がかかるとかという文章がありますけれども、そもそも行政ですから、ずっと長い間、品川区の行政そのものが続けられてきて、蓄積されたいろいろな経験ですとか知識があって、その上に立って今、部長や課長たちのように一定の経験をしながら、必要な行政知識を身につけていかれるんだと思うんですけれども。","respondent":"榎本人事課長","answer":"２点目の継続性の問題ですけれども、やはりトップの管理職の部分は任期がついておりますけれども、その下を支える職員につきましては、もちろんそのノウハウを、管理職だけで仕事をするわけではありませんので、ノウハウを持った上で、きちんと蓄積をして、次の管理職。","voiceIndex":48,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"用地担当課長という職が以前あったということであればなおさらなんですけれども、何かせっかく行政として蓄積したものを、途中で放棄したというか、そういう感じが非常にするんですけれども、ちょっとそこを教えていただきたい。どういう形でこの６級職とか８級職ですか、ここをどう採用するというのは、どこを見ればというか、教えていただきたいと思います。","respondent":"榎本人事課長","answer":"一般職については平成１９年４月、今年の４月から制度導入をやったということですけれども、今のところ設置事例はないということで、法律に基づいたこういう制度を導入するということ、それから給与制度に絡んできますので。","voiceIndex":50,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"最後にちょっと、今の規則のところなんですけれども、規則という形式であれば、条例の中身になければ、規則そのものであれば、いつでも変えていけるということなんですよね。要は今回のように議会に報告があったりとかということではなくて、規則部分はその中でいつでも変えられるという形式になっているということなんでしょうか。","respondent":"榎本人事課長","answer":"その規則の部分のところなんですが、制度導入にあたっては、２３区の課長会の中で、人事担当課長会の中で、どこまで制度ができるのかということで想定した場合に、給与体系等、共通な部分が崩れないかどうか。","voiceIndex":52,"id":"exchange-018"},{"speaker":"土井委員","kind":"質問・要望","question":"これをどう規定するかというのは、法律なんかで書ける代物であるような、ないようなものですよね。だから、そこら辺をだれが最終的にどう判断をするのかなと。それからもう１つは、これからこの新しい採用の仕方という形で、任期付の職員で管理職が入っていらっしゃるわけですけれども、このことと議会との関係というのはどういうふうになるんでしょうか。","respondent":"榎本人事課長","answer":"管理職の部分から幅がどれぐらい広がるか、今後どういうふうに広がっていくのかという部分については、区の中で人材育成基本方針等をつくって、どういうふうに人材を活用していくかというところがありますけれども、その中とその業務の範囲。","voiceIndex":54,"id":"exchange-019"},{"speaker":"土井委員","kind":"質問","question":"２つあって、今のように委員会等にも参加をしていただけるんですかという、専門性のお伺いをするときに来ていただけるんですよねという、これはごく当然だと思うんだけれども、問題は採用するとき自体に、こういう専門性のあるのをこうこうこういう思いでこの条例に基づいて採用いたしますといったとか、しますとかいうお話等が、どのレベルで議会にあるのかなと。","respondent":"榎本人事課長、桑村総務課長","answer":"専門性があるので、部署が限られているというのはあるんですけれども、実際上、例えば医師の採用等も同じような形で動いている中で、採用のときに、どの段階で議会に明らかにというか、今のところすぐ想定はできないんですが。２つありまして、１つはこういう形のもの、特に管理職を予定しておりますので、組織が絡むのは間違いないと思うんです。","voiceIndex":56,"id":"exchange-020"},{"speaker":"土井委員","kind":"質問","question":"１つ聞くのを忘れていました。でも人を採用するのに、野球の選手だって、１年契約か、２年契約か、３年契約かで大分話が違うように、相手の方との兼ね合いは当然出てくるんじゃないかと思うんですけれども、そういう形もあり得るんですかね。任期について。５年以内で、まさか１年もしないようなのはないだろうと思うんですけれども、そこら辺はどうお考えなっているのかというのが１つですね。","respondent":"榎本人事課長","answer":"その任期を更新する場合には、条例の第３条のほうに、任期の更新の中に、当該職員の同意を得なければならないということで、相手の同意が前提となっておりますので、同意を得た上で、５年の範囲内であれば延長ができるという形です。","voiceIndex":59,"id":"exchange-021"},{"speaker":"土井委員","kind":"質問","question":"逆の話。いい人を採用しようとしたら、民間とかそういうところから引っこ抜く形になるわけですよね。そうすると、そのためには、３年契約にしてもらわないとちょっと行きたくないなとかいう話にならないかということなんです。そういうのは交渉とか何かで決まるのかなという気もしたものですから、伺ってみたんです。それだけです。","respondent":"榎本人事課長","answer":"ただ短いのですと１年とかというのもあるんですけれども、それはそれなりにそれぞれ事情があってという形になりますが、大体３年が目安として採用されているというのが実態のところです。私のほうもほぼ３年程度を目安にやっていくというのが基本的な考え方だなと考えております。","voiceIndex":61,"id":"exchange-022"},{"speaker":"原委員","kind":"質問","question":"いろいろなケースが今後いろいろ出てきて、まだいろいろとはっきりしていない部分がおありだと思うんですけれども、今回に関しては土地収用事業ということで、高度な知識ということで、民間というものを想定されているようなんですけれども、多分現実には土地収用法とか、さっき出た税金の問題ですとか、土地の評価システムの問題とか、そうすると、国交省とか国交省の関連とか、都の土地開発公社ですとか。","respondent":"榎本人事課長","answer":"ほかの団体のＯＢ等、要は品川区でもって再任用できるというのは、区に属していた職員および区が参加している一部事務組合の職員という形で限られていますので、それ以外については、採用するとすれば。","voiceIndex":63,"id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"そんな関係があるので、私としてはそれが自治体として独立性を欠かないようにしてほしいという考えがあるものですから、その辺についてご意見をお聞かせいただければと思います。","respondent":"榎本人事課長","answer":"そういうＯＢの調査等は、マスコミ等の調査もありましたけれども、やはりこれはそれぞれの団体が個別に判断をして、どういうふうに人材を有効活用するのかという形になりますので、もちろん区としての判断を前提とした形で、仕事がよりスムーズに進むという前提のもとに。","voiceIndex":65,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"ですから、この考え方がそのまま条例としてでき上がっていけば、現在は土地収用事務とはいえ、この流れというのはさらに拡大をして、管理職だけではなくて、一般職員も含んでいくのではないかと思います。そもそも行政職ですから、どれをとって見ても、住民サービスというのが基本になって職種として成り立っている、機械的に進めることが可能な事務というのは、自治体には私はないと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"プールのところでお伺いしたいんですけれども、道路側のフェンス、これも工事に入ると考えてよろしいんですかということが１点と、見たところ、投光機というんですかね。照らすライトの大きいのがあったと思うんですけれども、私も初めて見てわかったんですけれども、この必要性と今後もそのままつけたままになるのかなということと、こちらがプールのことですね。","respondent":"宍戸施設担当課長","answer":"次にグラウンドですが、基本的にはダスト舗装、土舗装です。基本的には伊藤学園で使いましたものと同様と考えてございまして、特に飛散しにくくしたものということで、ダスト舗装なんですけれども、比較的今までうまくいったものを採用する予定です。","voiceIndex":77,"id":"exchange-026"},{"speaker":"井桁委員","kind":"質問","question":"陸橋の部分についてちょっとお伺いをしたいんですけれども、以前は道路を渡ってプールに、ないしは今ある仮設体育館のほうに移動する。なぜ陸橋をつくらなければいけない状況だったんでしょうか。移動するときに、雨でしたらプールはやらないと思うんですが、この屋根の部分についてお伺いをしたいと思うんですが。","respondent":"宍戸施設担当課長","answer":"それと現地での説明が不適切、不十分だったんですけれども、基本的に陸橋につきましては、屋根はつけません。一部屋根のようなものが設置されるんですけれども、これは高圧線防護板ということで、電柱のところを横切る高圧線を防護するための屋根状のものが一部つくです。","voiceIndex":79,"id":"exchange-027"},{"speaker":"井桁委員","kind":"質問","question":"ということは、移動の際にこの陸橋を使うということで、今までは道路を横断の場合は、先生がついて一緒に移動という形だったんですが、この部分になってくると、生徒が自由に行き来ができてしまうんでしょうか。それともプール等を使うときのみ開いて、そこで一緒に先生と移動という形をとるんでしょうか。","respondent":"宍戸施設担当課長","answer":"これは学校側の運用の部分になろうかと思いますけれども、やはりセキュリティについて非常に厳しい時代ですから、先生が必ずついてあたるようになるのかなと思います。","voiceIndex":81,"id":"exchange-028"},{"speaker":"井桁委員","kind":"質問","question":"先生と一緒に移動するということは、その分だけ児童にも目が届いていたと思うんですが、今後陸橋ができることによって自由に行き来ができるということは、１人で児童がプールのほうに行ってしまうような可能性も、休み時間などに自由に行き来ができるとなると、先生の目が届かないところにも児童が行ってしまうのかなという危惧があって、ちょっと１点お伺いしたかったんですが、その扉の設置とか。","respondent":"宍戸施設担当課長","answer":"建物側に扉が設置されます。それをどういうふうに運用するかというのは私は承知していないんですけれども、基本的にはセキュリティ上、非常に気を配って行き来をすることになるのではないかと推測しております。","voiceIndex":83,"id":"exchange-029"},{"speaker":"原委員","kind":"質問・要望","question":"この解体部分の工事なんですけれども、まず金額をお教えいただきたいんですけれども、解体の工事代金、金額と、平米でも坪でもいいんですけれども、約８００平米、建築屋さんが言うまるめの値段で結構なんですけれども、ざっくり、総額と平米単価というのが出たらば教えていただきたいんですが。","respondent":"宍戸施設担当課長","answer":"済みません、ちょっと総額が今出てこないんですけれども、おおむね平米２万円。","voiceIndex":86,"id":"exchange-030"},{"speaker":"原委員","kind":"確認","question":"さっき現地のほうで確認させていただいたんですけれども、これは今回、ＪＶで落とされているみたいなんですが、教育施設研究所というところが一緒に入って工事等をやられているような形をとられていると思うんですけれども、これは総務委員会ですから、お聞きしたいのは……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-031"},{"speaker":"土井委員","kind":"質問・要望","question":"２つほど。この契約の落札に対する経緯について、これは聞いておかなければならないと思いますので、経緯を聞かせていただきたいというのが１点です。ほかのところでもこんなふうにやっておられたらおもしろいんだがな、いいんだがなというところが幾つもあちこちにあるんじゃないかと思いますし、さらにまた別の見方をすれば、これが建ぺい率だとかいろいろなそういうものとの関係はどうなるのかなと。","respondent":"中島経理課長、宍戸施設担当課長","answer":"その中の１社大明建設が、落札率で言いますと９８.９％で落札したです。それとほかにもいろいろできるのかということなんですが、これは許可ですので、どうしてもということで理由も含めて認められないとなかなか実現しにくいということで、今回の場合は飛び地にプールがございまして、生徒の安全上。","voiceIndex":93,"id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"その路上協議会というものはどういうもので、どういう根拠があるものなんですか。","respondent":"宍戸施設担当課長","answer":"そこの協議内容を含めまして申請を出して、最終的には特定行政庁である品川区長が許可をする、そういう流れになってあります。","voiceIndex":96,"id":"exchange-033"},{"speaker":"土井委員","kind":"意見","question":"そういう皆さんとの調整をするための会議と理解していいのか、そうじゃなくて、区長がやるにつけても、第三者のいろいろな意見を聞かなきゃいけないから、学識経験者の１つみたいなスタイルでこういう皆さんが決まっているのか、そこら辺が知りたいんです。","respondent":"宍戸施設担当課長","answer":"今、委員のおっしゃった前者です。調整のためにいろいろ意見を聞く場と思ってあります。","voiceIndex":98,"id":"exchange-034"},{"speaker":"菊地委員","kind":"質問","question":"今、土井委員がおっしゃっていた入札経過でお聞きしたいんだけれども、今のお話だと、入札参加業者というのは３社という見方でよろしいんですか。それとも７社が入札に参加したという見方をするんですか。そこがちょっと。","respondent":"中島経理課長","answer":"難しいんですけれども、実際に札を入れた業者が３社あったということで、その間に辞退をしていますので、私どもとすれば７社から申し込みがあったと認識しているんですけれども、それが参加なのか、単に申し込みなのかといったら難しくなると思うんですけれども、いずれにしても。","voiceIndex":100,"id":"exchange-035"},{"speaker":"菊地委員","kind":"質問","question":"それはそれで幾らかの経費がかかっていくんだと思うんですけれども、こういう工事をやりますよといって値段を示したときに、閲覧的なそういう書類というのを事前に示してしまうというのは、法的に支障があるものなんですか。","respondent":"中島経理課長","answer":"ただこれは区によって扱いが変わっていまして、区によっては、例えば閲覧、見せる、図面を貸すというんですかね、そういうところもありますし、例えば今、電子入札なんかの場合に、電子でもってデータを送るということもありますし、さまざまな方法を各区考えてありますけれども。","voiceIndex":102,"id":"exchange-036"}]},{"id":"topic-02","title":"３報告事項に移ります。 商店街電線類地中化工事（戸越銀座地区）その１請負契約","agenda":"３報告事項に移ります。 商店街電線類地中化工事（戸越銀座地区）その１請負契約","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"そうすると北品川の場合は、この工事とは別に商店街負担で舗装をやっているという形なんですかね。","respondent":"日下部企画財政課長","answer":"ただそうなりますと、石畳の整備の費用というのが、通常のアスファルト舗装に比べてかなりその分の費用の問題というのが出てまいりますので、それについては地元にも一定のご負担をいただくということで調整を進めているです。","voiceIndex":119,"id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認なんですけれども、その１工事ということは、当然その２なりがあると思われますので、これは戸越銀座商店街の途中まで今はなってますけれども、その後どうなるかということの確認をいただきたいのと、あわせて聞きますけれども、もしそうであるならば、同じものでずっと通すわけじゃないですか。たまたまここが契約したけれども、一括が安いのか、わかりますよね。","respondent":"中島経理課長","answer":"戸越銀座の電線類地中化工事ですけれども、先ほどもちょっと説明したんですけれども、約１.２kmの区間を５工区に分けて実施するものです。今回その１工事ですので、最初の工事です。","voiceIndex":121,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問","question":"今の商店街の影響のことはわかりますよ。だけどこの仕様と全く同じものを、つまりやる話でしょう、将来的には。となれば、たまたま今回これを区切って発注するけれども、例えばＡさんと今度やりました。ですけれども、これは意見ですから、あくまで意見ですけれども、そういう思いがあるということだけは申し上げておきます。","respondent":"中島経理課長","answer":"先ほど申し上げましたように、平成２３年度まで長期にかかわる行程です。契約の関係ですと、債務負担の期間の問題がありますので、２年以上あるいは３年以上のものは債務負担がなかなかできないということがありますので、契約上のそういった制約もあります。","voiceIndex":127,"id":"exchange-039"},{"speaker":"土井委員","kind":"質問","question":"したがって２年ぐらいでおさまる分量に区切ってやりましょうよというは、それからこれが国や何かの補助金がつくのかつかないのかわからないけれども、そういうものが絡んでくるとますますそういう問題が起こってくるよという部分についてもあるんですよね。そのほかにあるんじゃないでしょうか。いろいろな業者さんにやってもらおうよという気持ちもあるんじゃないですか。それだけちょっと聞かせてください。","respondent":"中島経理課長","answer":"委員おっしゃるとおり、基本的には品川区内のさまざまな業者に受注の機会を持っていただくということがあります。それと一方ではそういったこともあります。そういった意味で、トータルでさまざま検討しなければならない部分があるです。","voiceIndex":129,"id":"exchange-040"},{"speaker":"武内副委員長","kind":"質問","question":"この商店街の地中化で、電柱がなくなって電線が地下に埋まる。そこから路地に入っていくと、どれくらいまで影響というか、出るのかというのを教えてもらいたい、とりあえずそれだけ。","respondent":"中島経理課長","answer":"地中化ですけれども、基本的に電柱をなくして、地下に電線をはわすということでございまして、今回の工事で言いますと、戸越銀座全体の１.２kmにつきましては、電柱が全くなくなって、電線ももちろん消えるですけれども、脇に入ったところにつきましては。","voiceIndex":131,"id":"exchange-041"},{"speaker":"武内副委員長","kind":"意見","question":"商店街から大体何ｍとか、ここではちょっとないのかもしれないので、あれば、わかればというのと、すぐとおっしゃったので、本当にすぐなのか、それとも１０ｍぐらい入るのかという影響、大体どれぐらいでしょう。","respondent":"中島経理課長","answer":"詳しく把握してございませんけれども、例えば２０５号線で地中化をしましたけれども、その例で申し上げますと、その２０５号線から入って比較的すぐ、１０ｍ程度に電柱が立っているという状況です。","voiceIndex":133,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1766#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":35161,"voices":149}},{"id":"h19-20071127-6","meetingId":"h19-cm11","date":"2007年11月27日","dateIso":"2007-11-27","committee":"区民委員会","time":"午前１０時０２分～午後０時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2504#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":2313,"voices":11}}]);
